const PLANTS=[{"s":"E","c":"Balsam fir","sci":"Abies balsamea","n":"(native populations only)","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/9906794/original.jpg","attr":"(c) Jenn Megyesi, some rights reserved (CC BY-NC), uploaded by Jenn Megyesi","desc":"Abies balsamea or balsam fir is a North American fir, native to most of eastern and central Canada and the northeastern United States.","fam":"Pinaceae","ord":"Pinales","cls":"Pinopsida","gr":"G5","sr":"S1","obs":43401,"wiki":"https://en.wikipedia.org/wiki/Abies_balsamea","inat":54261,"care":{"water":"Average","sun":["full sun"],"soil":["Sandy Loamy"],"cycle":"Perennial","growth":"Low","zone":{"min":"3","max":"6"},"attracts":["Squirrels"," Birds"],"prop":["Seed Propagation","Cutting","Layering Propagation","Grafting Propagation","Air Layering Propagation"]}},{"s":"SC","c":"Virginia copperleaf","sci":"Acalypha virginica","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/5/5c/Acalypha_virginica_Arkansas.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Acalypha virginica, commonly called Virginia threeseed mercury or Virginia copperleaf, is a plant in the spurge family (Euphorbiaceae). It is native to the eastern United States. It is found in a variety of natural habitats, particularly in open woodlands and along riverbanks. It is a somewhat weedy species that responds positively to ecological disturbance, and can be found in degraded habitats such as agricultural fields.","fam":"Euphorbiaceae","ord":"Malpighiales","cls":"Magnoliopsida","gr":"G4","sr":"","obs":0,"wiki":"https://en.wikipedia.org/wiki/Acalypha_virginica","inat":""},{"s":"E","c":"Sandplain agalinis","sci":"Agalinis acuta","n":"","ext":false,"fed":"E","img":"https://upload.wikimedia.org/wikipedia/commons/d/d9/Agalinis_acuta_at_Trustom_Pond_NWR.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Agalinis acuta is an annual hemiparasitic plant native to Maryland, Massachusetts, Rhode Island, Connecticut, and Long Island, New York. Common names include sandplain gerardia and sandplain false foxglove. It is one of about 70 species that comprise genus Agalinis. It currently resides within the family Orobanchaceae, but historically was aligned with members of the Scrophulariaceae. This was one of several re-alignments that were the consequence of the disintegration of the Scrophulariaceae as the result of conclusions based on molecular phylogeny data from the chloroplast genome. While historically regarded as a separate species, molecular phylogenetic data indicates that Agalinis acuta should be consolidated as part of the species Agalinis decemloba.","fam":"Orobanchaceae","ord":"Lamiales","cls":"Magnoliopsida","gr":"G1","sr":"S1","obs":0,"wiki":"https://en.wikipedia.org/wiki/Agalinis_acuta","inat":""},{"s":"E","c":"Yellow giant hyssop","sci":"Agastache nepetoides","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/152641959/original.jpg","attr":"(c) jfaupel, all rights reserved, uploaded by jfaupel","desc":"Agastache nepetoides, commonly known as yellow giant hyssop, is a perennial flowering plant native to the central and eastern United States and Canada. It is a member of the Lamiaceae (mint) family.","fam":"Lamiaceae","ord":"Lamiales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":3535,"wiki":"https://en.wikipedia.org/wiki/Agastache_nepetoides","inat":129634,"care":{"water":"Average","sun":["full sun","part sun/part shade"],"soil":["Clay"," Sand"," Loam"],"cycle":"Herbaceous Perennial","growth":"Low","zone":{"min":"2","max":"8"},"attracts":["Butterflies"],"prop":["Division","Cutting","Seed Propagation","Layering Propagation"]}},{"s":"E","c":"Purple giant hyssop","sci":"Agastache scrophulariifolia","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/4837675/original.jpg","attr":"(c) Megan Sebasky, some rights reserved (CC BY-NC), uploaded by Megan Sebasky","desc":"Agastache scrophulariifolia, also known as the purple giant hyssop, is a perennial plant that grows throughout the United States and northern Ontario, Canada. Its name comes from the similarity of its leaves to plants of the genus Scrophularia. It is a beneficial plant to pollinators and is noted for its medicinal properties, as many plants in the mint family are. It tends to grow in disturbed or open areas where it does not have to interact with non-native competitive plants.","fam":"Lamiaceae","ord":"Lamiales","cls":"Magnoliopsida","gr":"G4","sr":"S1","obs":2608,"wiki":"https://en.wikipedia.org/wiki/Agastache_scrophulariifolia","inat":158084},{"s":"E","c":"Small white snakeroot","sci":"Ageratina aromatica","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/506374/original.jpg","attr":"(c) Milo Pyne, all rights reserved","desc":"Ageratina aromatica, also known as lesser snakeroot and small-leaved white snakeroot, is a North American species of plants in the family Asteraceae. It is widespread and common across much of the eastern and southern United States from Louisiana to Massachusetts, as far inland as Kentucky and Ohio.","fam":"Asteraceae","ord":"Asterales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":1262,"wiki":"https://en.wikipedia.org/wiki/Ageratina_aromatica","inat":158107},{"s":"T","c":"Short-awned meadow-foxtail","sci":"Alopecurus aequalis","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/63324314/original.jpeg","attr":"no rights reserved, uploaded by \u8449\u5b50","desc":"Alopecurus aequalis is a common species of grass known as shortawn foxtail or orange foxtail. It is native to much of the temperate Northern Hemisphere from Eurasia to North America. It is most commonly found in areas near fresh water, such as the margins of ponds and ditches.","fam":"Poaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":3820,"wiki":"https://en.wikipedia.org/wiki/Alopecurus_aequalis","inat":75381},{"s":"SC","c":"Sea-beach amaranth","sci":"Amaranthus pumilus","n":"","ext":true,"fed":"T","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/10621979/original.jpeg","attr":"(c) wsimmons, some rights reserved (CC BY-NC), uploaded by wsimmons","desc":"Amaranthus pumilus, the seaside amaranth or seabeach amaranth, is a species of amaranth. This annual plant is now a threatened species, although it was formerly scattered along the eastern coast of the United States, its native range.","fam":"Amaranthaceae","ord":"Caryophyllales","cls":"Magnoliopsida","gr":"G2","sr":"SH","obs":335,"wiki":"https://en.wikipedia.org/wiki/Amaranthus_pumilus","inat":158252},{"s":"T","c":"Bog rosemary","sci":"Andromeda polifolia var. glaucophylla","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/204113206/original.jpg","attr":"(c) Jari Kontiokorpi, some rights reserved (CC BY-NC), uploaded by Jari Kontiokorpi","desc":"Andromeda polifolia, common name bog-rosemary, is a species of flowering plant in the heath family Ericaceae, native to northern parts of the Northern Hemisphere. It is the only member of the genus Andromeda, and is only found in bogs in cold peat-accumulating areas. Andromeda glaucophylla is a synonym of A.\u00a0polifolia var. latifolia.","fam":"Ericaceae","ord":"Ericales","cls":"Magnoliopsida","gr":"G5","sr":"S3","obs":15761,"wiki":"https://en.wikipedia.org/wiki/Andromeda_polifolia","inat":119892},{"s":"SC","c":"Sharp-lobed hepatica","sci":"Anemone acutiloba","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/2/26/Sharp-lobed_Hepatica_%28Hepatica_acutiloba%29_-_Flickr_-_Jay_Sturner_%281%29.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Hepatica acutiloba, the sharp-lobed hepatica, is a herbaceous flowering plant in the buttercup family Ranunculaceae. It is sometimes considered part of the genus Anemone, as Anemone acutiloba, A. hepatica, or A. nobilis.","fam":"Ranunculaceae","ord":"Ranunculales","cls":"Magnoliopsida","gr":"G5","sr":"S2","obs":0,"wiki":"https://en.wikipedia.org/wiki/Hepatica_acutiloba","inat":""},{"s":"T","c":"Canada anemone","sci":"Anemone canadensis","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/d/d2/Anemone_canadensis.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Anemonastrum canadense, synonym Anemone canadensis, the Canada anemone, round-headed anemone, round-leaf thimbleweed, meadow anemone, windflower, or crowfoot, is a herbaceous perennial flowering plant in the family Ranunculaceae. It is native to moist meadows, thickets, streambanks, and lakeshores in North America, spreading rapidly by underground rhizomes. It is valued for its white flowers.","fam":"Ranunculaceae","ord":"Ranunculales","cls":"Magnoliopsida","gr":"","sr":"","obs":0,"wiki":"https://en.wikipedia.org/wiki/Anemonastrum_canadense","inat":""},{"s":"E","c":"Sea-coast angelica","sci":"Angelica lucida","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/293983117/original.jpeg","attr":"(c) botanicum-vitae, all rights reserved","desc":"Angelica lucida is a species of angelica known by the common names seacoast angelica and sea-watch. It is also one of many species in the celery family which are casually called wild celery.","fam":"Apiaceae","ord":"Apiales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":3139,"wiki":"https://en.wikipedia.org/wiki/Angelica_lucida","inat":75453},{"s":"SC","c":"Hairy angelica","sci":"Angelica venenosa","n":"","ext":true,"fed":"","img":"https://static.inaturalist.org/photos/8928651/original.jpg","attr":"(c) jtuttle, all rights reserved, uploaded by jtuttle","desc":"Angelica venenosa is a species of flowering plant, known as hairy angelica, in the family Apiaceae. It is native to the Eastern United States where it ranges from the East Coast to the Ouachita Mountains. It is most often found in open, acidic areas. In the Midwest, its habitat includes prairies and savannas.","fam":"Apiaceae","ord":"Apiales","cls":"Magnoliopsida","gr":"G5","sr":"SH","obs":1625,"wiki":"https://en.wikipedia.org/wiki/Angelica_venenosa","inat":158382},{"s":"SC","c":"Field pussytoes","sci":"Antennaria howellii ssp. petaloidea","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/241000180/original.jpeg","attr":"(c) Andy Fyon, some rights reserved (CC BY-NC), uploaded by Andy Fyon","desc":"Antennaria howellii, the everlasting or Howell's pussytoes, is a North American species of plant in the family Asteraceae. It is native to northern Alaska, much of Canada including the Arctic territories, and the northern United States as far south as northern California, Colorado and North Carolina.","fam":"Asteraceae","ord":"Asterales","cls":"Magnoliopsida","gr":"G5","sr":"SNR","obs":5646,"wiki":"https://en.wikipedia.org/wiki/Antennaria_howellii","inat":75463},{"s":"SC","c":"Puttyroot","sci":"Aplectrum hyemale","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/203370024/original.jpeg","attr":"(c) Robby Deans, some rights reserved (CC BY-NC), uploaded by Robby Deans","desc":"Aplectrum hyemale is a species of orchid native to the eastern United States and Canada, from Oklahoma east to the Carolinas and north to Minnesota, Ontario, Quebec and Massachusetts. It is particularly common in the Appalachian Mountains, the Great Lakes Region, and the Ohio and Upper Mississippi Valleys. Isolated populations are also reported from Arizona.","fam":"Orchidaceae","ord":"Asparagales","cls":"Liliopsida","gr":"G5","sr":"SH","obs":12261,"wiki":"https://en.wikipedia.org/wiki/Aplectrum","inat":123188},{"s":"E","c":"Dwarf mistletoe","sci":"Arceuthobium pusillum","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/10127975/original.jpg","attr":"(c) thesnaguy, some rights reserved (CC BY-NC-SA), uploaded by thesnaguy","desc":"Arceuthobium pusillum is a perennial, obligate parasitic plant in the sandalwood family. Its common names include Dwarf mistletoe or Eastern dwarf mistletoe. It is one of the most widespread dwarf mistletoes within its range which covers the eastern United States and Canada, from Saskatchewan to Nova Scotia and New Jersey. The species name \"pusillum\" derives from Latin \"pusillus\", meaning very small.","fam":"Viscaceae","ord":"Santalales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":981,"wiki":"https://en.wikipedia.org/wiki/Arceuthobium_pusillum","inat":158562},{"s":"SC","c":"Dragon's-mouth","sci":"Arethusa bulbosa","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/41200137/original.jpg","attr":"(c) Nate Martineau, some rights reserved (CC BY-NC), uploaded by Nate Martineau","desc":"Arethusa bulbosa, commonly called dragon's mouth orchid, is the only species in the orchid genus Arethusa. The genus is named after a naiad of Greek mythology. This monotypic genus is abbreviated Aret in trade journals.","fam":"Orchidaceae","ord":"Asparagales","cls":"Liliopsida","gr":"G5","sr":"SH","obs":2590,"wiki":"https://en.wikipedia.org/wiki/Dragon's_mouth","inat":53042},{"s":"SC","c":"Needlegrass","sci":"Aristida longespica var. geniculata","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/24429938/original.jpg","attr":"(c) aarongunnar, some rights reserved (CC BY), uploaded by aarongunnar","desc":"Aristida longespica is a species of grass known by the common name slimspike threeawn. Aristida longespica var. geniculata is listed as a species of special concern in the State of Connecticut.","fam":"Poaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"SNR","obs":289,"wiki":"https://en.wikipedia.org/wiki/Aristida_longespica","inat":154299},{"s":"E","c":"Arrowfeather","sci":"Aristida purpurascens","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/55247095/original.jpg","attr":"(c) Alvin Diamond, some rights reserved (CC BY-NC), uploaded by Alvin Diamond","desc":"Aristida purpurascens is a species of grass known by the common name arrowfeather threeawn. It is native to eastern North America. One of the three varieties has a distribution extending south into Honduras.","fam":"Poaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":1169,"wiki":"https://en.wikipedia.org/wiki/Aristida_purpurascens","inat":158667},{"s":"E","c":"Beach needle grass","sci":"Aristida tuberculosa","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/239942470/original.jpg","attr":"(c) gglynn, some rights reserved (CC BY-NC), uploaded by gglynn","desc":"Aristida tuberculosa, common names seaside threeawn, seabeach needlegrass, beach three-awned grass and beach needlegrass, is annual plant native to the United States.","fam":"Poaceae","ord":"Poales","cls":"Liliopsida","gr":"G4","sr":"S1","obs":468,"wiki":"https://en.wikipedia.org/wiki/Aristida_tuberculosa","inat":158673},{"s":"SC","c":"Purple milkweed","sci":"Asclepias purpurascens","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/4194551/original.jpg","attr":"(c) dogtooth77, some rights reserved (CC BY-NC-SA)","desc":"Asclepias purpurascens, or the purple milkweed, is a herbaceous plant species. It is in the genus Asclepias, making it a type of milkweed. It is native to the Eastern, Southern and Midwestern United States similar to the range of the common milkweed. The plant gets its name from the flowers that first develop a pink color but then turn darker purple as they mature. Unlike common milkweed, purple milkweed prefers some shade and is considered a plant of partial shade. It is also considered an indicator of oak savanna, especially in Wisconsin. The species rarely produces seed pods which are smooth, instead of the rough warty ones produced by common milkweed.","fam":"Apocynaceae","ord":"Gentianales","cls":"Magnoliopsida","gr":"G4","sr":"S2","obs":4382,"wiki":"https://en.wikipedia.org/wiki/Asclepias_purpurascens","inat":125380},{"s":"SC","c":"White milkweed","sci":"Asclepias variegata","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/12744135/original.jpg","attr":"(c) Will Stuart, some rights reserved (CC BY-NC), uploaded by Will Stuart","desc":"Asclepias variegata, commonly called the redring milkweed or white milkweed, is a plant in the family Apocynaceae. It is native to eastern North America, where it is found in Canada and the United States. It is most common in the Southeastern United States, and becomes rare in the northern edge of its range.","fam":"Apocynaceae","ord":"Gentianales","cls":"Magnoliopsida","gr":"G5","sr":"SH","obs":6436,"wiki":"https://en.wikipedia.org/wiki/Asclepias_variegata","inat":127691},{"s":"E","c":"Green milkweed","sci":"Asclepias viridiflora","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/20950526/original.jpg","attr":"(c) davecz2, some rights reserved (CC BY-SA), uploaded by davecz2","desc":"Asclepias viridiflora; also known as green comet milkweed, green-flower milkweed, and green milkweed; is a species of milkweed (Asclepias). The plant is located in the eastern and central United States, ranging between Connecticut to Georgia and Arizona to Montana, and is also in southern Canada and northern Mexico. The Latin epithet viridiflora translates as \"green-flowered\".","fam":"Apocynaceae","ord":"Gentianales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":11780,"wiki":"https://en.wikipedia.org/wiki/Asclepias_viridiflora","inat":158763},{"s":"SC","c":"Mountain spleenwort","sci":"Asplenium montanum","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/167526/original.jpg","attr":"(c) Ken-ichi Ueda, some rights reserved (CC BY)","desc":"Asplenium montanum, commonly known as the mountain spleenwort, is a small fern endemic to the eastern United States. It is found primarily in the Appalachian Mountains from Vermont to Alabama, with a few isolated populations in the Ozarks and in the Ohio Valley. It grows in small crevices in sandstone cliffs with highly acid soil, where it is usually the only vascular plant occupying that ecological niche. It can be recognized by its tufts of dark blue-green, highly divided leaves. The species was first described in 1810 by the botanist Carl Ludwig Willdenow. No subspecies have been described, although a discolored and highly dissected form was reported from the Shawangunk Mountains in 1974. Asplenium\u00a0montanum is a diploid member of the \"Appalachian Asplenium complex,\" a group of spleenwort species and hybrids which have formed by reticulate evolution. Members of the complex descended from A.\u00a0montanum are among the few other vascular plants that can tolerate its typical habitat.","fam":"Aspleniaceae","ord":"Polypodiales","cls":"Polypodiopsida","gr":"G5","sr":"S2","obs":2338,"wiki":"https://en.wikipedia.org/wiki/Asplenium_montanum","inat":122055},{"s":"T","c":"Wallrue spleenwort","sci":"Asplenium ruta-muraria","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/8990088/original.jpg","attr":"(c) A. Flinn (and M. Finn), some rights reserved (CC BY-NC), uploaded by A. Flinn (and M. Finn)","desc":"Asplenium ruta-muraria is a species of fern commonly known as wall-rue. It is a very small epipetric species, growing exclusively on limestone and other calcareous rocks. Its fronds are bluish-green and are heavily sub-divided, becoming up to 12\u00a0cm (4.7\u00a0in) in length.","fam":"Aspleniaceae","ord":"Polypodiales","cls":"Polypodiopsida","gr":"G5","sr":"S2","obs":23143,"wiki":"https://en.wikipedia.org/wiki/Asplenium_ruta-muraria","inat":84954},{"s":"SC","c":"Bracted orache","sci":"Atriplex glabriuscula","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/1680207/original.jpg","attr":"(c) Tig, all rights reserved, uploaded by Tig","desc":"Atriplex glabriuscula, usually known in English as Babington's orache, is a prostrate to ascending plant that occurs on shingle beaches in NW Europe, and in NE North America. It is a characteristic annual of strandline vegetation at the top of sand and shingle beaches.","fam":"Amaranthaceae","ord":"Caryophyllales","cls":"Magnoliopsida","gr":"G4","sr":"","obs":198,"wiki":"https://en.wikipedia.org/wiki/Atriplex_glabriuscula","inat":159069},{"s":"T","c":"Swamp birch","sci":"Betula pumila","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/19558503/original.jpg","attr":"no rights reserved, uploaded by Reuven Martin","desc":"Betula pumila is a deciduous shrub native to North America. Bog birch occurs over a vast area of northern North America, from Yukon in the west to New England in the east and all the way to Washington and Oregon, inhabiting swamps and riparian zones in the boreal forests.","fam":"Betulaceae","ord":"Fagales","cls":"Magnoliopsida","gr":"","sr":"","obs":3880,"wiki":"https://en.wikipedia.org/wiki/Betula_pumila","inat":159231},{"s":"SC","c":"Beck's water-marigold","sci":"Bidens beckii","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/4578019/original.jpg","attr":"(c) Tab Tannery, some rights reserved (CC BY-NC-SA)","desc":"Bidens beckii, commonly called Beck's water-marigold or simply water marigold is a species of flowering plant in the family Asteraceae. It is native to Canada and the northern United States.","fam":"Asteraceae","ord":"Asterales","cls":"Magnoliopsida","gr":"G5","sr":"S2","obs":656,"wiki":"https://en.wikipedia.org/wiki/Bidens_beckii","inat":204252},{"s":"E","c":"Eaton's beggarticks","sci":"Bidens eatonii","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/5919793/original.jpeg","attr":"(c) Sean Blaney, some rights reserved (CC BY-NC), uploaded by Sean Blaney","desc":"Bidens eatonii is a North American species of flowering plant in the family Asteraceae. It is native to eastern Canada and the northeastern United States.","fam":"Asteraceae","ord":"Asterales","cls":"Magnoliopsida","gr":"G3","sr":"S1","obs":101,"wiki":"https://en.wikipedia.org/wiki/Bidens_eatonii","inat":159243},{"s":"SC","c":"Downy wood-mint","sci":"Blephilia ciliata","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/501669/original.jpg","attr":"(c) cotinis, some rights reserved (CC BY-NC-SA)","desc":"Blephilia ciliata is a species of herbaceous perennial plant in the Lamiaceae (mint) family native to central and eastern North America. It is commonly called downy wood mint. Other common names include downy pagoda-plant, sunny woodmint and Ohio horsemint.","fam":"Lamiaceae","ord":"Lamiales","cls":"Magnoliopsida","gr":"G5","sr":"SH","obs":3520,"wiki":"https://en.wikipedia.org/wiki/Blephilia_ciliata","inat":159273},{"s":"SC","c":"Hairy wood-mint","sci":"Blephilia hirsuta","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/3093905/original.jpg","attr":"(c) Tom Potterfield, some rights reserved (CC BY-NC-SA)","desc":"Blephilia hirsuta, commonly known as hairy wood-mint or hairy pagoda plant, is a species of herbaceous perennial in the mint family Lamiaceae. It is native to eastern North America.","fam":"Lamiaceae","ord":"Lamiales","cls":"Magnoliopsida","gr":"G5","sr":"SH","obs":5585,"wiki":"https://en.wikipedia.org/wiki/Blephilia_hirsuta","inat":120895},{"s":"SC","c":"Bayonet grass","sci":"Bolboschoenus maritimus ssp. paludosus","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/99364639/original.jpg","attr":"(c) Graham Talaber, all rights reserved, uploaded by Graham Talaber","desc":"Bolboschoenus maritimus is a species of flowering plant from family Cyperaceae. Common names for this species include sea clubrush, cosmopolitan bulrush, alkali bulrush, saltmarsh bulrush, and bayonet grass. It is found in seaside wetland habitats over much of the world. It is widespread across much of temperate and subtropical Africa, Asia, Europe, North America, South America and various islands.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"SNR","obs":8144,"wiki":"https://en.wikipedia.org/wiki/Bolboschoenus_maritimus","inat":58345},{"s":"SC","c":"Salt marsh bulrush","sci":"Bolboschoenus novae-angliae","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/21024132/original.jpg","attr":"(c) John Trent, some rights reserved (CC BY-NC-ND), uploaded by John Trent","desc":"Bolboschoenus novae-angliae, common names New England bulrush and Salt march bulrush, is a plant species found along the Atlantic seacoast of the United States from Alabama to Maine. It grows in brackish and salt-water marshes and estuaries along the coast.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G3","sr":"S3","obs":15,"wiki":"https://en.wikipedia.org/wiki/Bolboschoenus_novae-angliae","inat":204257},{"s":"SC","c":"Little grape fern","sci":"Botrychium simplex","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/155908/original.jpg","attr":"(c) H\u00f6r\u00f0ur Kristinsson, some rights reserved (CC BY-NC)","desc":"Botrychium simplex, the little grapefern, is a species of fern in the family Ophioglossaceae that is native to North America and Greenland. It is a perennial.","fam":"Ophioglossaceae","ord":"Ophioglossales","cls":"Polypodiopsida","gr":"G5","sr":"SH","obs":374,"wiki":"https://en.wikipedia.org/wiki/Botrychium_simplex","inat":75852},{"s":"E","c":"Sideoats grama-grass","sci":"Bouteloua curtipendula","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/5329132/original.jpeg","attr":"(c) psweet, some rights reserved (CC BY-SA), uploaded by psweet","desc":"Bouteloua curtipendula, commonly known as sideoats grama, is a perennial, short prairie grass that is native throughout the temperate and tropical Western Hemisphere, from Canada south to Argentina.","fam":"Poaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":16386,"wiki":"https://en.wikipedia.org/wiki/Bouteloua_curtipendula","inat":75858},{"s":"T","c":"Reed bentgrass","sci":"Calamagrostis stricta ssp. inexpansa","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/21146387/original.jpg","attr":"(c) Jukka Jantunen, some rights reserved (CC BY-NC), uploaded by Jukka Jantunen","desc":"Calamagrostis stricta, known as slim-stem small reed grass or narrow small-reed, is a species of bunchgrass in the family Poaceae of the Holarctic Kingdom.","fam":"Poaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"SNR","obs":1438,"wiki":"https://en.wikipedia.org/wiki/Calamagrostis_stricta","inat":75930},{"s":"SC","c":"Short-stalked false bindweed","sci":"Calystegia silvatica","n":"","ext":true,"fed":"","img":"https://static.inaturalist.org/photos/206044006/original.jpeg","attr":"(c) Anne Koerber, all rights reserved, uploaded by Anne Koerber","desc":"Calystegia silvatica is the largest species of bindweed and is a strong rampant climber. It is native to southern Europe but has been introduced to many other areas because it is an attractive garden plant. Calystegia silvatica subsp. fraterniflora (Mack. & Bush) Brummitt is native to North America.","fam":"Convolvulaceae","ord":"Solanales","cls":"Magnoliopsida","gr":"G5","sr":"SH","obs":15489,"wiki":"https://en.wikipedia.org/wiki/Calystegia_silvatica","inat":75968},{"s":"SC","c":"Low bindweed","sci":"Calystegia spithamaea","n":"","ext":true,"fed":"","img":"https://static.inaturalist.org/photos/211334991/original.jpg","attr":"(c) JoannaE, all rights reserved, uploaded by JoannaE","desc":"Calystegia spithamaea, which common names include: low false bindweed, low bindweed, erect bindweed, and upright bindweed, is a species of plant found in eastern North America.","fam":"Convolvulaceae","ord":"Solanales","cls":"Magnoliopsida","gr":"G5","sr":"SH","obs":1837,"wiki":"https://en.wikipedia.org/wiki/Calystegia_spithamaea","inat":159727},{"s":"SC","c":"Purple cress","sci":"Cardamine douglassii","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/17294221/original.jpeg","attr":"(c) jodihannah, some rights reserved (CC BY-NC), uploaded by jodihannah","desc":"Cardamine douglassii, the limestone bittercress or purple cress, is a perennial forb that produces white to pink or purple flowers in early spring. It is native to Ontario, Canada, as well as the eastern and central United States.","fam":"Brassicaceae","ord":"Brassicales","cls":"Magnoliopsida","gr":"G5","sr":"S2","obs":10312,"wiki":"https://en.wikipedia.org/wiki/Cardamine_douglassii","inat":125902},{"s":"SC","c":"Summer sedge","sci":"Carex aestivalis","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/313248967/original.jpg","attr":"(c) threepogonias, all rights reserved, uploaded by threepogonias","desc":"Carex aestivalis, the summer sedge, is a species of Carex native to North America. The specific epithet, aestivalis, is derived from Latin and means \"pertaining to the summer\".","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G4","sr":"S2","obs":46,"wiki":"https://en.wikipedia.org/wiki/Carex_aestivalis","inat":159861},{"s":"E","c":"Broadwing sedge","sci":"Carex alata","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/253562296/original.jpeg","attr":"(c) Brendan Kosnik, some rights reserved (CC BY-NC-ND), uploaded by Brendan Kosnik","desc":"Carex alata, commonly called broad-winged sedge, is a species of flowering plant in the sedge family. It is native to eastern North America, in Canada and the United States. It grows in wet, marshy areas. The species name alata is Latin for \"winged\", in reference to its winged perigynia.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":204,"wiki":"https://en.wikipedia.org/wiki/Carex_alata","inat":159864},{"s":"T","c":"Foxtail sedge","sci":"Carex alopecoidea","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/8334488/original.jpeg","attr":"(c) Colin Chapman-Lam, some rights reserved (CC BY-NC), uploaded by Colin Chapman-Lam","desc":"Carex alopecoidea, common names foxtail sedge and northern fox sedge, is a species of Carex native to North America. It is listed as threatened in Connecticut. It is listed as endangered in Indiana, New Jersey, Ohio, as possibly extirpated in Maine, as threatened in Massachusetts, and as endangered and possibly extirpated in Tennessee.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":398,"wiki":"https://en.wikipedia.org/wiki/Carex_alopecoidea","inat":159868},{"s":"SC","c":"Water sedge","sci":"Carex aquatilis ssp. altior","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/215795134/original.jpeg","attr":"(c) \u0428\u0438\u043b\u044c\u043d\u0438\u043a\u043e\u0432 \u0414\u043c\u0438\u0442\u0440\u0438\u0439 \u0421\u0435\u0440\u0433\u0435\u0435\u0432\u0438\u0447, some rights reserved (CC BY-NC), uploaded by \u0428\u0438\u043b\u044c\u043d\u0438\u043a\u043e\u0432 \u0414\u043c\u0438\u0442\u0440\u0438\u0439 \u0421\u0435\u0440\u0433\u0435\u0435\u0432\u0438\u0447","desc":"Carex aquatilis is a species of sedge known as water sedge and leafy tussock sedge. It has a circumboreal distribution, occurring throughout the northern reaches of the Northern Hemisphere. It grows in many types of mountainous and arctic habitat, including temperate coniferous forest, alpine meadows, tundra, and wetlands.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"SNR","obs":4353,"wiki":"https://en.wikipedia.org/wiki/Carex_aquatilis","inat":76013},{"s":"E","c":"Back's sedge","sci":"Carex backii","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/19077310/original.jpg","attr":"(c) Jenn (McPhee) Dyson, some rights reserved (CC BY), uploaded by Jenn (McPhee) Dyson","desc":"Carex backii, commonly known as Back's sedge, is a species of sedge (Carex) in the section Phyllostachyae. First described scientifically in 1839 by American botanist Francis Boott, it is found in Canada and the United States, where it grows in shaded woods, shaded slopes, and shrub thickets.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":320,"wiki":"https://en.wikipedia.org/wiki/Carex_backii","inat":159884},{"s":"E","c":"Barratt's sedge","sci":"Carex barrattii","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/302266819/original.jpeg","attr":"(c) Sequoia Janirella Wrens, some rights reserved (CC BY-NC), uploaded by Sequoia Janirella Wrens","desc":"Carex barrattii is a species of sedge known as Barratt's sedge. It is endemic to the United States, where it occurs on the Atlantic Coastal Plain from Connecticut south to Georgia and Alabama. It also occurs in the southern Appalachians.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G4","sr":"S1","obs":112,"wiki":"https://en.wikipedia.org/wiki/Carex_barrattii","inat":159886},{"s":"SC","c":"Bush's sedge","sci":"Carex bushii","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/364221/original.jpg","attr":"(c) Cassi, some rights reserved (CC BY-NC), uploaded by Cassi","desc":"Carex bushii, Bush's sedge, is a species of sedge in the genus Carex. It native to the eastern United States where it is found in areas of natural grassland.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S3","obs":799,"wiki":"https://en.wikipedia.org/wiki/Carex_bushii","inat":129633},{"s":"E","c":"Brown bog sedge","sci":"Carex buxbaumii","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/18432491/original.jpeg","attr":"(c) Trevor Edmonson, some rights reserved (CC BY), uploaded by Trevor Edmonson","desc":"Carex buxbaumii is a species of sedge known as Buxbaum's sedge or club sedge. It is native to much of the northern Northern Hemisphere, from Alaska to Greenland to Eurasia, and including most of Canada and the United States. It grows in wet habitat, such as marshes and fens. This sedge grows in clumps from long rhizomes. The stems are 75\u2013100\u00a0cm (30\u201339\u00a0in) in maximum height. The leaves are narrow and small. The inflorescence has a bract which is sometimes longer than the spikes. The fruits have dark-colored bracts and a sac called a perigynium or utricle which is gray-green and rough in texture.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":1914,"wiki":"https://en.wikipedia.org/wiki/Carex_buxbaumii","inat":76021},{"s":"E","c":"Chestnut-colored sedge","sci":"Carex castanea","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/42788515/original.jpg","attr":"(c) Samuel Brinker, all rights reserved, uploaded by Samuel Brinker","desc":"Carex castanea, commonly known as chestnut sedge, is a species of flowering plant in the sedge family (Cyperaceae) native to North America. It is listed as endangered in Connecticut, Massachusetts, and New Hampshire. Its range extends from Manitoba to the eastern seaboard in Canada and from Minnesota to New England in the United States. It is also sometimes called chestnut woodland sedge or chestnut-colored sedge.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":920,"wiki":"https://en.wikipedia.org/wiki/Carex_castanea","inat":159907},{"s":"SC","c":"Collins' sedge","sci":"Carex collinsii","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/19885170/original.jpg","attr":"(c) lidecicco, some rights reserved (CC BY-NC), uploaded by lidecicco","desc":"Carex collinsii, common name Collins' sedge, is a species of Carex native to North America. It is listed as a special concern species and believed extirpated in Connecticut. It is listed as endangered in New York, as threatened in Pennsylvania, and its historical range included Rhode Island.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G4","sr":"SH","obs":179,"wiki":"https://en.wikipedia.org/wiki/Carex_collinsii","inat":159913},{"s":"T","c":"Crawe's sedge","sci":"Carex crawei","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/31689392/original.jpg","attr":"(c) aarongunnar, some rights reserved (CC BY), uploaded by aarongunnar","desc":"Carex crawei, commonly called Crawe's sedge, is a species of flowering plant in the sedge family. It is native to North America, where it is widespread in the United States and Canada. Though widespread, it has a patchy distribution and is generally rare throughout its range. It is found in wet calcareous areas, usually associated with flat limestone outcrops or gravels. It is usually found in high quality natural habitats.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":892,"wiki":"https://en.wikipedia.org/wiki/Carex_crawei","inat":159920},{"s":"SC","c":"Crawford sedge","sci":"Carex crawfordii","n":"","ext":true,"fed":"","img":"https://static.inaturalist.org/photos/9234865/original.jpeg","attr":"(c) Samuel Brinker, all rights reserved, uploaded by Samuel Brinker","desc":"Carex crawfordii, common name Crawford sedge, is a species of Carex native to North America.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"SH","obs":510,"wiki":"https://en.wikipedia.org/wiki/Carex_crawfordii","inat":159921},{"s":"T","c":"Clustered sedge","sci":"Carex cumulata","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/5068731/original.jpeg","attr":"(c) John Scholze, some rights reserved (CC BY-NC), uploaded by John Scholze","desc":"Carex cumulata, common names clustered sedge, piled sedge, and piled-up sedge is a species of Carex native to North America. It is a perennial.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G4","sr":"S1","obs":300,"wiki":"https://en.wikipedia.org/wiki/Carex_cumulata","inat":159927},{"s":"T","c":"Davis' sedge","sci":"Carex davisii","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/139518211/original.jpeg","attr":"(c) Quinten Wiegersma, some rights reserved (CC BY), uploaded by Quinten Wiegersma","desc":"Carex davisii, known as Davis' sedge or awned graceful sedge, is a species of Carex native to North America. It is listed as an endangered, threatened, or species of concern across much of edge of its range. It was named in the 1820s by Lewis David de Schweinitz and John Torrey in honor of Emerson Davis (1798\u20131866), a Massachusetts educator and \"enthusiastic student of the genus\" Carex.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S2","obs":1212,"wiki":"https://en.wikipedia.org/wiki/Carex_davisii","inat":159930},{"s":"E","c":"Meager sedge","sci":"Carex exilis","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/206634298/original.jpeg","attr":"(c) Quinten Wiegersma, some rights reserved (CC BY), uploaded by Quinten Wiegersma","desc":"Carex exilis, common name coastal sedge or meager sedge, is a species of grass-like plant in the Cyperaceae family. It is native to North America and Canada, with several disjunct populations from southern Canada to the Gulf Coast.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"SNR","obs":452,"wiki":"https://en.wikipedia.org/wiki/Carex_exilis","inat":159947},{"s":"SC","c":"Bronze sedge","sci":"Carex foenea","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/12858267/original.jpeg","attr":"(c) Sean Blaney, some rights reserved (CC BY-NC), uploaded by Sean Blaney","desc":"Carex foenea is a species of flowering plant in the family Cyperaceae, native from subarctic America to the northern United States. It was first described by Carl Ludwig Willdenow in 1809.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"","obs":496,"wiki":"https://en.wikipedia.org/wiki/Carex_foenea","inat":204268},{"s":"SC","c":"Handsome sedge","sci":"Carex formosa","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/3796720/original.JPG","attr":"(c) Mark Kluge, some rights reserved (CC BY-NC), uploaded by Mark Kluge","desc":"Carex formosa, also known as handsome sedge, is a species of sedge native to North America. It is listed as an endangered species in the US states of Minnesota, New Jersey, and Pennsylvania, as threatened in Connecticut, Massachusetts, New York, and Wisconsin, and as presumed extirpated in Ohio.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"SNR","obs":415,"wiki":"https://en.wikipedia.org/wiki/Carex_formosa","inat":159955},{"s":"SC","c":"Hitchcock's sedge","sci":"Carex hitchcockiana","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/18618872/original.jpg","attr":"(c) Pat Deacon, some rights reserved (CC BY-NC), uploaded by Pat Deacon","desc":"Carex hitchcockiana, common name Hitchcock's sedge, is a Carex species that is native to North America. It is listed as endangered in Maryland, as threatened in New York and Tennessee, and as a species of special concern in Connecticut and Massachusetts.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S2","obs":580,"wiki":"https://en.wikipedia.org/wiki/Carex_hitchcockiana","inat":159975},{"s":"T","c":"Mud sedge","sci":"Carex limosa","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/3/3f/Carex_limosa_inflorescence_kz.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Carex limosa is a species of sedge known as bog-sedge, mud sedge, and shore sedge.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"SNR","obs":0,"wiki":"https://en.wikipedia.org/wiki/Carex_limosa","inat":""},{"s":"E","c":"Boreal bog sedge","sci":"Carex magellanica","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/399379/original.jpg","attr":"(c) Biopix, some rights reserved (CC BY-NC)","desc":"Carex magellanica, is a perennial Carex species native to North America, Europe and the subarctic Northern hemisphere. Although it is considered a stable species worldwide, it is listed as endangered in Connecticut.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":2280,"wiki":"https://en.wikipedia.org/wiki/Carex_magellanica","inat":143532},{"s":"SC","c":"Troublesome sedge","sci":"Carex molesta","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/2131696/original.jpg","attr":"(c) summerazure, some rights reserved (CC BY-NC-SA)","desc":"Carex molesta is a species of sedge known by the common name troublesome sedge. It is native to eastern and central North America, where it grows in varied wet and dry habitats, performs equally well in full sun and partial shade, including disturbed areas such as roadsides. It is an introduced species and often a weed in California.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":1556,"wiki":"https://en.wikipedia.org/wiki/Carex_molesta","inat":160026},{"s":"SC","c":"Black-edge sedge","sci":"Carex nigromarginata","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/133642979/original.jpg","attr":"(c) Douglas Goldman, some rights reserved (CC BY-SA), uploaded by Douglas Goldman","desc":"Carex nigromarginata, also known as black edge sedge, is a North American sedge which grows on acid soils in dry woodland, thickets, and roadside, and similar ruderal habitats in partial shade or in full sun, often near streams at elevations of 10\u2013800\u00a0m (33\u20132,625\u00a0ft). The plants grow in dense clumps, often forming circular patterns on forest floors or roadsides. 2n = 36.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"","obs":826,"wiki":"https://en.wikipedia.org/wiki/Carex_nigromarginata","inat":160037},{"s":"SC","c":"New England sedge","sci":"Carex novae-angliae","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/8/84/Carex_novae-angliae_BB-1913.png","attr":"Wikimedia Commons (CC BY-SA)","desc":"Carex novae-angliae, the New England sedge, is a Carex species that is native to North America.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S2","obs":0,"wiki":"https://en.wikipedia.org/wiki/Carex_novae-angliae","inat":""},{"s":"SC","c":"Eastern few-fruit sedge","sci":"Carex oligocarpa","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/248131591/original.jpeg","attr":"(c) Paul Marcum, some rights reserved (CC BY-NC), uploaded by Paul Marcum","desc":"Carex oligocarpa, common name richwoods sedge, eastern few-fruited sedge, few-fruit sedge, and few-fruited sedge is a Carex species that is native to North America. It is a perennial.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"T5","sr":"","obs":381,"wiki":"https://en.wikipedia.org/wiki/Carex_oligocarpa","inat":160044},{"s":"SC","c":"Few-seeded sedge","sci":"Carex oligosperma","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/8487521/original.jpg","attr":"(c) aarongunnar, some rights reserved (CC BY), uploaded by aarongunnar","desc":"Carex oligosperma, common name fewseed sedge, few-seeded sedge, and few-fruited sedge, is a perennial plant in the Carex genus. A distinct variety, Carex oligosperma var. oligosperma, exists.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"SH","obs":1466,"wiki":"https://en.wikipedia.org/wiki/Carex_oligosperma","inat":160045},{"s":"SC","c":"Few-flowered sedge","sci":"Carex pauciflora","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/147808022/original.jpg","attr":"(c) er-birds, some rights reserved (CC BY), uploaded by er-birds","desc":"Carex pauciflora, the few-flowered sedge, is a perennial species of sedge in the family Cyperaceae native to bogs and fens in cool temperate, subarctic, and mountainous regions of the Northern Hemisphere. The specific epithet pauciflora refers to the Latin term for 'few flowered'.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"SH","obs":1618,"wiki":"https://en.wikipedia.org/wiki/Carex_pauciflora","inat":62577},{"s":"E","c":"Variable sedge","sci":"Carex polymorpha","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/8735716/original.jpg","attr":"(c) Ephraim Zimmerman, some rights reserved (CC BY-NC), uploaded by Ephraim Zimmerman","desc":"Carex polymorpha common names variable sedge and many forms sedge, is a perennial species of Carex native to North America.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G3","sr":"S1","obs":29,"wiki":"https://en.wikipedia.org/wiki/Carex_polymorpha","inat":160072},{"s":"SC","c":"Prairie sedge","sci":"Carex prairea","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/11400931/original.jpg","attr":"(c) aarongunnar, some rights reserved (CC BY), uploaded by aarongunnar","desc":"Carex prairea, common name prairie sedge, is a species of Carex native to North America. It is a perennial, tussock-forming plant in the Cyperaceae family","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"SNR","obs":282,"wiki":"https://en.wikipedia.org/wiki/Carex_prairea","inat":160073},{"s":"E","c":"Cyperus-like sedge","sci":"Carex pseudocyperus","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/225905790/original.jpeg","attr":"(c) eugenezakharov, some rights reserved (CC BY-NC), uploaded by eugenezakharov","desc":"Carex pseudocyperus is a species of flowering plant in the sedge family known by the common name cyperus sedge or hop sedge. It grows in marshes, swamps, and the margins of ponds, rivers and canals. The stems can be up to 90 centimetres (35\u00a0in) with one male spike and 3 to 5 pendulous female spikes, and bright yellow-green leaves to 1.2 metres.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":6122,"wiki":"https://en.wikipedia.org/wiki/Carex_pseudocyperus","inat":62212},{"s":"E","c":"Reznicek's sedge","sci":"Carex reznicekii","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/17948258/original.jpg","attr":"(c) ThePrairiePreacher, some rights reserved (CC BY-NC), uploaded by ThePrairiePreacher","desc":"Carex reznicekii, known as Reznicek's sedge, is a species of Carex native to North America. It is a perennial. Described initially from a New York population, this species was named in 2006 in honor of the botanist Anton Reznicek, a specialist in the genus Carex.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G4","sr":"S1","obs":52,"wiki":"https://en.wikipedia.org/wiki/Carex_reznicekii","inat":160086},{"s":"E","c":"Schweinitz's sedge","sci":"Carex schweinitzii","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/2053194/original.jpg","attr":"(c) Liana May, some rights reserved (CC BY-NC), uploaded by Liana May","desc":"Carex schweinitzii, common name Schweinitz's sedge, is a Carex species native to North America. It is a perennial.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G3","sr":"S1","obs":70,"wiki":"https://en.wikipedia.org/wiki/Carex_schweinitzii","inat":160100},{"s":"SC","c":"Dioecious sedge","sci":"Carex sterilis","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/180491670/original.jpg","attr":"(c) John Thayer, all rights reserved, uploaded by John Thayer","desc":"Carex sterilis, common names dioecious sedge, sterile sedge and Atlantic sedge, is a perennial plant native to North America.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S3","obs":456,"wiki":"https://en.wikipedia.org/wiki/Carex_sterilis","inat":160110},{"s":"SC","c":"Hairy-fruited sedge","sci":"Carex trichocarpa","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/22454952/original.jpg","attr":"(c) aarongunnar, some rights reserved (CC BY), uploaded by aarongunnar","desc":"Carex trichocarpa, the hairy-fruited sedge, is a species of Carex native to North America. It is listed as a \"species of special concern\" in Connecticut, the United States. The larvae of Euphyes bimacula, the two-spotted skipper, feed on the plant. Euphyes bimacula is listed as endangered in Connecticut.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S3","obs":548,"wiki":"https://en.wikipedia.org/wiki/Carex_trichocarpa","inat":154309},{"s":"SC","c":"Tuckerman's sedge","sci":"Carex tuckermanii","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/98534915/original.jpg","attr":"(c) Michael John Oldham, some rights reserved (CC BY-NC), uploaded by Michael John Oldham","desc":"Carex tuckermanii, commonly known as Tuckerman's sedge, is a species of true sedge in the family Cyperaceae. It is a perennial plant native to North America.It owes its name to Edward Tuckerman, who was the first botanist to organize the genus Carex into natural groupings.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S2","obs":1291,"wiki":"https://en.wikipedia.org/wiki/Carex_tuckermanii","inat":143895},{"s":"SC","c":"Cattail sedge","sci":"Carex typhina","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/210710120/original.jpeg","attr":"(c) Wayne Longbottom, some rights reserved (CC BY-NC), uploaded by Wayne Longbottom","desc":"Carex typhina, often called the cattail sedge, is a rare species of Carex known to grow in wetlands. It is native to North America.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":1047,"wiki":"https://en.wikipedia.org/wiki/Carex_typhina","inat":48684},{"s":"E","c":"Little green sedge","sci":"Carex viridula","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/b/b9/CarexViridula1.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Carex viridula, known as little green sedge, green sedge, or greenish sedge, is a small flowering plant native to North America, Europe, Asia, and Morocco.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":0,"wiki":"https://en.wikipedia.org/wiki/Carex_viridula","inat":""},{"s":"E","c":"Willdenow's sedge","sci":"Carex willdenowii","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/251891093/original.jpeg","attr":"(c) Christopher David Benda, some rights reserved (CC BY-NC), uploaded by Christopher David Benda","desc":"Carex willdenowii, common name Willdenow's sedge, is a species of Carex native to North America.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":274,"wiki":"https://en.wikipedia.org/wiki/Carex_willdenowii","inat":160144},{"s":"E","c":"Indian paintbrush","sci":"Castilleja coccinea","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/103898/original.JPG","attr":"(c) Kent Miller, some rights reserved (CC BY-ND), uploaded by Kent Miller","desc":"Castilleja coccinea, commonly known as scarlet paintbrush or scarlet painted-cup, is a biennial flowering plant in the Orobanchaceae (broomrape) family. It is usually found in prairies, rocky glades, moist and open woodlands, thickets, and along streams in central and eastern North America.","fam":"Orobanchaceae","ord":"Lamiales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":6955,"wiki":"https://en.wikipedia.org/wiki/Castilleja_coccinea","inat":49342},{"s":"SC","c":"American bittersweet","sci":"Celastrus scandens","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/4910702/original.jpg","attr":"(c) Rob Curtis, some rights reserved (CC BY-NC-SA), uploaded by Rob Curtis","desc":"Celastrus scandens, commonly called American bittersweet, is a species of bittersweet that blooms mostly in June and is commonly found on rich, well-drained soils of woodlands.","fam":"Celastraceae","ord":"Celastrales","cls":"Magnoliopsida","gr":"G5","sr":"S2","obs":8805,"wiki":"https://en.wikipedia.org/wiki/Celastrus_scandens","inat":64538},{"s":"E","c":"Devil's-bit","sci":"Chamaelirium luteum","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/161799/original.jpg","attr":"(c) Tom Potterfield, some rights reserved (CC BY-NC-SA)","desc":"Chamaelirium is a genus of flowering plants containing the single species Chamaelirium luteum, commonly known as blazing-star, devil's bit, false unicorn, fairy wand, and helonias. It is a perennial herb native to the eastern United States. It can be found in a variety of habitats, including wet meadows and deciduous woodlands.","fam":"Melanthiaceae","ord":"Liliales","cls":"Liliopsida","gr":"G4","sr":"S1","obs":2418,"wiki":"https://en.wikipedia.org/wiki/Chamaelirium","inat":122251},{"s":"E","c":"Hairy lip-fern","sci":"Cheilanthes lanosa","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/2/26/Cheilanthes_lanosa_kz1.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Myriopteris lanosa, the hairy lip fern, is a medium-sized fern of the eastern United States. The leaves are twice-divided into lanceolate or oblong segments, and are sparsely covered in hairs, but lack scales, hence its common name. One of the cheilanthoid lip ferns, it was usually classified in the genus Cheilanthes as Cheilanthes lanosa until 2013, when the genus Myriopteris was again recognized as separate from Cheilanthes. It typically grows in shallow, dry, soil, often in rocky habitats.","fam":"Pteridaceae","ord":"Polypodiales","cls":"Polypodiopsida","gr":"","sr":"","obs":0,"wiki":"https://en.wikipedia.org/wiki/Myriopteris_lanosa","inat":""},{"s":"SC","c":"Red goosefoot","sci":"Chenopodium rubrum","n":"","ext":true,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/9/95/Chenopodium_rubrum.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Oxybasis rubra, common names red goosefoot or coastblite goosefoot, is a member of the genus Oxybasis, a segregate of Chenopodium. It is native to North America and Eurasia. It is an annual plant.","fam":"Amaranthaceae","ord":"Caryophyllales","cls":"Magnoliopsida","gr":"","sr":"","obs":0,"wiki":"https://en.wikipedia.org/wiki/Oxybasis_rubra","inat":""},{"s":"E","c":"Yellow thistle","sci":"Cirsium horridulum","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/156203292/original.jpg","attr":"(c) Mary Keim, some rights reserved (CC BY-NC-SA)","desc":"Cirsium horridulum, called bristly thistle, purple thistle, or yellow thistle is a North American species of plants in the tribe Cardueae within the family Asteraceae. It is an annual or biennial. The species is native to the eastern and southern United States from New England to Florida, Texas, and Oklahoma as well as to Mexico, Belize, Guatemala, Honduras, and the Bahamas.","fam":"Asteraceae","ord":"Asterales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":25753,"wiki":"https://en.wikipedia.org/wiki/Cirsium_horridulum","inat":127269},{"s":"E","c":"Long-bracted green orchid","sci":"Coeloglossum viride","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/0/0d/Dactylorhiza_viridis_%28flowers%29.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Dactylorhiza viridis, the frog orchid, is a species of flowering plant in the orchid family Orchidaceae. It has also been treated as the only species Coeloglossum viride of the monotypic genus Coeloglossum.","fam":"Orchidaceae","ord":"Asparagales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":0,"wiki":"https://en.wikipedia.org/wiki/Dactylorhiza_viridis","inat":""},{"s":"SC","c":"Long-leaved redtop-panicgrass","sci":"Coleataenia longifolia ssp. elongata","n":"","ext":true,"fed":"","img":"https://newfs.s3.amazonaws.com/taxon-images-1000s1000/Poaceae/coleataenia-longifolia-in-efarnsworth.jpg","attr":"Elizabeth Farnsworth / Native Plant Trust","desc":"Coleataenia longifolia is a species of grass in the family Poaceae found in North America. Coleataenia longifolia subsp. elongata is listed as a special concern and believed extirpated in Connecticut.","fam":"Poaceae","ord":"Poales","cls":"Liliopsida","gr":"G4","sr":"SNR","obs":0,"wiki":"https://en.wikipedia.org/wiki/Coleataenia_longifolia","inat":""},{"s":"SC","c":"Early coral root","sci":"Corallorhiza trifida","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/203353241/original.jpg","attr":"(c) Brad Von Blon, some rights reserved (CC BY-NC), uploaded by Brad Von Blon","desc":"Corallorhiza trifida, commonly known as early coralroot, northern coralroot, or yellow coralroot, is a coralroot orchid native to North America and Eurasia, with a circumboreal distribution. The species has been reported from the United States, Canada, Russia, China, Japan, Korea, India, Nepal, Kashmir, Pakistan, and almost every country in Europe.","fam":"Orchidaceae","ord":"Asparagales","cls":"Liliopsida","gr":"G5","sr":"S2","obs":6121,"wiki":"https://en.wikipedia.org/wiki/Corallorhiza_trifida","inat":50709},{"s":"T","c":"Yellow corydalis","sci":"Corydalis flavula","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/356576275/original.jpeg","attr":"(c) Michael J. Papay, some rights reserved (CC BY), uploaded by Michael J. Papay","desc":"Corydalis flavula is an herbaceous perennial plant native to the eastern United States. Its natural habitat is open woods and slopes.","fam":"Papaveraceae","ord":"Ranunculales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":8202,"wiki":"https://en.wikipedia.org/wiki/Corydalis_flavula","inat":128038},{"s":"E","c":"Pygmyweed","sci":"Crassula aquatica","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/171419290/original.jpeg","attr":"no rights reserved, uploaded by art_leostrin","desc":"Crassula aquatica is a succulent plant known by the common names water pygmyweed, common pygmyweed and just pigmyweed. It is an annual plant of salt marshes, vernal pools, wetlands, and other fresh to brackish water bodies. It is at least partially aquatic, living in areas which are submersed much of the time. It also lives along muddy banks and in tidally-active areas of estuaries.","fam":"Crassulaceae","ord":"Saxifragales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":691,"wiki":"https://en.wikipedia.org/wiki/Crassula_aquatica","inat":58135},{"s":"SC","c":"Bushy frostweed","sci":"Crocanthemum dumosum","n":"","ext":true,"fed":"","img":"https://static.inaturalist.org/photos/135391073/original.jpeg","attr":"(c) Rudy Bang, all rights reserved, uploaded by Rudy Bang","desc":"Crocanthemum dumosum, common known as bushy frostweed and bushy rockrose, is a perennial plant that is native to the United States.","fam":"Cistaceae","ord":"Malvales","cls":"Magnoliopsida","gr":"G3","sr":"SH","obs":26,"wiki":"https://en.wikipedia.org/wiki/Crocanthemum_dumosum","inat":204297},{"s":"SC","c":"Low frostweed","sci":"Crocanthemum propinquum","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/3894491/original.jpeg","attr":"(c) Uzay Sezen, all rights reserved, uploaded by Uzay Sezen","desc":"Helianthemum propinquum, formerly called Crocanthemum propinquum, common names low frostweed and low rockrose, is a perennial plant that is native to the United States.","fam":"Cistaceae","ord":"Malvales","cls":"Magnoliopsida","gr":"G4","sr":"S2","obs":27,"wiki":"https://en.wikipedia.org/wiki/Helianthemum_propinquum","inat":204298},{"s":"SC","c":"Elliptical rushfoil","sci":"Crotonopsis elliptica","n":"","ext":true,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/7/79/Croton_michauxii_-_Carter_Creek_WMA%2C_FL_-_May_2025.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Croton michauxii, commonly known as elliptical rushfoil, and Michaux's croton, is a plant species in the family Euphorbiaceae that is native to the United States. It is an annual plant.","fam":"Euphorbiaceae","ord":"Malpighiales","cls":"Magnoliopsida","gr":"","sr":"","obs":0,"wiki":"https://en.wikipedia.org/wiki/Croton_michauxii","inat":""},{"s":"E","c":"Slender cliff-brake","sci":"Cryptogramma stelleri","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/6/60/Cryptogramma_stelleri_5536193_4x3.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Cryptogramma stelleri, common names slender cliff-brake, fragile rock-brake, slender rock-brake, and Steller's rockbrake, is a plant found in North America. It is listed as endangered in Connecticut, Massachusetts, New Jersey, and Pennsylvania. It is listed as threatened in Maine and New Hampshire, as exploitably vulnerable in New York (state) and as sensitive in Washington (state).","fam":"Pteridaceae","ord":"Polypodiales","cls":"Polypodiopsida","gr":"G5","sr":"S1","obs":0,"wiki":"https://en.wikipedia.org/wiki/Cryptogramma_stelleri","inat":""},{"s":"SC","c":"Blue waxweed","sci":"Cuphea viscosissima","n":"","ext":true,"fed":"","img":"https://static.inaturalist.org/photos/214355507/original.jpg","attr":"(c) Tina Notas, all rights reserved, uploaded by Tina Notas","desc":"Cuphea viscosissima, also known as waxbush, blue waxweed, clammy cuphea or (ambiguously) as \"tarweed\", is an herbaceous plant in the loosestrife family. It native to the eastern United States, where it is most often found in open, rocky calcareous areas. It is the most common and widespread Cuphea in the U.S.","fam":"Lythraceae","ord":"Myrtales","cls":"Magnoliopsida","gr":"G5","sr":"SH","obs":1020,"wiki":"https://en.wikipedia.org/wiki/Cuphea_viscosissima","inat":161259},{"s":"SC","c":"Hazel dodder","sci":"Cuscuta coryli","n":"","ext":true,"fed":"","img":"https://static.inaturalist.org/photos/11228423/original.jpg","attr":"(c) Samuel Brinker, all rights reserved, uploaded by Samuel Brinker","desc":"Cuscuta coryli, synonym Grammica coryli, common name hazel dodder, is a perennial plant in the Cuscutaceae family native to North America.","fam":"Convolvulaceae","ord":"Solanales","cls":"Magnoliopsida","gr":"G4","sr":"SNR","obs":166,"wiki":"https://en.wikipedia.org/wiki/Cuscuta_coryli","inat":161268},{"s":"SC","c":"Wild comfrey","sci":"Cynoglossum virginianum","n":"","ext":true,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/2/2b/Cynoglossum_virginianum_-_Wild_Comfrey.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Andersonglossum virginianum, known as southern wild comfrey, is a flowering plant in the borage family native to North America. It is also sometimes called blue houndstongue.","fam":"Boraginaceae","ord":"Boraginales","cls":"Magnoliopsida","gr":"G5","sr":"SH","obs":0,"wiki":"https://en.wikipedia.org/wiki/Andersonglossum_virginianum","inat":""},{"s":"SC","c":"Ram's-head lady's-slipper","sci":"Cypripedium arietinum","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/8083006/original.jpg","attr":"(c) Superior National Forest, some rights reserved (CC BY)","desc":"Cypripedium arietinum, the ram's head lady's slipper, is a rare terrestrial orchid that grows in lightly to heavily shaded areas with calcareous soils. It is characteristic of the alvars around the Great Lakes in North America]. In Canada, it is found from Quebec to Saskatchewan, plus an isolated population in Nova Scotia, where it grows on gypsum based soils, 330\u00a0km away from the nearest population in Maine.","fam":"Orchidaceae","ord":"Asparagales","cls":"Liliopsida","gr":"G3","sr":"SH","obs":1311,"wiki":"https://en.wikipedia.org/wiki/Cypripedium_arietinum","inat":57844},{"s":"SC","c":"Yellow lady's-slipper","sci":"Cypripedium parviflorum","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/19472528/original.jpg","attr":"(c) Tony Ernst, some rights reserved (CC BY-NC), uploaded by Tony Ernst","desc":"Cypripedium parviflorum, commonly known as yellow lady's slipper or moccasin flower, is a lady's slipper orchid native to North America. It is widespread, ranging from Alaska south to Arizona and Georgia. It grows in fens, wetlands, shorelines, and damp woodlands.","fam":"Orchidaceae","ord":"Asparagales","cls":"Liliopsida","gr":"G5","sr":"S3","obs":18992,"wiki":"https://en.wikipedia.org/wiki/Cypripedium_parviflorum","inat":50713},{"s":"E","c":"Showy lady's-slipper","sci":"Cypripedium reginae","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/40938903/original.jpg","attr":"(c) Chelsea Gottfried, some rights reserved (CC BY-NC), uploaded by Chelsea Gottfried","desc":"Cypripedium reginae, known as the showy lady's slipper, pink lady's-slipper, or the queen's lady's-slipper, is a rare lady's-slipper orchid native to northern North America. Although never common, this plant has vanished from much of its historical range due to habitat loss. It is the state flower of Minnesota.","fam":"Orchidaceae","ord":"Asparagales","cls":"Liliopsida","gr":"G4","sr":"S1","obs":6226,"wiki":"https://en.wikipedia.org/wiki/Cypripedium_reginae","inat":51434},{"s":"SC","c":"Tufted hairgrass","sci":"Deschampsia cespitosa","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/108225556/original.jpeg","attr":"(c) \u0421\u043e\u043a\u043e\u043b\u043a\u043e\u0432 \u042e\u0440\u0438\u0439 \u041f\u0430\u0432\u043b\u043e\u0432\u0438\u0447, some rights reserved (CC BY-NC), uploaded by \u0421\u043e\u043a\u043e\u043b\u043a\u043e\u0432 \u042e\u0440\u0438\u0439 \u041f\u0430\u0432\u043b\u043e\u0432\u0438\u0447","desc":"Deschampsia cespitosa, commonly known as tufted hairgrass or tussock grass, is a perennial tufted plant in the grass family Poaceae. The distribution of this species is widespread, with it being native to North America, Central Africa, eastern Australia, New Zealand, and Eurasia and being introduced to South Africa, South Australia and South America.","fam":"Poaceae","ord":"Poales","cls":"Liliopsida","gr":"G4","sr":"","obs":13566,"wiki":"https://en.wikipedia.org/wiki/Deschampsia_cespitosa","inat":76639},{"s":"E","c":"Large-bracted tick-trefoil","sci":"Desmodium cuspidatum","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/23702249/original.jpeg","attr":"(c) Carol Nelson, some rights reserved (CC BY-NC), uploaded by Carol Nelson","desc":"Desmodium cuspidatum, common name large-bracted tick-trefoil, is a species of plant in the legume family, Fabaceae. It is native to North America.","fam":"Fabaceae","ord":"Fabales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":397,"wiki":"https://en.wikipedia.org/wiki/Desmodium_cuspidatum","inat":161731},{"s":"SC","c":"Dillenius' tick-trefoil","sci":"Desmodium glabellum","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/25779675/original.jpg","attr":"(c) ThePrairiePreacher, some rights reserved (CC BY-NC), uploaded by ThePrairiePreacher","desc":"Desmodium glabellum is a species of flowering plant in the legume family Fabaceae. It is native to the eastern and central United States. It is commonly called Dillenius' tick-trefoil in honor of Johann Dillenius, a British botanist of German birth. It is also known as the tall tick-trefoil.","fam":"Fabaceae","ord":"Fabales","cls":"Magnoliopsida","gr":"G5","sr":"S2","obs":2800,"wiki":"https://en.wikipedia.org/wiki/Desmodium_glabellum","inat":130994},{"s":"SC","c":"Sessile-leaf tick-trefoil","sci":"Desmodium sessilifolium","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/4798521/original.jpg","attr":"(c) Jenny Smith, some rights reserved (CC BY-NC), uploaded by Jenny Smith","desc":"Desmodium sessilifolium, common name sessileleaf ticktrefoil, is a species of plant in the legume family, Fabaceae. It is native to North America.","fam":"Fabaceae","ord":"Fabales","cls":"Magnoliopsida","gr":"G5","sr":"SH","obs":1133,"wiki":"https://en.wikipedia.org/wiki/Desmodium_sessilifolium","inat":146703},{"s":"SC","c":"Squirrel corn","sci":"Dicentra canadensis","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/263311482/original.jpg","attr":"(c) Mark Eanes, some rights reserved (CC BY), uploaded by Mark Eanes","desc":"Dicentra canadensis, the squirrel corn, is a flowering plant from eastern North America with oddly shaped white flowers and finely divided leaves.","fam":"Papaveraceae","ord":"Ranunculales","cls":"Magnoliopsida","gr":"G5","sr":"S2","obs":10253,"wiki":"https://en.wikipedia.org/wiki/Dicentra_canadensis","inat":48952},{"s":"SC","c":"Stiff-leaved rosette-panicgrass","sci":"Dichanthelium ovale ssp. pseudopubescens","n":"","ext":true,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/7/7b/Dichanthelium_ovale_NRCS-001.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Dichanthelium ovale, commonly known as eggleaf rosette grass, is a plant found in North America. Dichanthelium ovale subsp. pseudopubescens, common name Stiff-leaved rosette-panicgrass is listed as a special concern and believed extirpated in Connecticut.","fam":"Poaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"SNR","obs":0,"wiki":"https://en.wikipedia.org/wiki/Dichanthelium_ovale","inat":""},{"s":"E","c":"Tall swamp rosette-panicgrass","sci":"Dichanthelium scabriusculum","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/29651118/original.jpg","attr":"(c) Kim and Peter Connolly, some rights reserved (CC BY-NC), uploaded by Kim and Peter Connolly","desc":"Dichanthelium scabriusculum, commonly called tall swamp rosette-panicgrass, tall swamp panicgrass, rough panic-grass or panic grass, is a species of plant found in North America. It is listed as endangered in Connecticut, Maryland, and New York. It is listed as threatened in Massachusetts.","fam":"Poaceae","ord":"Poales","cls":"Liliopsida","gr":"G4","sr":"S1","obs":790,"wiki":"https://en.wikipedia.org/wiki/Dichanthelium_scabriusculum","inat":133040},{"s":"SC","c":"Round-fruited rosette-panicgrass","sci":"Dichanthelium sphaerocarpon var. isophyllum","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/2842200/original.jpg","attr":"(c) Lee Elliott, some rights reserved (CC BY-NC-SA), uploaded by Lee Elliott","desc":"Dichanthelium sphaerocarpon, also called Panicum polyanthes, common name round-seed panic grass, is a plant found in North America. It is listed as endangered in Michigan. Dichanthelium sphaerocarpon var. isophyllum is listed as a special concern and believed extirpated in Connecticut.","fam":"Poaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"SNR","obs":1072,"wiki":"https://en.wikipedia.org/wiki/Dichanthelium_sphaerocarpon","inat":161804},{"s":"SC","c":"Pale-leaved rosette-panicgrass","sci":"Dichanthelium xanthophysum","n":"","ext":true,"fed":"","img":"https://static.inaturalist.org/photos/292524477/original.jpeg","attr":"(c) Samuel Brinker, all rights reserved, uploaded by Samuel Brinker","desc":"Dichanthelium xanthophysum, formerly known as Panicum xanthophysum, common names slender rosette grass, panic grass and slender panic-grass, is a plant found in North America. It is listed as a special concern and believed extirpated in Connecticut. It is listed as endangered in New Jersey and Pennsylvania.","fam":"Poaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"SH","obs":396,"wiki":"https://en.wikipedia.org/wiki/Dichanthelium_xanthophysum","inat":161810},{"s":"E","c":"Narrow-leaved glade fern","sci":"Diplazium pycnocarpon","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/8/83/Diplazium_pycnocarpon_0001.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Homalosorus is a genus of fern with only one species, Homalosorus pycnocarpos. It may also be referred to by its older synonyms Athyrium pycnocarpon and Diplazium pycnocarpon. Commonly referred to as the narrow-leaved glade fern, narrow-leaved-spleenwort, or glade fern, it is endemic to eastern North America and typically grows in moist woodlands. Once classified in the family Athyriaceae due to its linear, often doubled sori, in the Pteridophyte Phylogeny Group classification of 2016, it is placed in the small family Diplaziopsidaceae, whose other three species are native to east Asia. Other sources place the genus in the subfamily Diplaziopsidoideae of a very broadly defined family Aspleniaceae, equivalent to the suborder Aspleniineae in PPG I.","fam":"Diplaziopsidaceae","ord":"Polypodiales","cls":"Polypodiopsida","gr":"","sr":"","obs":0,"wiki":"https://en.wikipedia.org/wiki/Homalosorus","inat":""},{"s":"SC","c":"Appalachian white-aster","sci":"Doellingeria infirma","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/549989346/original.jpg","attr":"(c) Rob Curtis, some rights reserved (CC BY-NC-SA), uploaded by Rob Curtis","desc":"Doellingeria infirma, the cornel-leaf whitetop or cornel-leaved aster, is a perennial forb native to the eastern United States, that produces white composite flowers in late summer.","fam":"Asteraceae","ord":"Asterales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":335,"wiki":"https://en.wikipedia.org/wiki/Doellingeria_infirma","inat":161981},{"s":"SC","c":"Whitlow-grass","sci":"Draba reptans","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/a/a5/Draba_reptans_BB-1913.png","attr":"Wikimedia Commons (CC BY-SA)","desc":"Tomostima reptans, common names Carolina draba, Carolina whitlow-grass, Creeping whitlow-grass, and Whitlow-grass, is an annual plant in the family Brassicaceae that is native to temperate North America.","fam":"Brassicaceae","ord":"Brassicales","cls":"Magnoliopsida","gr":"G5","sr":"S2","obs":0,"wiki":"https://en.wikipedia.org/wiki/Tomostima_reptans","inat":""},{"s":"SC","c":"Thread-leaf sundew","sci":"Drosera filiformis","n":"","ext":true,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/b/b9/Drosera_filiformis_ne1.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Drosera filiformis, commonly known as Tracy's sundew, dewthread or the thread-leaved sundew, is a small, insectivorous, rosette-forming species of perennial herb. A species of sundew, it is unusual within its genus in that the long, erect, filiform (thread-like) leaves of this plant unroll in spirals \u2013 an arrangement similar to the circinate vernation seen in ferns.","fam":"Droseraceae","ord":"Caryophyllales","cls":"Magnoliopsida","gr":"G4","sr":"SH","obs":0,"wiki":"https://en.wikipedia.org/wiki/Drosera_filiformis","inat":""},{"s":"SC","c":"Tall cinquefoil","sci":"Drymocallis arguta","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/2140269/original.JPG","attr":"(c) Mark Kluge, some rights reserved (CC BY-NC), uploaded by Mark Kluge","desc":"Drymocallis arguta, commonly known as the tall cinquefoil, prairie cinquefoil, or sticky cinquefoil, is a perennial herbaceous plant native to North America. It was formerly included with the typical cinquefoils in the genus Potentilla.","fam":"Rosaceae","ord":"Rosales","cls":"Magnoliopsida","gr":"G5","sr":"S2","obs":6019,"wiki":"https://en.wikipedia.org/wiki/Drymocallis_arguta","inat":204304},{"s":"E","c":"Mountain wood-fern","sci":"Dryopteris campyloptera","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/231738189/original.jpg","attr":"(c) msundue, all rights reserved, uploaded by msundue","desc":"Dryopteris campyloptera, also known as the mountain wood fern, is a large American fern of higher elevations and latitudes. It was formerly known as Dryopteris spinulosa var. americana. This species also has been mistakenly referred to as D. austriaca and D. dilatata.","fam":"Dryopteridaceae","ord":"Polypodiales","cls":"Polypodiopsida","gr":"G5","sr":"S1","obs":1925,"wiki":"https://en.wikipedia.org/wiki/Dryopteris_campyloptera","inat":82563},{"s":"SC","c":"Goldie's fern","sci":"Dryopteris goldiana","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/7/71/Dryopteris_goldiana10.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Dryopteris goldieana, commonly called Goldie's wood fern, or giant wood fern is a fern native to the eastern United States and adjacent areas of Canada, from New Brunswick to Ontario and Georgia. It is the largest native North American species of Dryopteris and along with ostrich fern it is one of the largest ferns in eastern North America. Specimens are known with fronds six feet tall. D. goldieana hybridizes with many other species of Dryopteris and the hybrids tend to be larger than the pure species. It was named by William Hooker in honor of its discoverer, John Goldie. The epithet was originally published as goldiana, but this is regarded as a misspelling to be corrected.","fam":"Dryopteridaceae","ord":"Polypodiales","cls":"Polypodiopsida","gr":"G5","sr":"S3","obs":0,"wiki":"https://en.wikipedia.org/wiki/Dryopteris_goldieana","inat":""},{"s":"E","c":"Bur-head","sci":"Echinodorus tenellus","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/4/4f/Echinodorus_tenellus_BB-1913.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Helanthium tenellum, the pygmy chain sword, is a species of plants in the Alismataceae. It is native to the eastern United States, southern Mexico, West Indies, Central America, South America","fam":"Alismataceae","ord":"Alismatales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":0,"wiki":"https://en.wikipedia.org/wiki/Helanthium_tenellum","inat":""},{"s":"E","c":"Horsetail spikesedge","sci":"Eleocharis equisetoides","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/9633052/original.jpeg","attr":"(c) Carlos G Velazco-Macias, some rights reserved (CC BY-NC), uploaded by Carlos G Velazco-Macias","desc":"Eleocharis equisetoides, with common names including horsetail spike-rush, jointed spike-rush, spikesedge, and knotted spike-rush, is a plant species native to the United States and Ontario, usually in freshwater wetland areas. It is known primarily from the Atlantic coastal plain from Texas to Massachusetts, and the Great Lakes region, with scattered populations elsewhere.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G4","sr":"S1","obs":197,"wiki":"https://en.wikipedia.org/wiki/Eleocharis_equisetoides","inat":162241},{"s":"SC","c":"Small-fruited spikesedge","sci":"Eleocharis microcarpa var. filiculmis","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/5282646/original.jpg","attr":"(c) grbfrog, some rights reserved (CC BY-NC), uploaded by grbfrog","desc":"Eleocharis microcarpa, common names small-fruited spikesedge, spike-rush, small-fruited spike-rush and tiny-fruited spike-sedge, is a plant in the Eleocharis genus found in North America.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"SH","obs":78,"wiki":"https://en.wikipedia.org/wiki/Eleocharis_microcarpa","inat":59069},{"s":"E","c":"Square-stemmed spikesedge","sci":"Eleocharis quadrangulata var. crassior","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/353262/original.jpg","attr":"(c) Layla, all rights reserved, uploaded by Layla","desc":"Eleocharis quadrangulata is a species of spikesedge known by the common names square-stem spikerush and four-angled spikerush. It is native to eastern and central North America, with additional populations in California, Oregon, and west-central Mexico. It grows in and around freshwater in lakes, ponds, and other bodies of water. It is a rhizomatous perennial herb growing one half to one meter in height. The spongy, compressible stem is a few millimeters wide and sharply four-angled. The inflorescence is a single spikelet 1.5 to 7.5 centimeters long which is made up of several flowers covered in light brown bracts.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":852,"wiki":"https://en.wikipedia.org/wiki/Eleocharis_quadrangulata","inat":76784},{"s":"SC","c":"Wiegand's wild rye","sci":"Elymus wiegandii","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/9884241/original.jpg","attr":"(c) botanicalwanderer, some rights reserved (CC BY-NC)","desc":"Elymus canadensis, synonyms including Elymus wiegandii, commonly known as Canada wild rye or Canadian wildrye, is a species of wild rye native to much of North America. It is most abundant in the central plains and Great Plains. It grows in a number of ecosystems, including woodlands, savannas, dunes, and prairies, sometimes in areas that have been disturbed.","fam":"Poaceae","ord":"Poales","cls":"Liliopsida","gr":"G4","sr":"S2","obs":217,"wiki":"https://en.wikipedia.org/wiki/Elymus_canadensis","inat":162293},{"s":"SC","c":"Virginia snakeroot","sci":"Endodeca serpentaria","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/2/26/Aristolochia_serpentaria.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Aristolochia serpentaria is a species of perennial flowering plant in the Aristolochiaceae (birthwort) family. The species is commonly known as Virginia snakeroot and is native to eastern North America, from Connecticut to southern Michigan and south to Texas and Florida.","fam":"Aristolochiaceae","ord":"Piperales","cls":"Magnoliopsida","gr":"","sr":"","obs":0,"wiki":"https://en.wikipedia.org/wiki/Aristolochia_serpentaria","inat":""},{"s":"SC","c":"Marsh horsetail","sci":"Equisetum palustre","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/84653148/original.jpg","attr":"(c) hpr61, some rights reserved (CC BY-NC), uploaded by hpr61","desc":"Equisetum palustre, the marsh horsetail, is a perennial herbaceous pteridophyte belonging to the subclass of horsetails (Equisetidae). It is widespread in cooler regions of Eurasia and North America.","fam":"Equisetaceae","ord":"Equisetales","cls":"Polypodiopsida","gr":"G5","sr":"SH","obs":5582,"wiki":"https://en.wikipedia.org/wiki/Equisetum_palustre","inat":76846},{"s":"E","c":"Meadow horsetail","sci":"Equisetum pratense","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/380439427/original.jpg","attr":"(c) degsis04, some rights reserved (CC BY-NC)","desc":"Equisetum pratense, commonly known as meadow horsetail, shade horsetail or shady horsetail, is a widespread horsetail (Equisetophyta) and it is a pteridophyte. Shade horsetail can be commonly found in forests with tall trees or very thick foliage that can provide shade and tends to grow closer and thicker around streams, ponds and rivers. The specific epithet pratense is Latin, meaning pasture or meadow dwelling.","fam":"Equisetaceae","ord":"Equisetales","cls":"Polypodiopsida","gr":"G5","sr":"S1","obs":10542,"wiki":"https://en.wikipedia.org/wiki/Equisetum_pratense","inat":127900},{"s":"E","c":"Dwarf scouring rush","sci":"Equisetum scirpoides","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/108329487/original.jpg","attr":"(c) Jason Berard, all rights reserved, uploaded by Jason Berard","desc":"Equisetum scirpoides Michx., Fl. Bor.-Amer. 2: 281 (1803). 2 n = 216. The smallest of the currently occurring representatives of the genus Equisetum (horsetail).","fam":"Equisetaceae","ord":"Equisetales","cls":"Polypodiopsida","gr":"G5","sr":"S1","obs":6317,"wiki":"https://en.wikipedia.org/wiki/Equisetum_scirpoides","inat":162373},{"s":"E","c":"Parker's pipewort","sci":"Eriocaulon parkeri","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/200890687/original.jpeg","attr":"(c) Martine Lapointe, some rights reserved (CC BY-NC), uploaded by Martine Lapointe","desc":"Eriocaulon parkeri is a species of flowering plant in the pipewort family known by the common names Parker's pipewort and estuary pipewort. It is native to eastern North America, where its distribution spans the coast from Quebec to North Carolina. It is extirpated from New York and Pennsylvania, however.","fam":"Eriocaulaceae","ord":"Poales","cls":"Liliopsida","gr":"G3","sr":"S1","obs":120,"wiki":"https://en.wikipedia.org/wiki/Eriocaulon_parkeri","inat":162562},{"s":"T","c":"Hare's tail","sci":"Eriophorum vaginatum var. spissum","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/289462497/original.jpeg","attr":"(c) dhope, some rights reserved (CC BY-NC)","desc":"Eriophorum vaginatum is a species of flowering plant in the sedge family Cyperaceae. It occurs throughout the subarctic and temperate regions of the Northern Hemisphere. It prefers wet, acidic, peaty soil and is often dominant in bogs, poor fens, and the Arctic tundra regions of northern Russia and Canada. The specific epithet vaginatum, which means \"having a sheath\", refers to an important character used to recognize this species. Both the scientific name Eriophorum vaginatum and the common name sheathed cottonsedge emphasize this fact. In Britain and Ireland, the species is referred to as hare's-tail cottongrass. The name tussock cottongrass gained in popularity after its publication in Flora of North America in 2002.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"SNR","obs":14700,"wiki":"https://en.wikipedia.org/wiki/Eriophorum_vaginatum","inat":128735},{"s":"E","c":"White thoroughwort","sci":"Eupatorium album","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/52309675/original.jpeg","attr":"(c) Eric M Powell, some rights reserved (CC BY-NC), uploaded by Eric M Powell","desc":"Eupatorium album, the white thoroughwort or snowy white eupatorium, is a herbaceous perennial plant in the family Asteraceae native from the eastern and southern United States, from eastern Texas to Connecticut, inland as far as Indiana.","fam":"Asteraceae","ord":"Asterales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":1085,"wiki":"https://en.wikipedia.org/wiki/Eupatorium_album","inat":162779},{"s":"T","c":"Rough aster","sci":"Eurybia radula","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/148867616/original.jpeg","attr":"(c) Patrick Sweeney, some rights reserved (CC BY-NC), uploaded by Patrick Sweeney","desc":"Eurybia radula, commonly known as the low rough aster or rough wood aster, is an herbaceous perennial in the family Asteraceae. It is native to eastern North America where it is present from Newfoundland and Labrador in the far northeast of Canada, west to Ontario and south to Kentucky and Virginia in the United States. The low rough aster is also present on the French overseas territory of St. Pierre and Miquelon just south of Newfoundland. It typically grows in wet soils in a wide variety of habitats from bogs and fens to creek shores to ditches. Although it is not considered threatened over most of its distribution, it is imperiled or possibly extirpated over much of its range in the United States. Its flower heads emerge in the late summer to early fall and show pale blue-violet rays with yellow centres.","fam":"Asteraceae","ord":"Asterales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":751,"wiki":"https://en.wikipedia.org/wiki/Eurybia_radula","inat":153201},{"s":"T","c":"Showy aster","sci":"Eurybia spectabilis","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/471193/original.jpg","attr":"(c) Jason S, some rights reserved (CC BY-NC-ND)","desc":"Eurybia spectabilis, commonly known as the eastern showy aster, simply showy aster or purple wood aster, is an herbaceous perennial native to the eastern United States. It is present along the coastal plain of the U.S. where it is most often found growing in dry, sandy soils. Although it is not considered threatened due to its extensive range, it is locally endangered in many states. The flowers appear in the fall and show ray florets that are a violet-purple and yellow disc florets. It is one of the parent species of the hybrid Eurybia \u00d7 herveyi.","fam":"Asteraceae","ord":"Asterales","cls":"Magnoliopsida","gr":"G5","sr":"S2","obs":839,"wiki":"https://en.wikipedia.org/wiki/Eurybia_spectabilis","inat":162891},{"s":"E","c":"False mermaid-weed","sci":"Floerkea proserpinacoides","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/587110/original.jpg","attr":"(c) Erin Haase, some rights reserved (CC BY-NC), uploaded by Erin Haase","desc":"Floerkea is a monotypic genus of plants in the meadowfoam family containing the sole species Floerkea proserpinacoides, which is known by the common names false mermaid, false mermaidweed, and floerkea. This tiny wildflower is native to many parts of North America, where it is found in moist areas, such as shady forests. It is a fleshy, annual herb which grows short stems which may lie flat on the ground, tangle into a clump, or grow somewhat erect. The foliage is hairless and shiny. The leaves are divided into many oval-shaped, pointed leaflets up to 2\u00a0cm (0.79\u00a0in) long. The flower is a cup of pointed green sepals containing three tiny white spoon-shaped petals and a bunch of stamens with yellow anthers. Growing in the center of the flower are the two to three fruits, which are bumpy, spherical nutlets.","fam":"Limnanthaceae","ord":"Brassicales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":4535,"wiki":"https://en.wikipedia.org/wiki/Floerkea","inat":69648},{"s":"E","c":"Bog bedstraw","sci":"Galium labradoricum","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/8250817/original.jpg","attr":"(c) aarongunnar, some rights reserved (CC BY), uploaded by aarongunnar","desc":"Galium labradoricum is a plant species in the family Rubiaceae. It is widespread across Canada, found in all provinces and territories except Yukon. It also occurs in Saint Pierre and Miquelon and in the northern United States, primarily in New England and the Great Lakes region, from Maine to the Dakotas. It is endangered in Connecticut.","fam":"Rubiaceae","ord":"Gentianales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":413,"wiki":"https://en.wikipedia.org/wiki/Galium_labradoricum","inat":163180},{"s":"SC","c":"Purple cudweed","sci":"Gamochaeta purpurea","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/68688462/original.jpeg","attr":"no rights reserved, uploaded by \u8449\u5b50","desc":"Gamochaeta purpurea, the purple cudweed, purple everlasting, or spoonleaf purple everlasting, is a plant native to North America.","fam":"Asteraceae","ord":"Asterales","cls":"Magnoliopsida","gr":"G5","sr":"SH","obs":4387,"wiki":"https://en.wikipedia.org/wiki/Gamochaeta_purpurea","inat":60957},{"s":"SC","c":"Creeping snowberry","sci":"Gaultheria hispidula","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/89125351/original.jpg","attr":"(c) roninat, some rights reserved (CC BY-NC), uploaded by roninat","desc":"Gaultheria hispidula, commonly known as the creeping snowberry or moxie-plum, and known to Mi'kmaq tribes of Newfoundland as manna teaberry, is a perennial spreading ground-level vine of the heath family Ericaceae. It is native to North America and produces small white edible berries. It fruits from August to September. Its leaves and berries taste and smell like wintergreen. The species epithet hispidula refers to the bristles on the stems and leaves.","fam":"Ericaceae","ord":"Ericales","cls":"Magnoliopsida","gr":"G5","sr":"S2","obs":9527,"wiki":"https://en.wikipedia.org/wiki/Gaultheria_hispidula","inat":53460},{"s":"T","c":"Dwarf huckleberry","sci":"Gaylussacia bigeloviana","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/9535756/original.jpeg","attr":"(c) Burkhard, some rights reserved (CC BY-NC-SA), uploaded by Burkhard","desc":"Gaylussacia bigeloviana, also known as the northern dwarf huckleberry or in French as the gaylussaquier de Bigelow, is a plant species native to the coastal plains of eastern Canada and the eastern United States. It grows from Newfoundland to South Carolina in swamps and marshes, including acidic bogs alongside Sphagnum peatmosses.","fam":"Ericaceae","ord":"Ericales","cls":"Magnoliopsida","gr":"G4","sr":"S2","obs":593,"wiki":"https://en.wikipedia.org/wiki/Gaylussacia_bigeloviana","inat":204323},{"s":"E","c":"Stiff gentian","sci":"Gentianella quinquefolia","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/541887/original.jpg","attr":"(c) Peter Gorman, some rights reserved (CC BY-NC-SA)","desc":"Gentianella quinquefolia, commonly called agueweed, is a flowering plant in the gentian family. It is native to eastern North America.","fam":"Gentianaceae","ord":"Gentianales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":2341,"wiki":"https://en.wikipedia.org/wiki/Gentianella_quinquefolia","inat":119901},{"s":"SC","c":"Bicknell's northern crane's-bill","sci":"Geranium bicknellii","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/96524/original.jpg","attr":"(c) Superior National Forest, some rights reserved (CC BY)","desc":"Geranium bicknellii is a species of geranium known by the common names Bicknell's cranesbill and northern cranesbill. It is native to much of the northern half of North America, where it can be found in a number of forest and woodland habitats. This is an annual or biennial herb which grows hairy stems up to about half a meter long. It may be erect or lie near the ground. Each leaf is several centimeters long and wide and is divided into several lobes, each of which may have smaller lobes or teeth. Flowers grow singly or in pairs and have pointed sepals and small lavender petals, each with a notch in the tip. The fruit has a rounded body with a long, straight style about 2 centimeters in length and tipped with a small beak.","fam":"Geraniaceae","ord":"Geraniales","cls":"Magnoliopsida","gr":"G5","sr":"SH","obs":2584,"wiki":"https://en.wikipedia.org/wiki/Geranium_bicknellii","inat":77251},{"s":"SC","c":"Dwarf rattlesnake plantain","sci":"Goodyera repens var. ophioides","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/150468053/original.jpeg","attr":"(c) Ramun\u0117 Vakar\u0117, some rights reserved (CC BY-NC-SA), uploaded by Ramun\u0117 Vakar\u0117","desc":"Goodyera repens, a small forest orchid in the genus Goodyera. It is known by the common name creeping lady's-tresses in Anglophone Europe and dwarf rattlesnake plantain or lesser rattlesnake plantain in North America.","fam":"Orchidaceae","ord":"Asparagales","cls":"Liliopsida","gr":"G5","sr":"SH","obs":8120,"wiki":"https://en.wikipedia.org/wiki/Goodyera_repens","inat":62407},{"s":"SC","c":"Kidneyleaf mud-plantain","sci":"Heteranthera reniformis","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/174842526/original.jpg","attr":"(c) tyler.fishman, all rights reserved, uploaded by tyler.fishman","desc":"Heteranthera reniformis common name kidneyleaf mud-plantain, and mud plantain; is a species of flowering plant in the family Pontederiaceae. It is found in North America. It is listed as a special concern and believed extirpated in Connecticut. It listed as endangered in Illinois and Ohio.","fam":"Pontederiaceae","ord":"Commelinales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":1759,"wiki":"https://en.wikipedia.org/wiki/Heteranthera_reniformis","inat":163710},{"s":"SC","c":"Seabeach sandwort","sci":"Honckenya peploides","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/397562368/original.jpg","attr":"(c) \u0414\u043c\u0438\u0442\u0440\u0438\u0439 \u041c\u0435\u0437\u0435\u043d\u0438\u043d, some rights reserved (CC BY-NC), uploaded by \u0414\u043c\u0438\u0442\u0440\u0438\u0439 \u041c\u0435\u0437\u0435\u043d\u0438\u043d","desc":"Honckenya peploides, the sea sandwort (UK) or seaside sandplant (Canada), is the only species in the genus Honckenya of the plant family Caryophyllaceae. Other common names include sea chickweed, sea pimpernal, sea-beach sandwort, and sea purslane. The scientific name is often spelled \"Honkenya\", and is named after the German botanist Gerhard August Honckeny. This plant has a circumboreal distribution.","fam":"Caryophyllaceae","ord":"Caryophyllales","cls":"Magnoliopsida","gr":"G5","sr":"S3","obs":14932,"wiki":"https://en.wikipedia.org/wiki/Honckenya","inat":129446},{"s":"SC","c":"Featherfoil","sci":"Hottonia inflata","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/287497205/original.jpeg","attr":"(c) botanicum-vitae, all rights reserved","desc":"Hottonia inflata, the American featherfoil or featherfoil, is an aquatic plant in the family Primulaceae.","fam":"Primulaceae","ord":"Ericales","cls":"Magnoliopsida","gr":"G4","sr":"S3","obs":885,"wiki":"https://en.wikipedia.org/wiki/Hottonia_inflata","inat":143759},{"s":"T","c":"Longleaf bluet","sci":"Houstonia longifolia","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/514266195/original.jpg","attr":"(c) Sadie Hickey, some rights reserved (CC BY-NC), uploaded by Sadie Hickey","desc":"Houstonia longifolia, commonly known as long-leaved bluet or longleaf summer bluet, is a perennial plant in the family Rubiaceae. It can be found throughout most of the Eastern United States and Canada. It has been reported from every state east of the Mississippi River except Delaware, plus North Dakota, Minnesota, Missouri, Arkansas and Oklahoma, with isolated populations in Kansas and Texas. Also, all Canadian provinces from Quebec to Alberta. It prefers upland woods in poor, dry, often sandy soil.","fam":"Rubiaceae","ord":"Gentianales","cls":"Magnoliopsida","gr":"G5","sr":"S2","obs":6663,"wiki":"https://en.wikipedia.org/wiki/Houstonia_longifolia","inat":69753},{"s":"E","c":"Golden-heather","sci":"Hudsonia ericoides","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/2/2f/Hudsonia_ericoides.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Hudsonia ericoides is a species of flowering plant in the rock-rose family known by the common names pine barren goldenheather, false heather, and golden-heather. It is native to eastern North America, where its distribution extends down the east coast from Newfoundland to Delaware, with a disjunct population in South Carolina.","fam":"Cistaceae","ord":"Malvales","cls":"Magnoliopsida","gr":"G4","sr":"S1","obs":0,"wiki":"https://en.wikipedia.org/wiki/Hudsonia_ericoides","inat":""},{"s":"T","c":"Woolly beach-heather","sci":"Hudsonia tomentosa","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/131691/original.JPG","attr":"(c) Tigran Tadevosyan, some rights reserved (CC BY), uploaded by Tigran Tadevosyan","desc":"Hudsonia tomentosa is a species of flowering plant in the rockrose family known by the common names woolly beachheather, beach heather, and sand heather. It is native to northeastern North America, including central and eastern Canada and the northeastern United States.","fam":"Cistaceae","ord":"Malvales","cls":"Magnoliopsida","gr":"G5","sr":"S2","obs":4706,"wiki":"https://en.wikipedia.org/wiki/Hudsonia_tomentosa","inat":62310},{"s":"SC","c":"Fir clubmoss","sci":"Huperzia appressa","n":"","ext":true,"fed":"","img":"https://static.inaturalist.org/photos/22327517/original.jpg","attr":"(c) Samuel Brinker, all rights reserved, uploaded by Samuel Brinker","desc":"Huperzia appressa, commonly known as Appalachian firmoss, is a non-flowering species of plant in the family Lycopodiaceae. It has been reported from the United States, Canada, China, Russia, and several European countries. It is a terrestrial plant up to 10\u00a0cm tall, with dichotomously branched stems.","fam":"Lycopodiaceae","ord":"Lycopodiales","cls":"Lycopodiopsida","gr":"G5","sr":"SH","obs":915,"wiki":"https://en.wikipedia.org/wiki/Huperzia_appressa","inat":204155},{"s":"SC","c":"Green violet","sci":"Hybanthus concolor","n":"","ext":true,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/f/f7/Cubelium_concolor.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Cubelium concolor, commonly known as eastern green violet, is a flowering plant in the violet family (Violaceae). It is native to eastern North America, where it ranges from Ontario south to Florida, and from Vermont west to Kansas and Oklahoma.","fam":"Violaceae","ord":"Malpighiales","cls":"Magnoliopsida","gr":"G5","sr":"SH","obs":0,"wiki":"https://en.wikipedia.org/wiki/Cubelium","inat":""},{"s":"E","c":"Goldenseal","sci":"Hydrastis canadensis","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/141315946/original.jpg","attr":"(c) Matt Tomlinson, some rights reserved (CC BY-NC), uploaded by Matt Tomlinson","desc":"Goldenseal, also called orangeroot or yellow puccoon, is a perennial herb in the buttercup family Ranunculaceae, native to North America. It may be distinguished by its thick, yellow knotted rootstock. The stem is purplish and hairy above ground and yellow below ground where it connects to the yellow rhizome. Goldenseal reproduces both clonally through the rhizome and sexually, with clonal division more frequent than asexual reproduction. It takes between 4 and 5 years for a plant to reach sexual maturity, i.e. the point at which it produces flowers. Plants in the first stage, when the seed erupts and cotyledons emerge, can remain in this state one or more years. The second vegetative stage occurs during years two and three and is characterized by the development of a single leaf and absence of a well developed stem. Finally, the third stage is reproductive, at which point flowering and fruiting occurs. This last stage takes between 4 and 5 years to develop.","fam":"Ranunculaceae","ord":"Ranunculales","cls":"Magnoliopsida","gr":"G3","sr":"S1","obs":5401,"wiki":"https://en.wikipedia.org/wiki/Goldenseal","inat":118768},{"s":"E","c":"Water pennywort","sci":"Hydrocotyle umbellata","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/53502259/original.jpeg","attr":"(c) Eric Ulteig, some rights reserved (CC BY-NC), uploaded by Eric Ulteig","desc":"Hydrocotyle umbellata is an aquatic plant that thrives in wet, sandy habitat. It is known by several common names, including manyflower marshpennywort, dollarweed, water pennywort, and as acari\u00e7oba. It is native to North America and parts of South America. At the north of its range, in Canada, the species is only known from three lakes located in southwestern Nova Scotia. Most of the Canadian population is found within Kejimkujik National Park. In Brazil, acari\u00e7oba has applications in herbal medicine with purported anxiolytic, analgesic and anti-inflammatory properties. It can also be found growing as an introduced species and sometimes a noxious weed on other continents. It is an edible weed that can be used in salads or as a pot herb. In some parts of its native American range, manyflower marshpennywort is considered to be a species at risk, as well as in Canada, where water pennywort is listed as threatened federally and as endangered in Nova Scotia.","fam":"Araliaceae","ord":"Apiales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":6108,"wiki":"https://en.wikipedia.org/wiki/Hydrocotyle_umbellata","inat":58792},{"s":"E","c":"Whorled pennywort","sci":"Hydrocotyle verticillata","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/0/04/Starr_980601-1501_Hydrocotyle_verticillata.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Hydrocotyle verticillata, also known as whorled pennywort, whorled marshpennywort or shield pennywort, is a flowering plant found in South and North America and the West Indies. Its creeping habit and unusual leaves give it its common names. It grows in places that are marshy, boggy, or even wet. Hydrocotyle verticillata is used in aquaria, where it is undemanding; it does prefer a good substrate, however, and at least moderate light. It benefits from additional carbon dioxide. It is widely used as a foreground plant.","fam":"Araliaceae","ord":"Apiales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":0,"wiki":"https://en.wikipedia.org/wiki/Hydrocotyle_verticillata","inat":""},{"s":"SC","c":"Virginia waterleaf","sci":"Hydrophyllum virginianum","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/91570/original.jpg","attr":"(c) Gordilly, some rights reserved (CC BY-NC-ND)","desc":"Hydrophyllum virginianum, commonly called Virginia waterleaf or eastern waterleaf, is an herbaceous perennial plant native to Eastern North America where it is primarily found in the Midwest, Northeast, and Appalachian regions. The genus Hydrophyllum is placed in the family Hydrophyllaceae.","fam":"Hydrophyllaceae","ord":"Boraginales","cls":"Magnoliopsida","gr":"G5","sr":"S3","obs":31285,"wiki":"https://en.wikipedia.org/wiki/Hydrophyllum_virginianum","inat":81711},{"s":"SC","c":"Creeping St. John's-wort","sci":"Hypericum adpressum","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/22662999/original.jpg","attr":"(c) Nate Martineau, some rights reserved (CC BY-NC), uploaded by Nate Martineau","desc":"Hypericum adpressum, common names creeping St. Johnswort and bog St. Johnswort, is a flowering perennial plant found growing on wet ground in the United States.","fam":"Hypericaceae","ord":"Malpighiales","cls":"Magnoliopsida","gr":"G3","sr":"SH","obs":136,"wiki":"https://en.wikipedia.org/wiki/Hypericum_adpressum","inat":163954},{"s":"SC","c":"Great St. John's-wort","sci":"Hypericum ascyron","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/408460/original.jpg","attr":"(c) Junichi HASHIMOTO, some rights reserved (CC BY-ND)","desc":"Hypericum ascyron, the great St. Johnswort or giant St. John's wort is a flowering plant in the family Hypericaceae.","fam":"Hypericaceae","ord":"Malpighiales","cls":"Magnoliopsida","gr":"G5","sr":"S2","obs":3975,"wiki":"https://en.wikipedia.org/wiki/Hypericum_ascyron","inat":163955},{"s":"T","c":"Inkberry","sci":"Ilex glabra","n":"(native populations only)","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/126467/original.jpg","attr":"(c) Mary Keim, some rights reserved (CC BY-NC-SA)","desc":"Ilex glabra, also known as Appalachian tea, evergreen winterberry, Canadian winterberry, gallberry, inkberry, dye-leaves and houx galbre, is a species of evergreen holly native to the coastal plain of eastern North America, from coastal Nova Scotia to Florida and west to Louisiana where it is most commonly found in sandy woods and peripheries of swamps and bogs. Ilex glabra is often found in landscapes of the middle and lower East Coast of the United States. It normally is cultivated as an evergreen shrub in USDA zones 6 to 10.","fam":"Aquifoliaceae","ord":"Aquifoliales","cls":"Magnoliopsida","gr":"G5","sr":"S2","obs":17298,"wiki":"https://en.wikipedia.org/wiki/Ilex_glabra","inat":129347},{"s":"E","c":"Small whorled pogonia","sci":"Isotria medeoloides","n":"","ext":false,"fed":"T","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/259600365/original.jpg","attr":"(c) rkluzco, some rights reserved (CC BY-NC)","desc":"Isotria medeoloides, commonly known as small whorled pogonia or little five leaves, is a terrestrial orchid found in temperate Eastern North America.","fam":"Orchidaceae","ord":"Asparagales","cls":"Liliopsida","gr":"G2","sr":"S1","obs":179,"wiki":"https://en.wikipedia.org/wiki/Isotria_medeoloides","inat":62257},{"s":"SC","c":"Weak rush","sci":"Juncus debilis","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/47481664/original.jpeg","attr":"(c) Eric M Powell, some rights reserved (CC BY-NC), uploaded by Eric M Powell","desc":"Juncus debilis, the weak rush, is a plant indigenous to the United States. It is listed as endangered in Massachusetts and New York, and as threatened in Rhode Island. It is listed as a species of special concern in Connecticut and believed extirpated in that state.","fam":"Juncaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"SH","obs":44,"wiki":"https://en.wikipedia.org/wiki/Juncus_debilis","inat":116356},{"s":"T","c":"Two-flowered cynthia","sci":"Krigia biflora","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/171809552/original.jpg","attr":"(c) Daniel Sembroski, some rights reserved (CC BY-NC), uploaded by Daniel Sembroski","desc":"Krigia biflora, also known as two-flower cynthia or two-flower dwarf dandelion, is a species of plant in the family Asteraceae. It is native to North America, where it is found in central Canada and in the eastern, central, and southwestern United States. This species is rare in Connecticut, and it is listed as a species of special concern.","fam":"Asteraceae","ord":"Asterales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":6459,"wiki":"https://en.wikipedia.org/wiki/Krigia_biflora","inat":119800},{"s":"E","c":"Carolina redroot","sci":"Lachnanthes caroliniana","n":"(native populations only)","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/9/97/Carolina_redroot_%28Lachnanthes_caroliana%29_%287450499000%29.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Lachnanthes is a genus of monocotyledonous plants in the bloodwort family containing only one species, i.e., Lachnanthes caroliana (caroliniana), commonly known as Carolina redroot or bloodroot. The plant is native to eastern North America, from southeastern Nova Scotia and Massachusetts in the north, south to Florida and Cuba, and west along the Gulf of Mexico to Louisiana. It has also been reported from an island in the western Caribbean off the coast of Honduras. It prefers wet, acidic, usually sandy soils, restricting it to various wetland habitats such as bogs, pinelands, hammocks and pocosins, among others.","fam":"Haemodoraceae","ord":"Commelinales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":0,"wiki":"https://en.wikipedia.org/wiki/Lachnanthes","inat":""},{"s":"SC","c":"Illinois pinweed","sci":"Lechea racemulosa","n":"","ext":true,"fed":"","img":"https://static.inaturalist.org/photos/4190298/original.jpg","attr":"(c) Layla, all rights reserved, uploaded by Layla","desc":"Lechea racemulosa, common name Illinois pinweed, is a perennial plant native to the United States.","fam":"Cistaceae","ord":"Malvales","cls":"Magnoliopsida","gr":"G5","sr":"SH","obs":369,"wiki":"https://en.wikipedia.org/wiki/Lechea_racemulosa","inat":164465},{"s":"E","c":"Saltpond Grass","sci":"Leptochloa fusca ssp. fascicularis","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/e/e0/Diplachne_fusca.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Diplachne fusca, called bearded sprangletop and Kallar grass, is a widespread species of grass in the genus Diplachne, native to North America, the Caribbean, South America, Africa, Asia, and Australia, and introduced in Europe, New Zealand and Hawaii, among other places. It prefers to live in salty, wet conditions, such as in salt marshes and shallow depressions.","fam":"Poaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"SNR","obs":0,"wiki":"https://en.wikipedia.org/wiki/Diplachne_fusca","inat":""},{"s":"SC","c":"Creeping bush-clover","sci":"Lespedeza repens","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/52288141/original.jpeg","attr":"(c) Douglas Goldman, some rights reserved (CC BY-SA), uploaded by Douglas Goldman","desc":"Lespedeza repens, common names creeping lespedeza, creeping bush-clover, and trailing lespedeza, is a plant native to the eastern and central United States and northeastern Mexico. It is listed as a species of special concern in Connecticut and as rare in New York. It is a perennial herb which blooms May to September. Its habitats include open woods, clearings, and thickets.","fam":"Fabaceae","ord":"Fabales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":2835,"wiki":"https://en.wikipedia.org/wiki/Lespedeza_repens","inat":130742},{"s":"SC","c":"New England blazing-star","sci":"Liatris novae-angliae","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/148637686/original.jpeg","attr":"(c) Erlon Bailey, some rights reserved (CC BY-NC), uploaded by Erlon Bailey","desc":"Liatris novae-angliae, commonly known as the New England blazing-star, is a species of flowering plant in the family Asteraceae.","fam":"Asteraceae","ord":"Asterales","cls":"Magnoliopsida","gr":"G4","sr":"SNR","obs":780,"wiki":"https://en.wikipedia.org/wiki/Liatris_novae-angliae","inat":204158},{"s":"E","c":"Scotch lovage","sci":"Ligusticum scoticum","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/e/e5/Dritv%C3%ADk_-_Vegetation_und_Lavakiesel_3.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Ligusticum scoticum, known as Scots lovage, or Scottish licorice-root, is a perennial flowering plant in the celery family, Apiaceae. It grows up to 60 centimetres (24\u00a0in) tall and is found in rock crevices and cliff-top grassland. It is closely related to, and possibly conspecific with, Ligusticum hultenii from the coast of the northern Pacific Ocean.","fam":"Apiaceae","ord":"Apiales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":0,"wiki":"https://en.wikipedia.org/wiki/Ligusticum_scoticum","inat":""},{"s":"SC","c":"Lilaeopsis","sci":"Lilaeopsis chinensis","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/86533877/original.jpg","attr":"(c) Megan Timmons, all rights reserved, uploaded by Megan Timmons","desc":"Lilaeopsis chinensis, common names eastern grasswort, eastern lilaeopsis, marsh lilaeopsis, and lilaeopsis, is a plant that is native to North America.","fam":"Apiaceae","ord":"Apiales","cls":"Magnoliopsida","gr":"G5","sr":"S3","obs":187,"wiki":"https://en.wikipedia.org/wiki/Lilaeopsis_chinensis","inat":200069},{"s":"SC","c":"Mudwort","sci":"Limosella australis","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/94254592/original.jpeg","attr":"(c) Lily M, some rights reserved (CC BY-NC-ND), uploaded by Lily M","desc":"Limosella australis, common name Welsh mudwort, is an annual dicot plant that is indigenous to the United States and Canada. It has white flowers, and blooms between July and October. Its habitat is tidal mudflats, muddy or sandy shores It is listed as a special concern species in Connecticut.","fam":"Scrophulariaceae","ord":"Lamiales","cls":"Magnoliopsida","gr":"G5","sr":"S3","obs":1115,"wiki":"https://en.wikipedia.org/wiki/Limosella_australis","inat":60248},{"s":"E","c":"Twinflower","sci":"Linnaea borealis ssp. americana","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/297803408/original.jpg","attr":"(c) Li Jianong, some rights reserved (CC BY-NC), uploaded by Li Jianong","desc":"Linnaea borealis is a species of flowering plant in the family Caprifoliaceae. It is the only species in the genus Linnaea. It is a boreal to subarctic woodland subshrub, commonly known as twinflower.","fam":"Caprifoliaceae","ord":"Dipsacales","cls":"Magnoliopsida","gr":"G5","sr":"SNR","obs":40574,"wiki":"https://en.wikipedia.org/wiki/Linnaea","inat":77780},{"s":"SC","c":"Sandplain flax","sci":"Linum intercursum","n":"","ext":true,"fed":"","img":"https://static.inaturalist.org/photos/57398935/original.jpg","attr":"(c) Steven Daniel, all rights reserved, uploaded by Steven Daniel","desc":"Linum intercursum, common names sandplain flax and sandplain wild flax, is a perennial plant native to the United States.","fam":"Linaceae","ord":"Malpighiales","cls":"Magnoliopsida","gr":"G4","sr":"SH","obs":84,"wiki":"https://en.wikipedia.org/wiki/Linum_intercursum","inat":204344},{"s":"E","c":"Yellow flax","sci":"Linum sulcatum","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/10543629/original.jpg","attr":"(c) thesnaguy, some rights reserved (CC BY-NC-SA), uploaded by thesnaguy","desc":"Linum sulcatum, common names yellow flax, grooved yellow flax, grooved flax, and yellow wild flax is a plant native to the United States and Canada.","fam":"Linaceae","ord":"Malpighiales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":1784,"wiki":"https://en.wikipedia.org/wiki/Linum_sulcatum","inat":129626},{"s":"E","c":"Lily-leaved twayblade","sci":"Liparis liliifolia","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/386586764/original.jpg","attr":"(c) Nicholas Wei, some rights reserved (CC BY-SA), uploaded by Nicholas Wei","desc":"Liparis liliifolia, known as the brown widelip orchid, lily-leaved twayblade, large twayblade, and mauve sleekwort, is a species of orchid native to eastern Canada and the eastern United States. It can be found in a variety of habitats, such as forests, shrublands, thickets, woodlands, and mountains. The orchid is considered globally secure, but it is considered rare or endangered in many northeastern states.","fam":"Orchidaceae","ord":"Asparagales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":3148,"wiki":"https://en.wikipedia.org/wiki/Liparis_liliifolia","inat":204347},{"s":"T","c":"Dwarf bulrush","sci":"Lipocarpha micrantha","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/c/c6/Lipocarpha_micrantha_NRCS-1.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Lipocarpha micrantha, known as dwarf bulrush, small-flowered hemicarpha, small-flower halfchaff sedge, common hemicarpa and tiny-flowered sedge, is a species of flowering plant in the sedge family (Cyperaceae) native to North America.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":0,"wiki":"https://en.wikipedia.org/wiki/Lipocarpha_micrantha","inat":""},{"s":"SC","c":"Many-fruited false-loosestrife","sci":"Ludwigia polycarpa","n":"","ext":true,"fed":"","img":"https://static.inaturalist.org/photos/100239583/original.jpg","attr":"(c) Steven Daniel, all rights reserved, uploaded by Steven Daniel","desc":"Ludwigia polycarpa, common names many-fruited false-loosestrife and false loosestrife seedbox, is a plant found in North America. It is listed as a special concern and believed extirpated in Connecticut, and as endangered in Massachusetts, Pennsylvania and Vermont.","fam":"Onagraceae","ord":"Myrtales","cls":"Magnoliopsida","gr":"G4","sr":"SH","obs":253,"wiki":"https://en.wikipedia.org/wiki/Ludwigia_polycarpa","inat":164863},{"s":"E","c":"Globe-fruited false-loosestrife","sci":"Ludwigia sphaerocarpa","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/22403955/original.jpeg","attr":"(c) wsimmons, some rights reserved (CC BY-NC), uploaded by wsimmons","desc":"Ludwigia sphaerocarpa, common names globe-fruited false-loosestrife, globefruit primrose-willow, round-fruited false-loosestrife, globe-fruited seedbox, globe-fruited ludwigia, spherical-fruited seedbox and round-fruited false loosestrife; is a plant in the Myrtales family Onagraceae found in North America. It is listed as endangered in Connecticut,\n \nIndiana, Massachusetts and Rhode Island, and as threatened in Michigan and New York (state). It is listed as extirpated in Pennsylvania.","fam":"Onagraceae","ord":"Myrtales","cls":"Magnoliopsida","gr":"G4","sr":"S1","obs":105,"wiki":"https://en.wikipedia.org/wiki/Ludwigia_sphaerocarpa","inat":164867},{"s":"E","c":"Foxtail clubmoss","sci":"Lycopodiella alopecuroides","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/20589279/original.jpg","attr":"(c) BJ Stacey, some rights reserved (CC BY-NC), uploaded by BJ Stacey","desc":"Lycopodiella alopecuroides, the foxtail clubmoss, is a species of perennial vascular plant in the club-moss family, Lycopodiaceae. It is commonly found along the Atlantic seaboard and has recently been discovered in the state of Maine. The family, Lycopodiaceae contains nearly 15 genera and about 375 species","fam":"Lycopodiaceae","ord":"Lycopodiales","cls":"Lycopodiopsida","gr":"G5","sr":"S1","obs":2797,"wiki":"https://en.wikipedia.org/wiki/Lycopodiella_alopecuroides","inat":122049},{"s":"SC","c":"Clasping-leaved water-horehound","sci":"Lycopus amplectens","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/33030479/original.jpeg","attr":"(c) Eric M Powell, some rights reserved (CC BY-NC), uploaded by Eric M Powell","desc":"Lycopus amplectens, common names clasping-leaved water-horehound, sessile-leaved bugleweed, and sessile-leaved water-horehound, is a species of Lycopus native to North America. Its native range stretches from Massachusetts south to northeastern Florida.","fam":"Lamiaceae","ord":"Lamiales","cls":"Magnoliopsida","gr":"G5","sr":"S2","obs":142,"wiki":"https://en.wikipedia.org/wiki/Lycopus_amplectens","inat":164969},{"s":"SC","c":"Climbing fern","sci":"Lygodium palmatum","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/21424888/original.jpg","attr":"(c) Nate Martineau, some rights reserved (CC BY-NC), uploaded by Nate Martineau","desc":"Lygodium palmatum is the only species of its genus native to North America. Unlike most species in the genus, this one, called the American climbing fern, Hartford fern, or Alice's fern, is extremely hardy in temperate zones .The name \"Hartford Fern\" being derived from its former prevalence in Hartford and the surrounding Connecticut area. It was extensively used as a Christmas decoration by early settlers, leading to the first law protecting a plant species in the United States in 1869.","fam":"Lygodiaceae","ord":"Schizaeales","cls":"Polypodiopsida","gr":"G4","sr":"S3","obs":2065,"wiki":"https://en.wikipedia.org/wiki/Lygodium_palmatum","inat":82571},{"s":"SC","c":"Stagger-bush","sci":"Lyonia mariana","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/201072200/original.jpg","attr":"(c) samwilhelm, some rights reserved (CC BY-NC), uploaded by samwilhelm","desc":"Lyonia mariana, the Piedmont staggerbush or staggerbush, is a perennial shrub that is native to the United States. L. mariana is a shrub whose native range encompasses the southeastern United States, from Virginia to Florida. The shrub grows in habitats including pine flatwoods and sandhills, it displays adaptability to acidic soils. Recognized by its lance-shaped, glossy green leaves and clusters of white and pink tubular flowers, the Piedmont staggerbush contributes to the biodiversity of its ecosystem by providing shelter for wildlife and supporting pollinators. The plant contains grayanotoxins, making it potentially toxic if ingested.","fam":"Ericaceae","ord":"Ericales","cls":"Magnoliopsida","gr":"G5","sr":"SH","obs":2682,"wiki":"https://en.wikipedia.org/wiki/Lyonia_mariana","inat":164989},{"s":"E","c":"Winged loosestrife","sci":"Lythrum alatum","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/154879/original.jpg","attr":"(c) Jason Sharp, all rights reserved, uploaded by Jason Sharp","desc":"Lythrum alatum, commonly known as winged loosestrife, winged lythrum or angled purple-loosestrife, is a species of flowering plant belonging to the family Lythraceae. It is endemic to wetland areas in central and eastern United States and Ontario.","fam":"Lythraceae","ord":"Myrtales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":8977,"wiki":"https://en.wikipedia.org/wiki/Lythrum_alatum","inat":128998},{"s":"T","c":"Three-leaved false Solomon's-seal","sci":"Maianthemum trifolium","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/878485/original.jpg","attr":"(c) Superior National Forest, some rights reserved (CC BY)","desc":"Maianthemum trifolium is a species of flowering plant that is associated with extremely wet environments and is native to Canada and the northeastern United States as well as St. Pierre and Miquelon and Asia (Siberia).","fam":"Asparagaceae","ord":"Asparagales","cls":"Liliopsida","gr":"G5","sr":"S2","obs":4193,"wiki":"https://en.wikipedia.org/wiki/Maianthemum_trifolium","inat":118774},{"s":"SC","c":"Bayard's white adder's mouth","sci":"Malaxis bayardii","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/146429417/original.jpeg","attr":"(c) Dan Wall, some rights reserved (CC BY-NC), uploaded by Dan Wall","desc":"Malaxis bayardii, or Bayard's adder's-mouth orchid, is a species of orchid native to northeastern North America. It is found from Massachusetts to North Carolina, with isolated populations in Ohio and Nova Scotia. There are historical reports of the plant formerly growing in Vermont and New Jersey, but it seems to have been extirpated in those two states It grows in dry, open woods and pine barrens at elevations of less than 600 m.","fam":"Orchidaceae","ord":"Asparagales","cls":"Liliopsida","gr":"G1","sr":"SH","obs":12,"wiki":"https://en.wikipedia.org/wiki/Malaxis_bayardii","inat":165090},{"s":"E","c":"White adder's-mouth","sci":"Malaxis brachypoda","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/206100204/original.jpg","attr":"(c) er-birds, some rights reserved (CC BY), uploaded by er-birds","desc":"Malaxis monophyllos, the white adder's mouth, is a terrestrial species of orchid. It is widespread across much of Europe, Asia, and much of southern Canada. In the United States, it grows mostly in southern Alaska, New England and the Great Lakes region, with isolated populations reported from Colorado and California.","fam":"Orchidaceae","ord":"Asparagales","cls":"Liliopsida","gr":"T5","sr":"S1","obs":329,"wiki":"https://en.wikipedia.org/wiki/Malaxis_monophyllos","inat":165091},{"s":"E","c":"Green adder's-mouth","sci":"Malaxis unifolia","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/207733/original.jpg","attr":"(c) BlueRidgeKitties, some rights reserved (CC BY-NC-SA)","desc":"Malaxis unifolia, or the green adder's-mouth orchid, is a species of orchid occurring from eastern and central Canada, the central and eastern United States, Mexico, Central America and the Greater Antilles.","fam":"Orchidaceae","ord":"Asparagales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":1763,"wiki":"https://en.wikipedia.org/wiki/Malaxis_unifolia","inat":154999},{"s":"E","c":"Tall millet-grass","sci":"Milium effusum","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/8529192/original.jpeg","attr":"(c) Jeremy Barker, some rights reserved (CC BY-NC), uploaded by Jeremy Barker","desc":"Milium effusum, the American milletgrass or wood millet, is a species of flowering plant in the grass family Poaceae, native to damp forests of the Holarctic Kingdom.","fam":"Poaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":6889,"wiki":"https://en.wikipedia.org/wiki/Milium_effusum","inat":165390},{"s":"E","c":"Mountain sandwort","sci":"Minuartia glabra","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/b/bf/Minuartia_glabra.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Geocarpon glabrum, commonly called Appalachian stichwort, is a species of flowering plant in the carnation family (Caryophyllaceae). It is native to the eastern United States, where it has a scattered distribution.","fam":"Caryophyllaceae","ord":"Caryophyllales","cls":"Magnoliopsida","gr":"","sr":"","obs":0,"wiki":"https://en.wikipedia.org/wiki/Geocarpon_glabrum","inat":""},{"s":"SC","c":"Naked miterwort","sci":"Mitella nuda","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/14989744/original.jpg","attr":"(c) Janet Nelson, some rights reserved (CC BY-NC-ND), uploaded by Janet Nelson","desc":"Mitella nuda, the naked bishop's cap or naked miterwort, is a species of flowering plant in the family Saxifragaceae. It is a perennial or rhizomatous geophyte native to temperate and subarctic regions of northern North America and northeastern Asia, ranging across Canada and the northern United States, and from Western Siberia through Mongolia and northern China to Korea, Japan, and the Russian Far East.","fam":"Saxifragaceae","ord":"Saxifragales","cls":"Magnoliopsida","gr":"","sr":"","obs":5580,"wiki":"https://en.wikipedia.org/wiki/Mitella_nuda","inat":144149},{"s":"E","c":"Large-leaved sandwort","sci":"Moehringia macrophylla","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/3908325/original.jpg","attr":"(c) Wendy Feltham, some rights reserved (CC BY-NC), uploaded by Wendy Feltham","desc":"Moehringia macrophylla, commonly known as the largeleaf sandwort, is a species of flowering plant in the family Caryophyllaceae. It is native to parts of eastern and western North America, where it can be found in moist, shady habitat types, such as mountain forests. It is a rhizomatous perennial herb growing erect to about 18 centimeters in maximum height. The lance-shaped leaves are up to 5 centimeters long and oppositely arranged about the stem. The inflorescence is a cyme of 2 to 5 flowers, each with 5 pointed green sepals and 5 rounded white petals. The fruit is a toothed black capsule.","fam":"Caryophyllaceae","ord":"Caryophyllales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":4286,"wiki":"https://en.wikipedia.org/wiki/Moehringia_macrophylla","inat":61884},{"s":"E","c":"One-flower wintergreen","sci":"Moneses uniflora","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/379657569/original.jpg","attr":"(c) Thierry Arbault, some rights reserved (CC BY), uploaded by Thierry Arbault","desc":"Moneses uniflora, the one-flowered wintergreen, single delight, wax-flower, shy maiden, star of Bethlehem (Aleutians), St. Olaf's candlestick (Norway), wood nymph, or frog's reading lamp, is a plant of the family of Ericaceae, that is indigenous to moist coniferous forests in temperate regions of the Northern Hemisphere from Spain to Japan and across North America. It is the sole member of genus Moneses.","fam":"Ericaceae","ord":"Ericales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":10269,"wiki":"https://en.wikipedia.org/wiki/Moneses","inat":60376},{"s":"E","c":"Long-awn hairgrass","sci":"Muhlenbergia capillaris","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/101581372/original.jpeg","attr":"(c) Lauren McLaurin, some rights reserved (CC BY), uploaded by Lauren McLaurin","desc":"Muhlenbergia capillaris, commonly known as the hairawn muhly, is a perennial sedge-like plant that grows to be about 30\u201390\u00a0cm (0.98\u20132.95\u00a0ft) tall and 60\u201390\u00a0cm (2.0\u20133.0\u00a0ft) wide. The plant includes a double layer; green, leaf-like structures surround the understory, and purple-pink flowers outgrow them from the bottom up. The plant is a warm-season grass, meaning that leaves begin growth in the summer. During the summer, the leaves stay green, but they morph during the fall to produce a more copper color. The seasonal changes also include the flowers, as they grow out during the fall and stay healthy till the end of autumn. The muhly grows along the border of roads and on plain prairies. The grass clumps into herds, causing bush-like establishments in the area the hairawn muhly inhabits. The flowers are very feathery and add a cloudlike appearance to the top of the grass. It is native to eastern North America and can be used for a multitude of purposes, including ornamental gardening and farming. It was voted 2012 plant of the year by the Garden Club of America.","fam":"Poaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":5583,"wiki":"https://en.wikipedia.org/wiki/Muhlenbergia_capillaris","inat":165543},{"s":"E","c":"Slender water-milfoil","sci":"Myriophyllum alterniflorum","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/114769680/original.jpg","attr":"(c) rosshall, some rights reserved (CC BY-NC)","desc":"Myriophyllum alterniflorum, known as alternate water-milfoil or alternateflower watermilfoil, is a species of water-milfoil. It is native to Europe and Asia, has been introduced to North America and inhabits aquatic habitat, such as ponds and streams.","fam":"Haloragaceae","ord":"Saxifragales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":552,"wiki":"https://en.wikipedia.org/wiki/Myriophyllum_alterniflorum","inat":165601},{"s":"E","c":"Cutleaf water-milfoil","sci":"Myriophyllum pinnatum","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/4/45/Myriophyllum_pinnatum_BB-1913.png","attr":"Wikimedia Commons (CC BY-SA)","desc":"Myriophyllum pinnatum, common names cutleaf water-milfoil, green parrot's-feather, and pinnate water-milfoil, is a species of Myriophyllum.","fam":"Haloragaceae","ord":"Saxifragales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":0,"wiki":"https://en.wikipedia.org/wiki/Myriophyllum_pinnatum","inat":""},{"s":"T","c":"Northern water-milfoil","sci":"Myriophyllum sibiricum","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/49285117/original.jpeg","attr":"(c) Alexey P. Seregin, some rights reserved (CC BY-NC), uploaded by Alexey P. Seregin","desc":"Myriophyllum sibiricum is a species of water milfoil known by the common names shortspike watermilfoil, northern watermilfoil, and Siberian water-milfoil. It is native to Russia, China, and much of North America, where it grows in aquatic habitat such as ponds and streams. It generally grows over a meter long, its green stem drying white. It is lined with whorls of fanlike green leaves divided into many narrow, feathery lobes.","fam":"Haloragaceae","ord":"Saxifragales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":2120,"wiki":"https://en.wikipedia.org/wiki/Myriophyllum_sibiricum","inat":61034},{"s":"SC","c":"Large yellow pond lily","sci":"Nuphar advena","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/159999198/original.jpeg","attr":"(c) mfeaver, some rights reserved (CC BY), uploaded by mfeaver","desc":"Nuphar advena is a species of Nuphar native throughout the eastern United States and in some parts of Canada, as well as Mexico and Cuba. It is locally naturalized in Britain.","fam":"Nymphaeaceae","ord":"Nymphaeales","cls":"Magnoliopsida","gr":"T5","sr":"S1","obs":16370,"wiki":"https://en.wikipedia.org/wiki/Nuphar_advena","inat":82504},{"s":"SC","c":"Small yellow pond lily","sci":"Nuphar microphylla","n":"","ext":true,"fed":"","img":"https://static.inaturalist.org/photos/48306597/original.jpg","attr":"(c) Steven Daniel, all rights reserved, uploaded by Steven Daniel","desc":"Nuphar microphylla is a perennial, rhizomatous, aquatic herb found in North America. It is listed as a special concern and believed extirpated in Connecticut.","fam":"Nymphaeaceae","ord":"Nymphaeales","cls":"Magnoliopsida","gr":"T5","sr":"S1","obs":73,"wiki":"https://en.wikipedia.org/wiki/Nuphar_microphylla","inat":204367},{"s":"E","c":"Bog aster","sci":"Oclemena nemoralis","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/158685002/original.jpeg","attr":"(c) Celeste Echlin, all rights reserved, uploaded by Celeste Echlin","desc":"Oclemena nemoralis, commonly known as bog aster or bog nodding-aster, is a species of flowering plant in the aster family Asteraceae. It is native to northeastern North America. It is one of the parent species of the hybrid known as Blake's aster.","fam":"Asteraceae","ord":"Asterales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":2386,"wiki":"https://en.wikipedia.org/wiki/Oclemena_nemoralis","inat":165770},{"s":"SC","c":"Sundrops","sci":"Oenothera fruticosa","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/40166105/original.jpg","attr":"(c) kwillard, some rights reserved (CC BY-NC), uploaded by kwillard","desc":"Oenothera fruticosa, the narrowleaf evening primrose or narrow-leaved sundrops, is a species of flowering plant in the evening primrose family.","fam":"Onagraceae","ord":"Myrtales","cls":"Magnoliopsida","gr":"G5","sr":"SH","obs":4269,"wiki":"https://en.wikipedia.org/wiki/Oenothera_fruticosa","inat":129556},{"s":"E","c":"Prairie goldenrod","sci":"Oligoneuron album","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/c/c4/Solidago_ptarmicoides_Arkansas.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Solidago ptarmicoides, the prairie goldenrod, white flat-top goldenrod or upland white aster, is a North American perennial flowering plant in the family Asteraceae. It is native to the central and eastern Canada and parts of the United States (mostly Great Lakes region, the Northeast, the Ozarks, and the northern Great Plains, with isolated populations in Wyoming, Colorado, Oklahoma, and scattered locations in the Southeast. It has also been called upland white solidago, upland white goldenrod, and sneezewort goldenrod","fam":"Asteraceae","ord":"Asterales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":0,"wiki":"https://en.wikipedia.org/wiki/Solidago_ptarmicoides","inat":""},{"s":"E","c":"Stiff goldenrod","sci":"Oligoneuron rigidum","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/0/00/Solidago_rigida_%284991314459%29.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Solidago rigida, known by the common names stiff goldenrod and stiff-leaved goldenrod, is a North American plant species in the family Asteraceae. It has a widespread distribution in Canada and the United States, where it is found primarily east of the Rocky Mountains. It is typically found in open, dry areas associated with calcareous or sandy soil. Habitats include prairies, savannas, and glades.","fam":"Asteraceae","ord":"Asterales","cls":"Magnoliopsida","gr":"G4","sr":"","obs":0,"wiki":"https://en.wikipedia.org/wiki/Solidago_rigida","inat":""},{"s":"E","c":"Gravel-weed","sci":"Onosmodium virginianum","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/5/58/Onosmodium_virginianum_BB-1913.png","attr":"Wikimedia Commons (CC BY-SA)","desc":"Onosmodium virginianum, common names gravel-weed, wild Job's tears, false gromwell, and Virginia false-gromwell is perennial plant native to the eastern United States.","fam":"Boraginaceae","ord":"Boraginales","cls":"Magnoliopsida","gr":"G4","sr":"S1","obs":0,"wiki":"https://en.wikipedia.org/wiki/Onosmodium_virginianum","inat":""},{"s":"E","c":"Northern adder's-tongue","sci":"Ophioglossum pusillum","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/76955920/original.jpg","attr":"(c) Steven Daniel, all rights reserved, uploaded by Steven Daniel","desc":"Ophioglossum pusillum is a species of fern in the family Ophioglossaceae known by the common name northern adder's tongue.","fam":"Ophioglossaceae","ord":"Ophioglossales","cls":"Polypodiopsida","gr":"G4","sr":"S1","obs":214,"wiki":"https://en.wikipedia.org/wiki/Ophioglossum_pusillum","inat":59889},{"s":"E","c":"Southern adder's-tongue","sci":"Ophioglossum vulgatum","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/362994668/original.jpg","attr":"(c) Matthias Svojtka, some rights reserved (CC BY-NC), uploaded by Matthias Svojtka","desc":"Ophioglossum vulgatum, commonly known as adder's-tongue, southern adder's-tongue or adder's-tongue fern, is a species of fern in the family Ophioglossaceae.","fam":"Ophioglossaceae","ord":"Ophioglossales","cls":"Polypodiopsida","gr":"G4","sr":"S1","obs":2487,"wiki":"https://en.wikipedia.org/wiki/Ophioglossum_vulgatum","inat":61419},{"s":"SC","c":"Eastern prickly pear","sci":"Opuntia humifusa","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/80402277/original.jpg","attr":"(c) Megan Morgan, all rights reserved, uploaded by Megan Morgan","desc":"Opuntia humifusa, commonly known as the devil's-tongue, eastern prickly pear or Indian fig, is a cactus of the genus Opuntia present in parts of the eastern United States, southeastern Canada, and northeastern Mexico.","fam":"Cactaceae","ord":"Caryophyllales","cls":"Magnoliopsida","gr":"G5","sr":"S3","obs":11560,"wiki":"https://en.wikipedia.org/wiki/Opuntia_humifusa","inat":47894},{"s":"SC","c":"Golden club","sci":"Orontium aquaticum","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/35184254/original.jpg","attr":"(c) Marty, some rights reserved (CC BY-NC-ND), uploaded by Marty","desc":"Orontium aquaticum, sometimes called golden-club, floating arum, never-wets or tawkin, is a species of flowering plants in the family Araceae. It is the single living species in the genus Orontium, which also contains several extinct species described from fossils. O. aquaticum is endemic to the eastern United States and is found growing in ponds, streams, and shallow lakes. It prefers an acidic environment. The leaves are pointed and oval with a water repellent surface. The inflorescence is most notable for having an extremely small almost indistinguishable sheath surrounding the spadix. Very early in the flowering this green sheath withers away leaving only the spadix.","fam":"Araceae","ord":"Alismatales","cls":"Liliopsida","gr":"G5","sr":"S3","obs":4004,"wiki":"https://en.wikipedia.org/wiki/Orontium_aquaticum","inat":51138},{"s":"SC","c":"One-sided pyrola","sci":"Orthilia secunda","n":"","ext":true,"fed":"","img":"https://static.inaturalist.org/photos/216938573/original.jpg","attr":"(c) Anna Wyngaarden, all rights reserved, uploaded by Anna Wyngaarden","desc":"Orthilia is a genus of flowering plants in the family Ericaceae. It has only one species, Orthilia secunda. Its common names are sidebells wintergreen, one-sided-wintergreen and serrated-wintergreen. It is also called one-sided pyrola, one-sided shinleaf, and one-sided wintergreen. It was previously part of genus Pyrola, the wintergreens.","fam":"Ericaceae","ord":"Ericales","cls":"Magnoliopsida","gr":"G5","sr":"SH","obs":25402,"wiki":"https://en.wikipedia.org/wiki/Orthilia","inat":78288},{"s":"SC","c":"Violet wood-sorrel","sci":"Oxalis violacea","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/120266744/original.jpg","attr":"(c) walkmic, some rights reserved (CC BY-NC)","desc":"Oxalis violacea, the violet wood-sorrel, is a perennial plant and herb in the family Oxalidaceae. It is native to the eastern and central United States.","fam":"Oxalidaceae","ord":"Oxalidales","cls":"Magnoliopsida","gr":"G5","sr":"S3","obs":21683,"wiki":"https://en.wikipedia.org/wiki/Oxalis_violacea","inat":81796},{"s":"E","c":"Small's ragwort","sci":"Packera anonyma","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/4964780/original.jpg","attr":"(c) Kevin Metcalf, some rights reserved (CC BY-NC), uploaded by Kevin Metcalf","desc":"Packera anonyma, called Appalachian ragwort and Small's ragwort, is a flowering plant in the Asteraceae.","fam":"Asteraceae","ord":"Asterales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":9996,"wiki":"https://en.wikipedia.org/wiki/Packera_anonyma","inat":67825},{"s":"E","c":"Balsam groundsel","sci":"Packera paupercula","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/112498/original.jpg","attr":"(c) Peter Gorman, some rights reserved (CC BY-NC-SA)","desc":"Packera paupercula is a flowering plant species of the genus Packera and family Asteraceae, native to North America, where it is widespread across Canada and much of the United States. Its common names include balsam ragwort and balsam groundsel. It is a perennial herb that grows 1\u20133 feet tall. Its habitats include wet meadows, open woodlands, and rocky outcrops.","fam":"Asteraceae","ord":"Asterales","cls":"Magnoliopsida","gr":"G5","sr":"","obs":6647,"wiki":"https://en.wikipedia.org/wiki/Packera_paupercula","inat":127945},{"s":"SC","c":"American ginseng","sci":"Panax quinquefolius","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/5091105/original.jpeg","attr":"(c) Lori A Owenby, some rights reserved (CC BY-NC), uploaded by Lori A Owenby","desc":"American ginseng is a species of flowering plant in the ivy family Araliaceae. It is native to eastern North America although its cultivation was successfully introduced to China in 1975. The specific epithet quinquefolius means \"five-leaved\", which refers to the typical number of leaflets per leaf. It is one of a group of taxa known as \"ginseng\".","fam":"Araliaceae","ord":"Apiales","cls":"Magnoliopsida","gr":"G3","sr":"S2","obs":3824,"wiki":"https://en.wikipedia.org/wiki/American_ginseng","inat":116333},{"s":"T","c":"Bitter panicgrass","sci":"Panicum amarum var. amarum","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/163108864/original.jpg","attr":"(c) emrys_fergus, some rights reserved (CC BY-NC), uploaded by emrys_fergus","desc":"Panicum amarum is a species of grass known by the common name bitter panicum. It is native to North America, where it is found in coastal regions along the East Coast and Gulf Coast of the United States and into northeastern Mexico. It also occurs in The Bahamas and in Cuba.","fam":"Poaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"SNR","obs":2702,"wiki":"https://en.wikipedia.org/wiki/Panicum_amarum","inat":166067},{"s":"SC","c":"Warty panic grass","sci":"Panicum verrucosum","n":"","ext":true,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/3/3b/Panicum_verrucosum_NRCS-004.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Panicum verrucosum, common name warty panicgrass, is a plant in North America. It is listed as a special concern and believed extirpated in Connecticut. It is listed as threatened in Indiana and Michigan, and as endangered in Ohio.","fam":"Poaceae","ord":"Poales","cls":"Liliopsida","gr":"TNR","sr":"","obs":0,"wiki":"https://en.wikipedia.org/wiki/Panicum_verrucosum","inat":""},{"s":"SC","c":"Hairy forked chickweed","sci":"Paronychia fastigiata","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/301632793/original.jpeg","attr":"(c) Shaun Pogacnik, some rights reserved (CC BY-NC), uploaded by Shaun Pogacnik","desc":"Paronychia fastigiata, common names hairy forked chickweed, hairy forked nailwort, and forked chickweed, is an annual plant native to North America.","fam":"Caryophyllaceae","ord":"Caryophyllales","cls":"Magnoliopsida","gr":"G5","sr":"SH","obs":138,"wiki":"https://en.wikipedia.org/wiki/Paronychia_fastigiata","inat":166137},{"s":"T","c":"Field paspalum","sci":"Paspalum laeve","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/2629154/original.JPG","attr":"(c) Doug Mitchell, all rights reserved, uploaded by Doug Mitchell","desc":"Paspalum laeve common name field paspalum, is a plant found in North America. Its distribution ranges from the southeastern United States northward to New York and westward to Texas and Kansas.","fam":"Poaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S2","obs":714,"wiki":"https://en.wikipedia.org/wiki/Paspalum_laeve","inat":166180},{"s":"SC","c":"Thin paspalum","sci":"Paspalum setaceum var. psammophilum","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/9381709/original.jpeg","attr":"(c) Mark Kluge, some rights reserved (CC BY-NC), uploaded by Mark Kluge","desc":"Paspalum setaceum is a species of grass known by several common names, including thin paspalum. It is native to the Americas, where it can be found in the eastern and central United States, Ontario in Canada, Mexico, Central America, and the Caribbean. It can be found in other areas of the world as an introduced, and often invasive, species, including many Pacific Islands. It is a weed of lawns and turf.","fam":"Poaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"SNR","obs":3138,"wiki":"https://en.wikipedia.org/wiki/Paspalum_setaceum","inat":122592},{"s":"T","c":"Swamp lousewort","sci":"Pedicularis lanceolata","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/24280660/original.jpg","attr":"(c) Greg Funka, some rights reserved (CC BY-NC), uploaded by Greg Funka","desc":"Pedicularis lanceolata, the swamp lousewort, is a species of flowering plant native to the Midwestern and Northeastern United States and southern Canada. It is most often found in base-rich wetlands such as fens, springs, and wet meadows.","fam":"Orobanchaceae","ord":"Lamiales","cls":"Magnoliopsida","gr":"G4","sr":"S2","obs":3065,"wiki":"https://en.wikipedia.org/wiki/Pedicularis_lanceolata","inat":154328},{"s":"E","c":"Smooth cliff-brake","sci":"Pellaea glabella","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/72296/original.jpg","attr":"(c) Jason Hollinger, some rights reserved (CC BY)","desc":"Pellaea glabella is a fern with the common name smooth cliffbrake. It was once regarded as a reduced form or variety of Pellaea atropurpurea. P. glabella is known to exist in two cryptic species, one diploid and one tetraploid. The diploid reproduces sexually, while the tetraploid is normally apogamous. It is now known that the tetraploid form of the species is one of the parents of the original hybrid P.\u00a0\u00d7\u00a0atropurpurea that became the apogamous species.","fam":"Pteridaceae","ord":"Polypodiales","cls":"Polypodiopsida","gr":"G5","sr":"S1","obs":2790,"wiki":"https://en.wikipedia.org/wiki/Pellaea_glabella","inat":122083},{"s":"T","c":"Sweet coltsfoot","sci":"Petasites frigidus var. palmatus","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/272664283/original.jpg","attr":"(c) christinelind, some rights reserved (CC BY-NC)","desc":"Petasites frigidus, the Arctic sweet coltsfoot or Arctic butterbur, is a species of flowering plant in the family Asteraceae. It is native to Arctic to cool temperate regions of the Northern Hemisphere in northern Europe, northern Asia and northern North America.","fam":"Asteraceae","ord":"Asterales","cls":"Magnoliopsida","gr":"G5","sr":"SNR","obs":25588,"wiki":"https://en.wikipedia.org/wiki/Petasites_frigidus","inat":55780},{"s":"SC","c":"Wild kidney bean","sci":"Phaseolus polystachios var. polystachios","n":"","ext":true,"fed":"","img":"https://static.inaturalist.org/photos/64826346/original.jpg","attr":"(c) Paulette Haywood Ogard, all rights reserved, uploaded by Paulette Haywood Ogard","desc":"Phaseolus polystachios, also known as the thicket bean or wild kidney bean, is a perennial, herbaceous vine that is native to North America. It is unique among the Phaseolus in that its native range extends across the eastern temperate United States to southeast Canada, while most Phaseolus are tropical or subtropical. It is the namesake for the Polystachios group clade, which is the most species-rich within Phaseolus. In spite of its common name, it is more closely related to the lima bean, and it holds potential as a crop wild relative due to its resistance to white mold.","fam":"Fabaceae","ord":"Fabales","cls":"Magnoliopsida","gr":"G5","sr":"SNR","obs":598,"wiki":"https://en.wikipedia.org/wiki/Phaseolus_polystachios","inat":138680},{"s":"SC","c":"American reed","sci":"Phragmites americanus","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/f/fc/Phragmites_americanus_iN-11747103.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Phragmites americanus, common name American reed, is a species of plant found in North America. It is sometimes considered a subspecies of Phragmites australis. It is listed as a special concern in Connecticut.","fam":"Poaceae","ord":"Poales","cls":"Liliopsida","gr":"T5","sr":"S1","obs":0,"wiki":"https://en.wikipedia.org/wiki/Phragmites_americanus","inat":""},{"s":"E","c":"Red pine","sci":"Pinus resinosa","n":"(native populations only)","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/4013782/original.jpg","attr":"(c) timmenzies on Flickr, some rights reserved (CC BY-SA)","desc":"Pinus resinosa, known as red pine, is a pine native to Eastern North America, with a distributed from Pennsylvania and the Great Lakes region to Manitoba and Newfoundland. It is an adaptable species, and is a valuable forestry species in its native range. One of only two American members of subsection Pinus, the species is characterised by low genetic diversity.","fam":"Pinaceae","ord":"Pinales","cls":"Pinopsida","gr":"G5","sr":"S1","obs":24188,"wiki":"https://en.wikipedia.org/wiki/Pinus_resinosa","inat":52383},{"s":"E","c":"Slender mountain ricegrass","sci":"Piptatherum pungens","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/a/a1/Piptatheropsis_pungens_%28as_Oryzopsis_pungens%29_BB-1913.png","attr":"Wikimedia Commons (CC BY-SA)","desc":"Piptatherum pungens, also called Oryzopsis pungens, commonly called slender mountain-ricegrass, ricegrass, northern ricegrass, or slender mountain-rice, is a plant found in North America. It is listed as endangered in Connecticut, Iowa, New Jersey, and Pennsylvania. It is listed as extirpated in Indiana, as a special concern in Rhode Island, and as threatened in Vermont.","fam":"Poaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":0,"wiki":"https://en.wikipedia.org/wiki/Piptatherum_pungens","inat":""},{"s":"E","c":"Sickle-leaved golden aster","sci":"Pityopsis falcata","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/22752798/original.jpg","attr":"(c) jfflyfisher, some rights reserved (CC BY-NC)","desc":"Pityopsis falcata, commonly known as sickleleaf silkgrass, sickle-leaved golden aster, and New England Golden aster, is perennial plant in the family Asteraceae native to the northeastern Atlantic Coastal Plain of the United States.","fam":"Asteraceae","ord":"Asterales","cls":"Magnoliopsida","gr":"G4","sr":"S1","obs":1719,"wiki":"https://en.wikipedia.org/wiki/Pityopsis_falcata","inat":166937},{"s":"SC","c":"Hoary plantain","sci":"Plantago virginica","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/294656268/original.jpg","attr":"(c) Douglas Goldman, some rights reserved (CC BY-SA), uploaded by Douglas Goldman","desc":"Plantago virginica, common names hoary plantain and Virginia plantain, is a species of plant native to North America and introduced in Asia. It is listed as a special concern in Connecticut. The Kiowa use it to make garlands or wreaths for old men to wear around their heads during ceremonial dances as a symbol of health. It is commonly found within the continental United States in the majority of states along coastal areas and on roads, though has become an invasive species to eastern China after its introduction c. 1980. It is an annual plant, blooming around the month of May.","fam":"Plantaginaceae","ord":"Lamiales","cls":"Magnoliopsida","gr":"G5","sr":"SU","obs":9532,"wiki":"https://en.wikipedia.org/wiki/Plantago_virginica","inat":78622},{"s":"E","c":"White-fringed orchid","sci":"Platanthera blephariglottis","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/149085/original.JPG","attr":"(c) JodBot, some rights reserved (CC BY-NC-SA), uploaded by JodBot","desc":"Platanthera blephariglottis, commonly known as the white fringed orchid or white-fringed orchis, is a species of orchid of the genus Platanthera. It is considered to be an endangered species in Connecticut and Ohio, a threatened species in Florida, Maryland and Rhode Island, exploitably vulnerable in New York, and susceptible to be threatened in Qu\u00e9bec.","fam":"Orchidaceae","ord":"Asparagales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":3608,"wiki":"https://en.wikipedia.org/wiki/Platanthera_blephariglottis","inat":52499},{"s":"E","c":"Yellow-fringed orchid","sci":"Platanthera ciliaris","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/537775194/original.jpg","attr":"(c) Jeffrey Harris, all rights reserved, uploaded by Jeffrey Harris","desc":"Platanthera ciliaris, commonly known as the yellow fringed orchid or orange fringed orchid, is a large and showy species of orchid. Widely distributed across eastern North American, this orchid can be found along the longleaf pine landscapes of the Gulf Coast of the United States, as well as in various acidic wetlands, bogs, and pine savannas. Like many species in these habitats, it is dependent upon sunny, open conditions to thrive. Often, these environments are created from periodic disturbances such as recurring fires.","fam":"Orchidaceae","ord":"Asparagales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":3989,"wiki":"https://en.wikipedia.org/wiki/Platanthera_ciliaris","inat":167016},{"s":"SC","c":"Tall white bog orchid","sci":"Platanthera dilatata","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/140548724/original.jpg","attr":"(c) Jenifer Shapland, some rights reserved (CC BY-NC), uploaded by Jenifer Shapland","desc":"Platanthera dilatata, known as tall white bog orchid, bog candle, or boreal bog orchid is a species of orchid, a flowering plant in the family Orchidaceae, native to North America. It was first formally described in 1813 by Frederick Traugott Pursh as Orchis dilatata.","fam":"Orchidaceae","ord":"Asparagales","cls":"Liliopsida","gr":"G5","sr":"SH","obs":16109,"wiki":"https://en.wikipedia.org/wiki/Platanthera_dilatata","inat":78623},{"s":"SC","c":"Pale green orchid","sci":"Platanthera flava var. herbiola","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/26254/original.jpg","attr":"(c) amy_b, some rights reserved (CC BY-NC-SA)","desc":"Platanthera flava, the southern rein orchid or palegreen orchid, is a species of terrestrial orchid native to eastern North America, from Texas east to Florida, north to Ontario, Quebec and Nova Scotia.","fam":"Orchidaceae","ord":"Asparagales","cls":"Liliopsida","gr":"G5","sr":"SU","obs":1339,"wiki":"https://en.wikipedia.org/wiki/Platanthera_flava","inat":68598},{"s":"SC","c":"Hooker's orchid","sci":"Platanthera hookeri","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/77725072/original.jpeg","attr":"(c) allenwoodliffe, some rights reserved (CC BY-NC), uploaded by allenwoodliffe","desc":"Platanthera hookeri, otherwise known as Hooker's orchid or Hooker's bog orchid, is a perennial wildflower in the genus Platanthera that can be found in temperate regions of North America ranging from Iowa to Newfoundland.","fam":"Orchidaceae","ord":"Asparagales","cls":"Liliopsida","gr":"G4","sr":"SH","obs":639,"wiki":"https://en.wikipedia.org/wiki/Platanthera_hookeri","inat":167019},{"s":"SC","c":"Large round-leaved orchid","sci":"Platanthera orbiculata","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/220577635/original.jpg","attr":"(c) Nate Martineau, some rights reserved (CC BY-NC), uploaded by Nate Martineau","desc":"Platanthera orbiculata, the round leaved orchid or lesser roundleaved orchid, is a species of orchid native to forested areas of North America. It is widespread across most of Canada and parts of the United States.","fam":"Orchidaceae","ord":"Asparagales","cls":"Liliopsida","gr":"G5","sr":"SH","obs":3021,"wiki":"https://en.wikipedia.org/wiki/Platanthera_orbiculata","inat":131218},{"s":"SC","c":"Clammy-weed","sci":"Polanisia dodecandra","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/350716/original.jpg","attr":"no rights reserved","desc":"Polanisia dodecandra is a species of flowering plant in the Cleomaceae family, known by the common name redwhisker clammyweed or clammyweed, and there are three subspecies of Polanisia. Usually annual, occasionally perennial, Polanisia is native to North America, and is found throughout much of Canada and the United States. It favors full sun, mesic to dry conditions, and barren, sandy or gravelly soils, even highly disturbed areas where there is little other ground vegetation. It looks similar to a close relative, the spider flower (Cleome).","fam":"Cleomaceae","ord":"Brassicales","cls":"Magnoliopsida","gr":"G5","sr":"SH","obs":10332,"wiki":"https://en.wikipedia.org/wiki/Polanisia_dodecandra","inat":78664},{"s":"SC","c":"Alternate milkwort","sci":"Polygala ambigua","n":"","ext":false,"fed":"","img":"https://newfs.s3.amazonaws.com/taxon-images-1000s1000/Polygalaceae/polygala-ambigua-ha-jsachs.jpg","attr":"Jason Sachs / Native Plant Trust","desc":"Polygala ambigua may refer to two different species of plants:Polygala ambigua Nutt., a taxonomic synonym for Senega ambigua\nPolygala ambigua Torr. & A.Gray, a taxonomic synonym for Senega nuttallii\n","fam":"Polygalaceae","ord":"Fabales","cls":"Magnoliopsida","gr":"","sr":"","obs":0,"wiki":"https://en.wikipedia.org/wiki/Polygala_ambigua","inat":""},{"s":"E","c":"Field milkwort","sci":"Polygala cruciata","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/0/0b/Polygala_cruciata_Eastern_Highland_Rim.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Senega cruciata, commonly called drumheads milkwort, is a species of flowering plant in the milkwort family. It is native to eastern North America, where it is found in scattered localities, particularly around the Coastal Plain, the Great Lakes, and the southern Appalachian Mountains. It is found most often in wet, sandy prairies and marshes.","fam":"Polygalaceae","ord":"Fabales","cls":"Magnoliopsida","gr":"","sr":"","obs":0,"wiki":"https://en.wikipedia.org/wiki/Senega_cruciata","inat":""},{"s":"T","c":"Nuttall's milkwort","sci":"Polygala nuttallii","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/f/ff/Annual_report_of_the_New_Jersey_State_Museum_%281910%29_%2819178055560%29.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Senega nuttallii is a species of flowering plant in the milkwort family (Polygalaceae). It is endemic to the United States.","fam":"Polygalaceae","ord":"Fabales","cls":"Magnoliopsida","gr":"","sr":"","obs":0,"wiki":"https://en.wikipedia.org/wiki/Senega_nuttallii","inat":""},{"s":"E","c":"Seneca snakeroot","sci":"Polygala senega","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/7/79/Polygala_senega_2.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Senega officinalis is a species of flowering plant in the milkwort family, Polygalaceae. It is native to North America, where it is found in southern Canada and the central and eastern United States. Its common names include Seneca snakeroot, senega snakeroot, senegaroot, rattlesnake root, and mountain flax. Its genus name honors the Seneca people, a Native American group who used the plant to treat snakebite.","fam":"Polygalaceae","ord":"Fabales","cls":"Magnoliopsida","gr":"","sr":"","obs":0,"wiki":"https://en.wikipedia.org/wiki/Senega_officinalis","inat":""},{"s":"SC","c":"Seabeach knotweed","sci":"Polygonum glaucum","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/430814110/original.jpeg","attr":"no rights reserved, uploaded by Dan Wilder","desc":"Polygonum glaucum, common names seabeach knotweed and seaside knotweed, is a North American species of plant in the buckwheat family. It grows on the Atlantic Coast of the United States, from Alabama to Massachusetts, including in salt-water inlets such as Chesapeake Bay and the Hudson River.","fam":"Polygonaceae","ord":"Caryophyllales","cls":"Magnoliopsida","gr":"","sr":"","obs":148,"wiki":"https://en.wikipedia.org/wiki/Polygonum_glaucum","inat":167242},{"s":"E","c":"Small-flowered leafcup","sci":"Polymnia canadensis","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/95847304/original.jpeg","attr":"(c) Tyler Yates, all rights reserved, uploaded by Tyler Yates","desc":"Polymnia canadensis, commonly known as whiteflower leafcup, is a flowering perennial plant in the family Asteraceae. It is native to eastern North America from Ontario south to Alabama and from Kansas, Oklahoma, and Minnesota east to North Carolina, Vermont and Connecticut. It is considered endangered in the last two states. It is typically found in moist forests over calcareous rocks.","fam":"Asteraceae","ord":"Asterales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":10833,"wiki":"https://en.wikipedia.org/wiki/Polymnia_canadensis","inat":85383},{"s":"T","c":"Swamp cottonwood","sci":"Populus heterophylla","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/78313406/original.jpeg","attr":"(c) David Weisenbeck, some rights reserved (CC BY), uploaded by David Weisenbeck","desc":"Populus heterophylla, also known as downy poplar, swamp poplar and swamp cottonwood, is a large deciduous poplar belonging to the Populus genus of the family Salicaceae. This species can grow on sites that have too much water for other native poplars. On the IUCN Red List this species is listed as \"least concern\".","fam":"Salicaceae","ord":"Malpighiales","cls":"Magnoliopsida","gr":"G4","sr":"S2","obs":896,"wiki":"https://en.wikipedia.org/wiki/Populus_heterophylla","inat":167295},{"s":"E","c":"Tuckerman's pondweed","sci":"Potamogeton confervoides","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/29782028/original.jpeg","attr":"(c) Joseph D Kurtz, some rights reserved (CC BY-NC), uploaded by Joseph D Kurtz","desc":"Potamogeton confervoides, common names pondweed, alga-like pondweed, algae-like pondweed, and Tuckerman's pondweed is a species of plant found in North America. It is listed as endangered in Connecticut, as a special concern in Maine, as threatened in Massachusetts, New York (state), Pennsylvania, and Wisconsin. It is listed as historical in Rhode Island.","fam":"Potamogetonaceae","ord":"Alismatales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":59,"wiki":"https://en.wikipedia.org/wiki/Potamogeton_confervoides","inat":167320},{"s":"E","c":"Fries' pondweed","sci":"Potamogeton friesii","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/63400898/original.jpeg","attr":"(c) Gennadiy Okatov, some rights reserved (CC BY-NC), uploaded by Gennadiy Okatov","desc":"Potamogeton friesii, known as flat-stalked pondweed, or Fries' pondweed, is an aquatic plant in the genus Potamogeton. It grows mainly in mesotrophic to eutrophic rivers, lakes, ponds and ditches, rarely in brackish water. It occurs in North America, Europe, western Asia and a few scattered locations elsewhere in Asia.","fam":"Potamogetonaceae","ord":"Alismatales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":153,"wiki":"https://en.wikipedia.org/wiki/Potamogeton_friesii","inat":167322},{"s":"T","c":"Capillary pondweed","sci":"Potamogeton gemmiparus","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/1/13/BB-0201_Potamogeton_gemmiparus.png","attr":"Wikimedia Commons (CC BY-SA)","desc":"Potamogeton gemmiparus, is a species of plant found in North America. It is also known as Potamogeton pusillus var. gemmiparus, common names capillary pondweed, slender pondweed, and budding pondweed. It is listed as threatened in Connecticut and in New Hampshire, as rare in Indiana, and as a special concern in Rhode Island.","fam":"Potamogetonaceae","ord":"Alismatales","cls":"Liliopsida","gr":"T2","sr":"S1","obs":0,"wiki":"https://en.wikipedia.org/wiki/Potamogeton_gemmiparus","inat":""},{"s":"E","c":"Hill's pondweed","sci":"Potamogeton hillii","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/220803695/original.jpeg","attr":"(c) Pauline Catling, all rights reserved, uploaded by Pauline Catling","desc":"Potamogeton hillii, common name Hill's pondweed, is a species of plant found in North America. It is listed as endangered in Connecticut, Ohio, and Pennsylvania. It is listed as a special concern in Massachusetts and as threatened in Michigan and New York (state).","fam":"Potamogetonaceae","ord":"Alismatales","cls":"Liliopsida","gr":"G3","sr":"S1","obs":74,"wiki":"https://en.wikipedia.org/wiki/Potamogeton_hillii","inat":118757},{"s":"E","c":"Ogden's pondweed","sci":"Potamogeton ogdenii","n":"","ext":false,"fed":"","img":"https://newfs.s3.amazonaws.com/taxon-images-1000s1000/Potamogetonaceae/potamogeton-ogdenii-le-jgarrett.jpg","attr":"Jennifer Garrett / Native Plant Trust","desc":"Potamogeton ogdenii, common name Ogden's pondweed, is a perennial plant native to North America.","fam":"Potamogetonaceae","ord":"Alismatales","cls":"Liliopsida","gr":"GNA","sr":"SNA","obs":0,"wiki":"https://en.wikipedia.org/wiki/Potamogeton_ogdenii","inat":""},{"s":"E","c":"Straight-leaved pondweed","sci":"Potamogeton strictifolius","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/553126/original.jpeg","attr":"(c) Smithsonian Institution, National Museum of Natural History, Department of Botany, some rights reserved (CC BY-NC-SA)","desc":"Potamogeton strictifolius, common names straight-leaved pondweed, pondweed, straight-leaf pondweed, and narrow-leaved pondweed, is a species of plant found in North America. It is listed as endangered in Connecticut, Illinois, Indiana, Massachusetts, and in New York (state). It is listed as possibly extirpated in Maine, and presumed extirpated in Ohio.","fam":"Potamogetonaceae","ord":"Alismatales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":38,"wiki":"https://en.wikipedia.org/wiki/Potamogeton_strictifolius","inat":167331},{"s":"T","c":"Vasey's pondweed","sci":"Potamogeton vaseyi","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/9267956/original.jpg","attr":"(c) Brenton Butterfield, all rights reserved, uploaded by Brenton Butterfield","desc":"Potamogeton vaseyi is a species of flowering plant in the pondweed family Potamogetonaceae. It is native to North America. The specific epithet vaseyi honors the American botanist George Vasey. The species is commonly called Vasey's pondweed.","fam":"Potamogetonaceae","ord":"Alismatales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":80,"wiki":"https://en.wikipedia.org/wiki/Potamogeton_vaseyi","inat":167334},{"s":"SC","c":"Alleghany plum","sci":"Prunus alleghaniensis","n":"","ext":true,"fed":"","img":"https://static.inaturalist.org/photos/39157043/original.jpg","attr":"(c) Greg J Schmidt, all rights reserved, uploaded by Greg J Schmidt","desc":"Prunus alleghaniensis, the Allegheny plum, is a species of New World plum, native to the Appalachian Mountains.","fam":"Rosaceae","ord":"Rosales","cls":"Magnoliopsida","gr":"","sr":"","obs":39,"wiki":"https://en.wikipedia.org/wiki/Prunus_alleghaniensis","inat":118759},{"s":"SC","c":"Graves beach plum","sci":"Prunus maritima var. gravesii","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/24175601/original.jpeg","attr":"(c) Tom Norton, some rights reserved (CC BY), uploaded by Tom Norton","desc":"Prunus maritima, the beach plum, is a species of plum native to the East Coast of the United States. It is a choice wild edible and its few pests and salt tolerance make it a resilient fruit crop for degraded lands and urban soils.","fam":"Rosaceae","ord":"Rosales","cls":"Magnoliopsida","gr":"G4","sr":"S4","obs":4758,"wiki":"https://en.wikipedia.org/wiki/Prunus_maritima","inat":64543},{"s":"SC","c":"Goose grass","sci":"Puccinellia pumila","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/396350199/original.jpg","attr":"(c) jamie_fenneman, some rights reserved (CC BY-NC)","desc":"Puccinellia pumila is a species of grass known by the common names dwarf akaligrass and smooth alkali grass. It is native to North America where it grows along the coastline in the northern latitudes, from Alaska across Arctic northern Canada to Greenland. It occurs on the coast of the Pacific Northwest in the United States and it is known from the Kamchatka Peninsula. The grass is only found on the coast, in wetland habitat, beaches, and areas inundated by the highest tides, in saline sand and mud. This perennial grass grows decumbent or erect to a maximum height near 40 centimeters, often remaining much smaller, especially in harsh habitat. It may root at stem nodes which become buried in wet substrate. The inflorescence is a dense or open array of branches bearing spikelets.","fam":"Poaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"SH","obs":50,"wiki":"https://en.wikipedia.org/wiki/Puccinellia_pumila","inat":78785},{"s":"E","c":"Torrey mountain-mint","sci":"Pycnanthemum torrei","n":"","ext":false,"fed":"","img":"https://newfs.s3.amazonaws.com/taxon-images-1000s1000/Lamiaceae/pycnanthemum-torrei-fl-mhassler.jpg","attr":"Michael Hassler / Native Plant Trust","desc":"Pycnanthemum torreyi, common name Torrey's mountainmint, is a perennial plant native to the United States.","fam":"Lamiaceae","ord":"Lamiales","cls":"Magnoliopsida","gr":"G2","sr":"S1","obs":0,"wiki":"https://en.wikipedia.org/wiki/Pycnanthemum_torreyi","inat":""},{"s":"SC","c":"Bur oak","sci":"Quercus macrocarpa","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/22786993/original.jpeg","attr":"(c) rayrob, some rights reserved (CC BY-NC), uploaded by rayrob","desc":"Quercus macrocarpa, the bur oak or burr oak, is a species of oak tree native to central and eastern North America. It is in the white oak section, Quercus sect. Quercus, and is also called mossycup oak, mossycup white oak, or scrub oak. The acorns are the largest of any North American oak, and are important food for wildlife.","fam":"Fagaceae","ord":"Fagales","cls":"Magnoliopsida","gr":"G5","sr":"SU","obs":48073,"wiki":"https://en.wikipedia.org/wiki/Quercus_macrocarpa","inat":54781},{"s":"E","c":"Water-plantain spearwort","sci":"Ranunculus ambigens","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/2053328/original.JPG","attr":"(c) Scott Schuette, some rights reserved (CC BY-NC), uploaded by Scott Schuette","desc":"Ranunculus ambigens, common names water-plantain spearwort, water plantain, and spearwort, is a plant found in the eastern part of North America. It is listed as endangered in Connecticut, and New Hampshire; as endangered and extirpated in Maryland; as a special concern in Kentucky; as possibly extirpated in Maine; as threatened in Michigan; and as a special concern in Rhode Island.","fam":"Ranunculaceae","ord":"Ranunculales","cls":"Magnoliopsida","gr":"G2","sr":"S1","obs":13,"wiki":"https://en.wikipedia.org/wiki/Ranunculus_ambigens","inat":118754},{"s":"E","c":"Seaside crowfoot","sci":"Ranunculus cymbalaria","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/f/f3/Ranunculuscymbalaria.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Halerpestes cymbalaria is a species of buttercup known by the common names alkali buttercup and seaside buttercup. It is native to much of Eurasia and parts of North and South America, where it grows in many types of habitat, especially in moist to wet areas such as marshes, bogs, and moist spring meadows. It is a perennial herb producing several stems a few centimeters to nearly 40 centimeters long. Some are prostrate against the ground and are stolons which root in moist substrate, and some are erect. The leaves are variable in shape, the basal ones with notched or slightly divided leaf blades borne on long petioles, and any upper leaves much reduced in size. The inflorescence bears one or more flowers on erect stalks. The flower has five to eight pale yellow petals, each under a centimeter long. The protruding receptacle at the center of the flower becomes a cylindrical cluster of fruits, each of which is an achene.","fam":"Ranunculaceae","ord":"Ranunculales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":0,"wiki":"https://en.wikipedia.org/wiki/Halerpestes_cymbalaria","inat":""},{"s":"SC","c":"Creeping spearwort","sci":"Ranunculus flammula var. reptans","n":"","ext":true,"fed":"","img":"https://static.inaturalist.org/photos/392293472/original.jpg","attr":"(c) Honza Gr\u00fcnwald, all rights reserved, uploaded by Honza Gr\u00fcnwald","desc":"Ranunculus flammula, the lesser spearwort, greater creeping spearwort or banewort, is a species of perennial herbaceous plants in the genus Ranunculus (buttercup), growing in damp places throughout the Boreal Kingdom. It flowers June/July. Ranunculus flammula is poisonous.\nIt is very closely related to R. reptans, which is distinguished by prostrate and more slender stems, narrower leaves and smaller flowers and is sometimes included within R. flammula sensu lato as a variety.","fam":"Ranunculaceae","ord":"Ranunculales","cls":"Magnoliopsida","gr":"G5","sr":"","obs":9440,"wiki":"https://en.wikipedia.org/wiki/Ranunculus_flammula","inat":67826},{"s":"SC","c":"Bristly buttercup","sci":"Ranunculus pensylvanicus","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/338178750/original.jpeg","attr":"(c) wanderingeden, some rights reserved (CC BY-NC), uploaded by wanderingeden","desc":"Ranunculus pensylvanicus is a flowering plant species in the buttercup family, Ranunculaceae. Common names include bristly buttercup, bristly crowfoot and Pennsylvania buttercup. It is native to North America with a distribution over the northern part of the continent.","fam":"Ranunculaceae","ord":"Ranunculales","cls":"Magnoliopsida","gr":"G5","sr":"SU","obs":1210,"wiki":"https://en.wikipedia.org/wiki/Ranunculus_pensylvanicus","inat":167747},{"s":"T","c":"Labrador tea","sci":"Rhododendron groenlandicum","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/44570815/original.jpeg","attr":"no rights reserved, uploaded by agbelliveau","desc":"Rhododendron groenlandicum, known by the common names bog Labrador tea, muskeg tea, swamp tea, in northern Canada, Hudson's Bay tea, and in Greenlandic, Qajaasaq, is a species of flowering shrub in the family Ericaceae. Found in northern parts of North America and Greenland, R.\u00a0groenlandicum grows primarily in bogs and other wetlands, which tend to be also in cold, acidic, and nutrient-poor environments. It has traditionally been used to make medicinal herbal teas among the Dene, Athabaskan, and Inuit, and other indigenous cultures of North America peoples.","fam":"Ericaceae","ord":"Ericales","cls":"Magnoliopsida","gr":"G5","sr":"S2","obs":28407,"wiki":"https://en.wikipedia.org/wiki/Rhododendron_groenlandicum","inat":180413},{"s":"SC","c":"Fragrant sumac","sci":"Rhus aromatica","n":"(native populations only)","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/310253516/original.jpg","attr":"(c) Catherine C. Galley, some rights reserved (CC BY), uploaded by Catherine C. Galley","desc":"Rhus aromatica, commonly known as fragrant sumac, smooth sumac, aromatic sumac, lemon sumac, skunk bush, polecat bush, polecat sumac, or simply sumac, is a deciduous shrub in the family Anacardiaceae native to North America. It is native to southern and eastern Canada, most of the contiguous United States, and Mexico.","fam":"Anacardiaceae","ord":"Sapindales","cls":"Magnoliopsida","gr":"G5","sr":"SH","obs":35970,"wiki":"https://en.wikipedia.org/wiki/Rhus_aromatica","inat":58738},{"s":"E","c":"Needle beaksedge","sci":"Rhynchospora capillacea","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/76284211/original.jpg","attr":"(c) Tab Tannery, some rights reserved (CC BY-NC-SA)","desc":"Rhynchospora capillacea is a species of sedge known by the common names needle beaksedge, slender beakrush and needle beakrush. It is native to eastern North America from Labrador to Alberta, and south to Texas. It grows in wet, usually calcareous habitat, such as fens, sandy or stony shores, interdunal flats, and wet meadows It is a perennial herb producing clumps of stems 10 to 40 centimetres tall, each stem with very narrow, filiform leaves. The inflorescence consists of few (1\u20134) narrow brown spikelets each about 6 or 7 millimetres long.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G4","sr":"S1","obs":405,"wiki":"https://en.wikipedia.org/wiki/Rhynchospora_capillacea","inat":167848},{"s":"T","c":"Tall beaksedge","sci":"Rhynchospora macrostachya","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/143310669/original.jpg","attr":"(c) Keith Bradley, some rights reserved (CC BY-NC), uploaded by Keith Bradley","desc":"Rhynchospora macrostachya, the tall horned beaksedge or tall beaksedge, is a plant in the sedge family, Cyperaceae. It is a perennial.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G4","sr":"S1","obs":474,"wiki":"https://en.wikipedia.org/wiki/Rhynchospora_macrostachya","inat":167881},{"s":"E","c":"Long-beaked beaksedge","sci":"Rhynchospora scirpoides","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/152836349/original.jpg","attr":"(c) Nate Martineau, some rights reserved (CC BY-NC), uploaded by Nate Martineau","desc":"Rhynchospora scirpoides, also referred to as Psilocarya scirpoides; common names long-beaked beaksedge and long-beaked bald rush; is a plant in the Rhynchospora genus found in North America.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G4","sr":"S1","obs":81,"wiki":"https://en.wikipedia.org/wiki/Rhynchospora_scirpoides","inat":167901},{"s":"SC","c":"Skunk currant","sci":"Ribes glandulosum","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/38735878/original.jpg","attr":"(c) Mary Jane, some rights reserved (CC BY-NC), uploaded by Mary Jane","desc":"Ribes glandulosum, or the skunk currant, is a North American species of flowering plant in the currant family.","fam":"Grossulariaceae","ord":"Saxifragales","cls":"Magnoliopsida","gr":"G5","sr":"S2","obs":4496,"wiki":"https://en.wikipedia.org/wiki/Ribes_glandulosum","inat":85475},{"s":"SC","c":"Swamp black currant","sci":"Ribes lacustre","n":"","ext":true,"fed":"","img":"https://static.inaturalist.org/photos/377392354/original.jpg","attr":"(c) madeline mundt, all rights reserved, uploaded by madeline mundt","desc":"Ribes lacustre is a species of flowering plant known by the common names prickly currant, bristly black currant, black swamp gooseberry, and black gooseberry. It is a shrub widely distributed in North America.","fam":"Grossulariaceae","ord":"Saxifragales","cls":"Magnoliopsida","gr":"G5","sr":"SH","obs":10210,"wiki":"https://en.wikipedia.org/wiki/Ribes_lacustre","inat":78858},{"s":"SC","c":"Wild currant","sci":"Ribes rotundifolium","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/252341850/original.jpeg","attr":"(c) smartinbiologist, some rights reserved (CC BY-NC)","desc":"Ribes rotundifolium is a North American species of currant known by the common names wild gooseberry and Appalachian gooseberry. It is native to the eastern United States, primarily the Adirondacks, from Massachusetts and the Appalachian Mountains south as far as South Carolina and Tennessee.","fam":"Grossulariaceae","ord":"Saxifragales","cls":"Magnoliopsida","gr":"G5","sr":"SU","obs":795,"wiki":"https://en.wikipedia.org/wiki/Ribes_rotundifolium","inat":167920},{"s":"E","c":"Swamp red currant","sci":"Ribes triste","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/286713581/original.jpeg","attr":"(c) Christina Yu, all rights reserved, uploaded by Christina Yu","desc":"Ribes triste, known as the northern redcurrant, swamp redcurrant, or wild redcurrant, is an Asian and North American shrub in the gooseberry family.","fam":"Grossulariaceae","ord":"Saxifragales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":3549,"wiki":"https://en.wikipedia.org/wiki/Ribes_triste","inat":118750},{"s":"SC","c":"Shining rose","sci":"Rosa nitida","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/207732/original.jpg","attr":"(c) Sakurai Midori, some rights reserved (CC BY-SA)","desc":"Rosa nitida, also known as shining rose due to its glossy leaves, is a perennial shrub in the rose family Rosaceae native to northeastern North America.","fam":"Rosaceae","ord":"Rosales","cls":"Magnoliopsida","gr":"G5","sr":"SH","obs":368,"wiki":"https://en.wikipedia.org/wiki/Rosa_nitida","inat":155003},{"s":"T","c":"Toothcup","sci":"Rotala ramosior","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/315669468/original.jpg","attr":"(c) bbuzas, some rights reserved (CC BY-NC)","desc":"Rotala ramosior is a species of flowering plant in the loosestrife family known by the common name lowland rotala. This aquatic or semiaquatic plant is native to North America, where it grows in lakes, streams, and irrigation ditches. The branching stems of the plant grow to about 40\u00a0cm long. Leaves are decussate, arranged oppositely in perpendicular pairs along the stems. The leaves are linear to lance-shaped to oval and up to 5\u00a0cm long. Flowers occur singly in leaf axils. Each has triangular sepals with long, narrow appendages and usually four tiny white petals in shades of pink to white. This plant is sometimes grown in aquariums.","fam":"Lythraceae","ord":"Myrtales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":1151,"wiki":"https://en.wikipedia.org/wiki/Rotala_ramosior","inat":78889},{"s":"SC","c":"Sand blackberry","sci":"Rubus cuneifolius","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/144544887/original.jpg","attr":"(c) Gary A. Paul, all rights reserved, uploaded by Gary A. Paul","desc":"Rubus cuneifolius, the sand blackberry, is a North American species of flowering plant in the rose family. It occurs in the eastern United States in every coastal state from Louisiana to New Hampshire, with the exception of Rhode Island. There are also reports of inland populations in Tennessee, Arkansas, and Oklahoma, and the species has become an invasive species in South Africa.","fam":"Rosaceae","ord":"Rosales","cls":"Magnoliopsida","gr":"GNR","sr":"SNR","obs":4491,"wiki":"https://en.wikipedia.org/wiki/Rubus_cuneifolius","inat":128854},{"s":"E","c":"Dew-drop","sci":"Rubus dalibarda","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/310266667/original.jpeg","attr":"(c) Tania Thiffeault, some rights reserved (CC BY-NC), uploaded by Tania Thiffeault","desc":"Rubus repens (dewdrop, false violet, star violet, Robin runaway. French Canadian: dalibarde rampante) is a perennial plant in the rose family, native to eastern and central Canada and to the northeastern and north-central United States. It is part of the genus Rubus, which includes brambles, blackberries, and raspberries. Some authorities consider it the sole member of a separate genus, Dalibarda. It is fairly easily grown in shady locations in damp to wet, acidic soils, and is frequently used in wildflower and bog gardens as a ground-cover.","fam":"Rosaceae","ord":"Rosales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":3859,"wiki":"https://en.wikipedia.org/wiki/Rubus_repens","inat":130751},{"s":"SC","c":"Sea-side dock","sci":"Rumex persicarioides","n":"","ext":true,"fed":"","img":"https://newfs.s3.amazonaws.com/taxon-images-1000s1000/Polygonaceae/rumex-pallidus-ha-mlovit-b.jpg","attr":"Marilee Lovit / Native Plant Trust","desc":"Rumex persicarioides is a flowering dicot species in the family Polygonaceae. This species flowers annually in the summer-time but on rare occasions it has been found to be biennial. R. persicarioides is not cultivated for human use and should not be confused with the similarly named genus Persicariae.","fam":"Polygonaceae","ord":"Caryophyllales","cls":"Magnoliopsida","gr":"G5","sr":"SH","obs":0,"wiki":"https://en.wikipedia.org/wiki/Rumex_persicarioides","inat":""},{"s":"SC","c":"Large marsh pink","sci":"Sabatia dodecandra","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/142834919/original.jpeg","attr":"(c) Sharleen, some rights reserved (CC BY-NC), uploaded by Sharleen","desc":"Sabatia dodecandra, common names large marsh pink or marsh rose gentian, is a plant in the Gentianaceae family.","fam":"Gentianaceae","ord":"Gentianales","cls":"Magnoliopsida","gr":"G4","sr":"","obs":258,"wiki":"https://en.wikipedia.org/wiki/Sabatia_dodecandra","inat":168265},{"s":"E","c":"Marsh pink","sci":"Sabatia stellaris","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/136317758/original.jpeg","attr":"(c) flwildbeauty, all rights reserved, uploaded by flwildbeauty","desc":"Sabatia stellaris, with the common names rose of Plymouth, marsh pink, salt-marsh pink, and sea-pink; is a species of Sabatia. It has the synonym Sabatia maculata (Benth.) Benth. & Hook.f., Sabatia palmeri Gray, Sabatia purpusii Brandeg., Sabatia simulata Britt.).","fam":"Gentianaceae","ord":"Gentianales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":4946,"wiki":"https://en.wikipedia.org/wiki/Sabatia_stellaris","inat":126339},{"s":"E","c":"Northern arrowhead","sci":"Sagittaria cuneata","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/148892400/original.jpeg","attr":"(c) Brittney Miller, some rights reserved (CC BY-NC), uploaded by Brittney Miller","desc":"Sagittaria cuneata is a North American species of flowering plant in the water plantain family known by the common name arumleaf arrowhead or duck potato. Like some other Sagittaria species, it may be called wapato.","fam":"Alismataceae","ord":"Alismatales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":2420,"wiki":"https://en.wikipedia.org/wiki/Sagittaria_cuneata","inat":78925},{"s":"SC","c":"Awl-leaved arrowhead","sci":"Sagittaria subulata","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/59808160/original.jpg","attr":"(c) PA Natural Heritage Program PNHP, some rights reserved (CC BY-NC-SA)","desc":"Sagittaria subulata, the awl-leaf arrowhead, narrow-leaved arrowhead or dwarf sagittaria, is an aquatic plant species native to the Americas.","fam":"Alismataceae","ord":"Alismatales","cls":"Liliopsida","gr":"G4","sr":"SNR","obs":69,"wiki":"https://en.wikipedia.org/wiki/Sagittaria_subulata","inat":69817},{"s":"E","c":"Quill-leaved arrowhead","sci":"Sagittaria teres","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/249183386/original.jpeg","attr":"(c) doug_mcgrady, some rights reserved (CC BY-NC), uploaded by doug_mcgrady","desc":"Sagittaria teres, the quill-leaved arrowhead or slender arrowhead, is an aquatic plant species in the genus Sagittaria. It is a perennial herb up to 80 centimetres tall. The leaves can grow both under and above the water. The flowers are white, up to 1.5\u00a0cm in diameter, borne in one or more whorls on a stalk rising above the leaves.","fam":"Alismataceae","ord":"Alismatales","cls":"Liliopsida","gr":"G3","sr":"S1","obs":97,"wiki":"https://en.wikipedia.org/wiki/Sagittaria_teres","inat":168301},{"s":"E","c":"Sandbar willow","sci":"Salix exigua","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/23642240/original.jpg","attr":"(c) wyatthersey, some rights reserved (CC BY-NC)","desc":"Salix exigua is a species of willow native to most of North America except for the southeast and far north, occurring from Alaska east to New Brunswick, and south to northern Mexico. It is considered a threatened species in Massachusetts while in Connecticut, Maryland, and New Hampshire it is considered endangered.","fam":"Salicaceae","ord":"Malpighiales","cls":"Magnoliopsida","gr":"G5","sr":"","obs":14005,"wiki":"https://en.wikipedia.org/wiki/Salix_exigua","inat":59008},{"s":"E","c":"Bog willow","sci":"Salix pedicellaris","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/512935218/original.jpg","attr":"(c) Levi smith, some rights reserved (CC BY-NC), uploaded by Levi smith","desc":"Salix pedicellaris, the bog willow, is a species of willow. It grows as a shrub.","fam":"Salicaceae","ord":"Malpighiales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":965,"wiki":"https://en.wikipedia.org/wiki/Salix_pedicellaris","inat":168347},{"s":"SC","c":"Slender willow","sci":"Salix petiolaris","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/8986454/original.jpg","attr":"(c) Josh Sulman, all rights reserved, uploaded by Josh Sulman","desc":"Salix petiolaris, common name slender willow or meadow willow, is a species of willow.","fam":"Salicaceae","ord":"Malpighiales","cls":"Magnoliopsida","gr":"G5","sr":"SU","obs":3092,"wiki":"https://en.wikipedia.org/wiki/Salix_petiolaris","inat":54848},{"s":"E","c":"Lizard's tail","sci":"Saururus cernuus","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/391564513/original.jpeg","attr":"(c) Michael J. Papay, some rights reserved (CC BY), uploaded by Michael J. Papay","desc":"Saururus cernuus is a species of herbaceous perennial plant.","fam":"Saururaceae","ord":"Piperales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":20452,"wiki":"https://en.wikipedia.org/wiki/Saururus_cernuus","inat":60742},{"s":"E","c":"Pod grass","sci":"Scheuchzeria palustris ssp. americana","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/21566633/original.jpg","attr":"(c) Jukka Jantunen, some rights reserved (CC BY-NC), uploaded by Jukka Jantunen","desc":"Scheuchzeria palustris, is a flowering plant in the family Scheuchzeriaceae, in which there is only one species and Scheuchzeria is the only genus. In the APG II system it is placed in the order Alismatales of the monocots.","fam":"Scheuchzeriaceae","ord":"Alismatales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":3776,"wiki":"https://en.wikipedia.org/wiki/Scheuchzeria","inat":78991},{"s":"SC","c":"Purple oat","sci":"Schizachne purpurascens","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/5554989/original.jpeg","attr":"(c) Leanne Wallis, some rights reserved (CC BY-NC), uploaded by Leanne Wallis","desc":"Schizachne is a genus of Eurasian and North American plants in the grass family. The only accepted species is Schizachne purpurascens, commonly called false melic. Three subspecies are recognized:Schizachne purpurascens subsp. callosa (Turcz. ex Griseb.) T.Koyama & Kawano \u2013 European and Asiatic Russia, China, Mongolia, Korea, Kazakhstan\nSchizachne purpurascens subsp. capillipes (Kom.) Tzvelev \u2013 Kamchatka\nSchizachne purpurascens subsp. purpurascens \u2013 Canada, United States ","fam":"Poaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S3","obs":1493,"wiki":"https://en.wikipedia.org/wiki/Schizachne","inat":129497},{"s":"T","c":"Hard-stemmed bulrush","sci":"Schoenoplectus acutus","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/17377005/original.jpeg","attr":"(c) Sean Blaney, some rights reserved (CC BY-NC), uploaded by Sean Blaney","desc":"Schoenoplectus acutus, called tule, common tule, hardstem tule, tule rush, hardstem bulrush, or viscid bulrush, is a giant species of sedge in the plant family Cyperaceae, native to freshwater marshes all over North America. The common name derives from the N\u0101huatl word t\u014dllin, and it was first recognized by the early Spanish explorers and missionaries in New Spain who saw the marsh plants in the Central Valley of California as similar to those in the marshes around Mexico City being used to construct shelters by the indigenous inhabitants.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S2","obs":5702,"wiki":"https://en.wikipedia.org/wiki/Schoenoplectus_acutus","inat":59205},{"s":"T","c":"Torrey bulrush","sci":"Schoenoplectus torreyi","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/44429571/original.jpeg","attr":"(c) Alex Graeff, all rights reserved, uploaded by Alex Graeff","desc":"Schoenoplectus torreyi, common name Torrey bulrush or Torrey's bulrush, is a species of Schoenoplectus found in North America.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G4","sr":"S2","obs":201,"wiki":"https://en.wikipedia.org/wiki/Schoenoplectus_torreyi","inat":168634},{"s":"SC","c":"Chaffseed","sci":"Schwalbea americana","n":"","ext":true,"fed":"E","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/11101296/original.jpg","attr":"(c) dogtooth77, some rights reserved (CC BY-NC-SA)","desc":"Schwalbea americana, commonly known as American chaffseed, is the sole species currently classified in the genus Schwalbea. It is an erect, hemiparasitic, perennial herb in the family Orobanchaceae. It is native to the southeastern and Atlantic coastal United States where it is found in wet acidic grasslands. This species has declined tremendously from its historical range due to fire suppression, development and collection, and it is currently listed as an endangered species by the U.S. Fish and Wildlife Service.","fam":"Orobanchaceae","ord":"Lamiales","cls":"Magnoliopsida","gr":"G2","sr":"SH","obs":105,"wiki":"https://en.wikipedia.org/wiki/Schwalbea","inat":168637},{"s":"SC","c":"Georgia bulrush","sci":"Scirpus georgianus","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/48544520/original.jpeg","attr":"(c) agujaceratops, some rights reserved (CC BY), uploaded by agujaceratops","desc":"Scirpus georgianus, or Georgia bulrush, is a flowering plant in the family Cyperaceae that grows in much of the eastern half of North America. Its habitat is wet marshy field areas prone to seasonal flooding. It was described by Roland McMillan Harper.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":522,"wiki":"https://en.wikipedia.org/wiki/Scirpus_georgianus","inat":168644},{"s":"SC","c":"Long's bulrush","sci":"Scirpus longii","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/5863562/original.jpeg","attr":"(c) Sean Blaney, some rights reserved (CC BY-NC), uploaded by Sean Blaney","desc":"Scirpus longii is a species of flowering plant in the sedge family known by the common name Long's bulrush. It is native to eastern North America, where it is limited to the Atlantic coastal plain.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"","sr":"","obs":57,"wiki":"https://en.wikipedia.org/wiki/Scirpus_longii","inat":168646},{"s":"E","c":"Few-flowered nutrush","sci":"Scleria pauciflora var. caroliniana","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/57116278/original.jpg","attr":"(c) Peggy Romfh, some rights reserved (CC BY-NC), uploaded by Peggy Romfh","desc":"Scleria pauciflora, known as few-flowered nutrush, papillose nut-sedge, and Carolina-whipgrass, is a plant in the sedge family (Cyperaceae) native to northern Mexico, the eastern United States, southern Canada, and Cuba. It is common across a broad stretch of the southeastern United States in many different habitat types, becoming rare at the northern end of its distribution. It has been observed to occur in habitats such as pine savannas, wet and dry pine flatwoods, slashpine woods, and along boggy riverbanks.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"SNR","obs":465,"wiki":"https://en.wikipedia.org/wiki/Scleria_pauciflora","inat":168663},{"s":"E","c":"Reticulated nutrush","sci":"Scleria reticularis","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/2/28/Scleria_reticularis_BB-1913.png","attr":"Wikimedia Commons (CC BY-SA)","desc":"Scleria reticularis, also known as the reticulated nutrush or netted nutrush, is a plant in the sedge family Cyperaceae.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"","obs":0,"wiki":"https://en.wikipedia.org/wiki/Scleria_reticularis","inat":""},{"s":"E","c":"Whip nutrush","sci":"Scleria triglomerata","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/2131594/original.jpg","attr":"(c) dogtooth77, some rights reserved (CC BY-NC-SA)","desc":"Scleria triglomerata, also known as the whip nutrush, is a plant in the sedge family Cyperaceae.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":1528,"wiki":"https://en.wikipedia.org/wiki/Scleria_triglomerata","inat":141078},{"s":"SC","c":"Low nutrush","sci":"Scleria verticillata","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/24118207/original.jpeg","attr":"(c) Don Sutherland, some rights reserved (CC BY-NC), uploaded by Don Sutherland","desc":"Scleria verticillata, known as low nutrush or whorled nutrush, is a plant in the sedge family Cyperaceae. It is native to Ontario, Canada, the eastern United States, The Bahamas, and Cuba.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"SH","obs":521,"wiki":"https://en.wikipedia.org/wiki/Scleria_verticillata","inat":145496},{"s":"E","c":"Hyssop skullcap","sci":"Scutellaria integrifolia","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/77308222/original.jpg","attr":"(c) ranger-jenny, all rights reserved","desc":"Scutellaria integrifolia, commonly called helmet flower or helmet skullcap, is a flowering plant in the mint family. It is native to the eastern United States where it is found in openings in mesic, acidic soil. It likely requires disturbance in the form of fire to maintain its appropriate habitat.","fam":"Lamiaceae","ord":"Lamiales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":8471,"wiki":"https://en.wikipedia.org/wiki/Scutellaria_integrifolia","inat":127045},{"s":"E","c":"Small skullcap","sci":"Scutellaria parvula var. missouriensis","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/1740427/original.jpg","attr":"(c) Eric Hunt, all rights reserved","desc":"Scutellaria parvula, commonly known as the small skullcap, is a species of flowering plant in the mint family. It is native to eastern and central North America, ranging from Ontario and Quebec south and west through much of the eastern and central United States to Texas.","fam":"Lamiaceae","ord":"Lamiales","cls":"Magnoliopsida","gr":"","sr":"","obs":3429,"wiki":"https://en.wikipedia.org/wiki/Scutellaria_parvula","inat":129652},{"s":"E","c":"Sweet-scented Indian-plantain","sci":"Senecio suaveolens","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/4/44/Senecio_suaveolens_-_Sweet_Scented_Indian_Plantain.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Hasteola suaveolens, known by the common names false Indian plantain and sweet scented Indian plantain, is a perennial forb native to the northeastern and north-central United States. It is found from Massachusetts south to Virginia and North Carolina, and west as far as Minnesota and Minnesota and Missouri.","fam":"Asteraceae","ord":"Asterales","cls":"Magnoliopsida","gr":"","sr":"","obs":0,"wiki":"https://en.wikipedia.org/wiki/Hasteola_suaveolens","inat":""},{"s":"T","c":"Wild senna","sci":"Senna hebecarpa","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/47750663/original.jpeg","attr":"(c) Mark Kluge, some rights reserved (CC BY-NC), uploaded by Mark Kluge","desc":"Senna hebecarpa, with the common names American senna and wild senna, is a species of legume native to eastern North America.","fam":"Fabaceae","ord":"Fabales","cls":"Magnoliopsida","gr":"G5","sr":"S2","obs":7145,"wiki":"https://en.wikipedia.org/wiki/Senna_hebecarpa","inat":136373},{"s":"T","c":"Three-toothed cinquefoil","sci":"Sibbaldiopsis tridentata","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/43939553/original.jpeg","attr":"(c) Cade, all rights reserved, uploaded by Cade","desc":"Sibbaldia tridentata is a species in the plant family Rosaceae. Its synonyms include the illegitimate name Sibbaldia retusa and Sibbaldiopsis tridentata. Under the latter name, it has been treated as the only species in the genus Sibbaldiopsis. Its English names include three-toothed cinquefoil, shrubby fivefingers, and wineleaf.","fam":"Rosaceae","ord":"Rosales","cls":"Magnoliopsida","gr":"G5","sr":"S2","obs":11449,"wiki":"https://en.wikipedia.org/wiki/Sibbaldia_tridentata","inat":81595},{"s":"T","c":"Starry campion","sci":"Silene stellata","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/353169921/original.jpeg","attr":"(c) Michael J. Papay, some rights reserved (CC BY), uploaded by Michael J. Papay","desc":"Silene stellata, known by the common names starry campion, widow's frill, and whorled catchfly, is a perennial herbaceous summer forb with white flowers, native to the central and eastern United States. It grows in habitats such as forests, river flats, and tall grass prairies.","fam":"Caryophyllaceae","ord":"Caryophyllales","cls":"Magnoliopsida","gr":"G5","sr":"S2","obs":7525,"wiki":"https://en.wikipedia.org/wiki/Silene_stellata","inat":128942},{"s":"SC","c":"Bristly greenbriar","sci":"Smilax hispida","n":"","ext":true,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/7/77/Smilax_tamnoides_2009-05-24_01.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Smilax tamnoides, common name bristly greenbrier, is a North American species of plants native to the United States and Canada. It is widespread from Ontario and New York State south to Texas and Florida.","fam":"Smilacaceae","ord":"Liliales","cls":"Liliopsida","gr":"G5","sr":"SH","obs":0,"wiki":"https://en.wikipedia.org/wiki/Smilax_tamnoides","inat":""},{"s":"SC","c":"Early wrinkle-leaved goldenrod","sci":"Solidago aestivalis","n":"","ext":true,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/6/66/Solidago_rugosa_var_aspera.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Solidago rugosa, commonly called the wrinkleleaf goldenrod or rough-stemmed goldenrod, is a species of flowering plant in the family Asteraceae. It is native to North America, where it is widespread across eastern and central Canada and the eastern and central United States. It is usually found in wet to mesic habitats.","fam":"Asteraceae","ord":"Asterales","cls":"Magnoliopsida","gr":"T4","sr":"SH","obs":0,"wiki":"https://en.wikipedia.org/wiki/Solidago_rugosa","inat":""},{"s":"SC","c":"Elliott's goldenrod","sci":"Solidago latissimifolia","n":"","ext":true,"fed":"","img":"https://static.inaturalist.org/photos/26685912/original.jpeg","attr":"(c) Isaac Maxwell, all rights reserved, uploaded by Isaac Maxwell","desc":"Solidago latissimifolia, common name Elliott's goldenrod, is North American species of flowering plants in the family Asteraceae. It is native to the Atlantic Coast of the United States and Canada, from Nova Scotia south to Alabama and Florida.","fam":"Asteraceae","ord":"Asterales","cls":"Magnoliopsida","gr":"G4","sr":"S1","obs":144,"wiki":"https://en.wikipedia.org/wiki/Solidago_latissimifolia","inat":169111},{"s":"E","c":"Floating bur-reed","sci":"Sparganium fluctuans","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/21417586/original.jpg","attr":"(c) paulgelok, all rights reserved, uploaded by paulgelok","desc":"Sparganium fluctuans is a species of bur-reed found in North America known by the common name floating bur-reed. It is listed as endangered in Connecticut.","fam":"Typhaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":624,"wiki":"https://en.wikipedia.org/wiki/Sparganium_fluctuans","inat":169152},{"s":"E","c":"Small bur-reed","sci":"Sparganium natans","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/0/0c/Sparganium_natans.jpeg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Sparganium natans is a species of bur-reed known by the common names least bur-reed and small bur-reed. It is a water circumboreal plant inhabiting North America, Europe, West Asia and Japan. It is usually found submersed in shallow, calm water. This bur-reed has thin, flexible, grasslike leaves which float in the water. Plants that spend more time out of water at the waterline are tougher and have shorter leaves. The plant bears two inflorescences, the staminate type being a rounded white filamentous ball and the pistillate type a sphere of thick, green, pointy peduncles. The fruits are small green or brown achenes.","fam":"Typhaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":0,"wiki":"https://en.wikipedia.org/wiki/Sparganium_natans","inat":""},{"s":"T","c":"Canada sand-spurry","sci":"Spergularia canadensis","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/417067218/original.jpeg","attr":"(c) Mike Zifkin, some rights reserved (CC BY), uploaded by Mike Zifkin","desc":"Spergularia canadensis is a species of flowering plant in the family Caryophyllaceae, known by the common name Canadian sandspurry. It is native to North America, where it is known from mainly coastal habitat. It is found along the coastline of Canada and northern parts of the United States, from Alaska to northern California on the West Coast, and as far south as New York on the East Coast.","fam":"Caryophyllaceae","ord":"Caryophyllales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":469,"wiki":"https://en.wikipedia.org/wiki/Spergularia_canadensis","inat":79168},{"s":"SC","c":"Little ladies'-tresses","sci":"Spiranthes tuberosa var. grayi","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/323158729/original.jpg","attr":"(c) Nicholas Wei, some rights reserved (CC BY-SA), uploaded by Nicholas Wei","desc":"Spiranthes tuberosa, commonly called little lady's tresses, little pearl-twist and slender ladies'-tresses is an orchid species. It is a perennial plant native to North America.","fam":"Orchidaceae","ord":"Asparagales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":1466,"wiki":"https://en.wikipedia.org/wiki/Spiranthes_tuberosa","inat":169276},{"s":"E","c":"Rough dropseed","sci":"Sporobolus clandestinus","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/99254490/original.jpeg","attr":"(c) Kathy McAleese, some rights reserved (CC BY-NC-ND), uploaded by Kathy McAleese","desc":"Sporobolus clandestinus, common names rough dropseed and rough rushgrass, is a species of grass found in North America. It is listed as endangered in Connecticut, Maryland, New York, and Pennsylvania and listed as threatened in Kentucky.","fam":"Poaceae","ord":"Poales","cls":"Liliopsida","gr":"G4","sr":"S1","obs":124,"wiki":"https://en.wikipedia.org/wiki/Sporobolus_clandestinus","inat":169288},{"s":"T","c":"Sand dropseed","sci":"Sporobolus cryptandrus","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/322509463/original.jpg","attr":"(c) Keir Morse, some rights reserved (CC BY-NC-ND), uploaded by Keir Morse","desc":"Sporobolus cryptandrus, commonly known as sand dropseed, is a species of grass in the family Poaceae. It is native to North America, where it is widespread in southern Canada, most of the United States, and northern Mexico.","fam":"Poaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":3118,"wiki":"https://en.wikipedia.org/wiki/Sporobolus_cryptandrus","inat":79185},{"s":"E","c":"Northern dropseed","sci":"Sporobolus heterolepis","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/158094846/original.jpg","attr":"(c) Adam Thada, all rights reserved, uploaded by Adam Thada","desc":"Sporobolus heterolepis, commonly known as prairie dropseed, is a species of prairie grass native to the tallgrass and mixed grass prairies of central North America from Texas to southern Canada. It is also found further east, to the Atlantic coast of the United States and Canada, but is much less common beyond the Great Plains and is restricted to specialized habitats. It is found in 27 states and four Canadian provinces.","fam":"Poaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":3701,"wiki":"https://en.wikipedia.org/wiki/Sporobolus_heterolepis","inat":120557},{"s":"E","c":"Small dropseed","sci":"Sporobolus neglectus","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/9856210/original.jpeg","attr":"(c) Colin Chapman-Lam, some rights reserved (CC BY-NC), uploaded by Colin Chapman-Lam","desc":"Sporobolus neglectus, common names small dropseed, small rushgrass, and puffsheath dropseed, is a plant found in North America. It is listed as endangered in Connecticut, Massachusetts, New Hampshire and New Jersey. It is listed is as endangered and extirpated in Maryland and as possibly extirpated in Maine.","fam":"Poaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":173,"wiki":"https://en.wikipedia.org/wiki/Sporobolus_neglectus","inat":169298},{"s":"T","c":"Hispid hedge-nettle","sci":"Stachys hispida","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/957219/original.JPG","attr":"(c) Mark Kluge, some rights reserved (CC BY-NC), uploaded by Mark Kluge","desc":"Stachys hispida, commonly known as hispid hedgenettle, is a species of flowering plant in the mint family (Lamiaceae). It is native to eastern North America, where it is found in Canada and the United States. Its natural habitat is in moist areas, such as alluvial banks, bottomland forests, and wet meadows.","fam":"Lamiaceae","ord":"Lamiales","cls":"Magnoliopsida","gr":"","sr":"","obs":2663,"wiki":"https://en.wikipedia.org/wiki/Stachys_hispida","inat":204419},{"s":"E","c":"Hyssop-leaf hedge-nettle","sci":"Stachys hyssopifolia","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/21425341/original.jpg","attr":"(c) Nate Martineau, some rights reserved (CC BY-NC), uploaded by Nate Martineau","desc":"Stachys hyssopifolia, commonly known as hyssop-leaf hedge-nettle, rough hedge-nettle hyssop-leaved hedgenettle, and hyssop hedge-nettle is a species of flowering plant in the mint family (Lamiaceae).","fam":"Lamiaceae","ord":"Lamiales","cls":"Magnoliopsida","gr":"G4","sr":"S1","obs":271,"wiki":"https://en.wikipedia.org/wiki/Stachys_hyssopifolia","inat":169317},{"s":"SC","c":"Northern stitchwort","sci":"Stellaria borealis","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/86574966/original.jpg","attr":"(c) Steven Daniel, all rights reserved, uploaded by Steven Daniel","desc":"Stellaria borealis is a species of flowering plant in the family Caryophyllaceae known by the common name boreal starwort. It has a circumboreal distribution, occurring throughout northern areas of the Northern Hemisphere. It occurs in many types of moist and wet habitat, including marshes, riverbanks, lakesides, floodplains, talus, ditches, and moist spots in forests and woodlands. It is quite variable in appearance, especially across subspecies. In general, it is a rhizomatous perennial herb forming mats of branching, four-angled stems lined with lance-shaped leaves a few centimeters in length. The inflorescence bears many flowers each with five deeply lobed white petals. Some flowers lack petals and have only the five pointed green sepals.","fam":"Caryophyllaceae","ord":"Caryophyllales","cls":"Magnoliopsida","gr":"G5","sr":"SU","obs":480,"wiki":"https://en.wikipedia.org/wiki/Stellaria_borealis","inat":79199},{"s":"T","c":"White mandarin","sci":"Streptopus amplexifolius","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/151898177/original.jpeg","attr":"(c) olgaaseeva, some rights reserved (CC BY-NC)","desc":"Streptopus amplexifolius is a species of flowering plant in the family Liliaceae, native to North America, Europe and Asia.","fam":"Liliaceae","ord":"Liliales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":13756,"wiki":"https://en.wikipedia.org/wiki/Streptopus_amplexifolius","inat":79273},{"s":"SC","c":"Crooked-stem aster","sci":"Symphyotrichum prenanthoides","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/11816687/original.jpeg","attr":"(c) Julie, some rights reserved (CC BY-NC), uploaded by Julie","desc":"Symphyotrichum prenanthoides is a species of flowering plant in the family Asteraceae known by the common name crookedstem aster. It is native to northcentral and northeastern North America.","fam":"Asteraceae","ord":"Asterales","cls":"Magnoliopsida","gr":"G5","sr":"SH","obs":4382,"wiki":"https://en.wikipedia.org/wiki/Symphyotrichum_prenanthoides","inat":146705},{"s":"E","c":"Yellow pimpernel","sci":"Taenidia integerrima","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/20567134/original.jpg","attr":"(c) L Bet Crooks T, some rights reserved (CC BY-NC), uploaded by L Bet Crooks T","desc":"Taenidia integerrima, the yellow pimpernel, is an herbaceous plant in the parsley family. It is native to the eastern North America, where it is widespread. Its natural habitat is rocky prairies and woodlands, often over calcareous substrates. It is a perennial.","fam":"Apiaceae","ord":"Apiales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":3568,"wiki":"https://en.wikipedia.org/wiki/Taenidia_integerrima","inat":130364},{"s":"T","c":"Northern white cedar","sci":"Thuja occidentalis","n":"(native populations only)","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/4684247/original.jpeg","attr":"(c) Donna Pomeroy, some rights reserved (CC BY-NC), uploaded by Donna Pomeroy","desc":"Thuja occidentalis, also known as northern white-cedar, eastern white-cedar, or arborvitae, is an evergreen coniferous tree, in the cypress family Cupressaceae, which is native to eastern Canada and much of the north-central and northeastern United States. It is widely cultivated as an ornamental plant. It is not to be confused with Juniperus virginiana.","fam":"Cupressaceae","ord":"Pinales","cls":"Pinopsida","gr":"G5","sr":"S2","obs":58606,"wiki":"https://en.wikipedia.org/wiki/Thuja_occidentalis","inat":54037},{"s":"SC","c":"Appalachian gametophyte","sci":"Trichomanes intricatum","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/1/1b/Trichomanes_intricatum2-BobKlips.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Crepidomanes intricatum, synonym Trichomanes intricatum, is known as the weft fern. The genus Crepidomanes is accepted in the Pteridophyte Phylogeny Group classification of 2016, but not by some other sources. As of October\u00a02019, Plants of the World Online sank the genus into a broadly defined Trichomanes, treating this species as Trichomanes intricatum.","fam":"Hymenophyllaceae","ord":"Hymenophyllales","cls":"Polypodiopsida","gr":"","sr":"","obs":0,"wiki":"https://en.wikipedia.org/wiki/Crepidomanes_intricatum","inat":""},{"s":"SC","c":"Alpine bulrush","sci":"Trichophorum alpinum","n":"","ext":true,"fed":"","img":"https://static.inaturalist.org/photos/286499777/original.jpg","attr":"(c) \u041e\u043b\u044c\u0433\u0430 \u041b\u0435\u0441\u043d\u0430\u044f, all rights reserved, uploaded by \u041e\u043b\u044c\u0433\u0430 \u041b\u0435\u0441\u043d\u0430\u044f","desc":"Trichophorum alpinum, commonly known as alpine bulrush or cotton deergrass, is a species of flowering plant in the sedge family. It has a circumboreal distribution, occurring throughout the northern latitudes of the Northern Hemisphere. It is present in Europe, Asia, and northern North America.","fam":"Cyperaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"SH","obs":2429,"wiki":"https://en.wikipedia.org/wiki/Trichophorum_alpinum","inat":57491},{"s":"E","c":"False pennyroyal","sci":"Trichostema brachiatum","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/2/2a/Trichostema_brachiatum.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Trichostema brachiatum, commonly known as fluxweed or false pennyroyal, is a species of plant endemic to North America.","fam":"Lamiaceae","ord":"Lamiales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":0,"wiki":"https://en.wikipedia.org/wiki/Trichostema_brachiatum","inat":""},{"s":"E","c":"Narrow-leaved horse gentian","sci":"Triosteum angustifolium","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/122232882/original.jpg","attr":"(c) Marie Gerard, all rights reserved, uploaded by Marie Gerard","desc":"Triosteum angustifolium, commonly known as yellowfruit horse-gentian, is a species of flowering plant belonging to the family Caprifoliaceae. It is found Eastern North America, primarily in Limestone regions.","fam":"Caprifoliaceae","ord":"Dipsacales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":212,"wiki":"https://en.wikipedia.org/wiki/Triosteum_angustifolium","inat":170012},{"s":"E","c":"Nodding pogonia","sci":"Triphora trianthophora","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/2/28/Threebirds_%28Triphora_trianthophoros%29_%2817643671299%29.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Triphora trianthophoros, the threebirds or three birds orchid, or nodding pogonia, is a species of terrestrial orchid native to eastern North America.","fam":"Orchidaceae","ord":"Asparagales","cls":"Liliopsida","gr":"G4","sr":"S1","obs":0,"wiki":"https://en.wikipedia.org/wiki/Triphora_trianthophoros","inat":""},{"s":"E","c":"Narrow false oats","sci":"Trisetum spicatum","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/f/f1/Trisetum_spicatum_%283938670853%29.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Trisetum spicatum is a species of grass known by the common name spike trisetum and spike false oat. It is native to North America, Eurasia, and South America. In North America it occurs throughout northern regions, including northern sections of the United States and most all of Canada, its range continuing to Greenland. It is widespread throughout the Canadian Arctic Islands. The grass occurs in a variety of Arctic and alpine habitat types, as well as many types of mountainous habitat in regions further south. It is a perennial grass forming clumps of upright stems ranging in height from a few centimeters to over one meter. The narrow leaves are mostly located around the bases of the densely clumped stems. The inflorescence is a narrow spike a few centimeters long or up to 30 to 50 centimeters in maximum length. The spikes are green to purple or brownish and shiny.","fam":"Poaceae","ord":"Poales","cls":"Liliopsida","gr":"TNR","sr":"","obs":0,"wiki":"https://en.wikipedia.org/wiki/Trisetum_spicatum","inat":""},{"s":"T","c":"Spreading globe flower","sci":"Trollius laxus","n":"","ext":false,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/0/02/Globeflower_Trollius_laxus_Flower_2400px.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Trollius laxus is a rare flowering plant species in the buttercup family, Ranunculaceae. It is native to North America and is considered to have two subspecies, one with a distribution is the east and one in the west. Common names for Trollius laxus include American globeflower and American spreading globeflower. The American Globeflower, Trollius laxus is an endangered species of flowering plants Native to Northeastern United States. This species of plants is\u00a0limited in range by their ability to exclusively survive in wetlands and marshes. Thus, clusters of the species are constantly threatened by the ever-changing hydrology of the range they are confined to.","fam":"Ranunculaceae","ord":"Ranunculales","cls":"Magnoliopsida","gr":"G5","sr":"","obs":0,"wiki":"https://en.wikipedia.org/wiki/Trollius_laxus","inat":""},{"s":"E","c":"Resupinate bladderwort","sci":"Utricularia resupinata","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/4279880/original.jpg","attr":"(c) Jerry Oldenettel, some rights reserved (CC BY-NC-SA)","desc":"Utricularia resupinata, popularly known as lavender bladderwort or northeastern bladderwort, is a small perennial subaquatic carnivorous plant that belongs to the genus Utricularia. It is native to eastern Canada, the United States, and Central America. This plant species has an interesting etymology, growth pattern, ecology, and research history. As a plant that is threatened or endangered in many of the States where it is found, it is a candidate for sound conservation efforts.","fam":"Lentibulariaceae","ord":"Lamiales","cls":"Magnoliopsida","gr":"G4","sr":"S1","obs":540,"wiki":"https://en.wikipedia.org/wiki/Utricularia_resupinata","inat":170091},{"s":"E","c":"Large-flowered bellwort","sci":"Uvularia grandiflora","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/96536/original.jpg","attr":"(c) JanetandPhil, some rights reserved (CC BY-NC-ND)","desc":"Uvularia grandiflora, the large-flowered bellwort or merrybells, is a species of flowering plant in the family Colchicaceae, native to eastern and central North America.","fam":"Colchicaceae","ord":"Liliales","cls":"Liliopsida","gr":"G5","sr":"S1","obs":21680,"wiki":"https://en.wikipedia.org/wiki/Uvularia_grandiflora","inat":126749},{"s":"E","c":"Velvetleaf blueberry","sci":"Vaccinium myrtilloides","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/136191767/original.jpg","attr":"(c) Michelle Holland, some rights reserved (CC BY-NC), uploaded by Michelle Holland","desc":"Vaccinium myrtilloides is a North American species of blueberry with common names including common blueberry, velvetleaf huckleberry, velvetleaf blueberry, Canadian blueberry, and sourtop blueberry.","fam":"Ericaceae","ord":"Ericales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":9507,"wiki":"https://en.wikipedia.org/wiki/Vaccinium_myrtilloides","inat":52741},{"s":"SC","c":"Mountain cranberry","sci":"Vaccinium vitis-idaea ssp. minus","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/32657295/original.jpg","attr":"(c) Andy Fyon, some rights reserved (CC BY-NC), uploaded by Andy Fyon","desc":"Vaccinium vitis-idaea is a small evergreen shrub in the heath family, Ericaceae. It is known colloquially as the lingonberry, partridgeberry, foxberry, mountain cranberry, or cowberry. It is native to boreal forest and Arctic tundra throughout the Northern Hemisphere. Commercially cultivated in the United States Pacific Northwest and the Netherlands, the edible berries are also picked in the wild and used in various dishes, especially in Nordic cuisine, and among many other cuisines around the world.","fam":"Ericaceae","ord":"Ericales","cls":"Magnoliopsida","gr":"G5","sr":"SNR","obs":56153,"wiki":"https://en.wikipedia.org/wiki/Vaccinium_vitis-idaea","inat":56312},{"s":"SC","c":"Beaked corn-salad","sci":"Valerianella radiata","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/6784839/original.jpeg","attr":"(c) Kimberlie Sasan, some rights reserved (CC BY-ND), uploaded by Kimberlie Sasan","desc":"Valeriana woodsiana, common name beaked cornsalad, is a plant native to the United States. It is an annual self pollinating flowering plant and besides being edible there are no known uses. Valerianella radiata flowers from April to May.","fam":"Caprifoliaceae","ord":"Dipsacales","cls":"Magnoliopsida","gr":"G5","sr":"SH","obs":11335,"wiki":"https://en.wikipedia.org/wiki/Valeriana_woodsiana","inat":82819},{"s":"SC","c":"Hybrid bunchflower","sci":"Veratrum latifolium","n":"","ext":true,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/2/22/Veratrum_hybridum_%28as_Melanthium_latifolium%29_BB-1913.png","attr":"Wikimedia Commons (CC BY-SA)","desc":"Veratrum hybridum is a species of flowering plant in the Melanthiaceae known by the common names slender bunchflower and crisped bunchflower. Many publications use the synonyms Melanthium latifolium and Veratrum latifolium, but the \"hybridum\" epithet is 9 years older than the \"latifolium,\" so Veratrum hybridum is now the accepted name.","fam":"Melanthiaceae","ord":"Liliales","cls":"Liliopsida","gr":"","sr":"","obs":0,"wiki":"https://en.wikipedia.org/wiki/Veratrum_hybridum","inat":""},{"s":"SC","c":"Narrow-leaved vervain","sci":"Verbena simplex","n":"","ext":true,"fed":"","img":"https://static.inaturalist.org/photos/337652/original.jpg","attr":"(c) Eric Hunt, all rights reserved","desc":"Verbena simplex is a species of flowering plant in the vervain family, Verbenaceae. It is commonly known as narrowleaf vervain, and is a perennial herbaceous plant. It is native to central and eastern North America where it is found in open, dry, habitats on calcareous soil. It produces lavender flowers in the summer.","fam":"Verbenaceae","ord":"Lamiales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":2932,"wiki":"https://en.wikipedia.org/wiki/Verbena_simplex","inat":170159},{"s":"SC","c":"Possum haw","sci":"Viburnum nudum","n":"","ext":true,"fed":"","img":"https://upload.wikimedia.org/wikipedia/commons/7/74/Viburnum_nudum_10zz.jpg","attr":"Wikimedia Commons (CC BY-SA)","desc":"Viburnum nudum is a deciduous shrub in the genus Viburnum within the muskroot family, Adoxaceae.","fam":"Viburnaceae","ord":"Dipsacales","cls":"Magnoliopsida","gr":"G5","sr":"SH","obs":0,"wiki":"https://en.wikipedia.org/wiki/Viburnum_nudum","inat":""},{"s":"T","c":"Smooth black-haw","sci":"Viburnum prunifolium","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/35211762/original.jpg","attr":"no rights reserved, uploaded by mefisher","desc":"Viburnum prunifolium is a species of Viburnum native to eastern North America, from Connecticut west to eastern Kansas, and south to Alabama and Texas.","fam":"Viburnaceae","ord":"Dipsacales","cls":"Magnoliopsida","gr":"G5","sr":"S2","obs":23092,"wiki":"https://en.wikipedia.org/wiki/Viburnum_prunifolium","inat":129977},{"s":"E","c":"Hook-spurred violet","sci":"Viola adunca","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/192684110/original.jpg","attr":"(c) Larry Halverson, all rights reserved, uploaded by Larry Halverson","desc":"Viola adunca is a species of violet known by the common names hookedspur violet, early blue violet, sand violet, and western dog violet. It is native to meadows and forests of western North America, Canada, and the northern contiguous United States.","fam":"Violaceae","ord":"Malpighiales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":17241,"wiki":"https://en.wikipedia.org/wiki/Viola_adunca","inat":53328},{"s":"E","c":"Coast violet","sci":"Viola brittoniana","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/51587898/original.jpeg","attr":"(c) mhough, some rights reserved (CC BY-NC), uploaded by mhough","desc":"Viola brittoniana, known as coast violet, northern coastal violet and Britton's violet, is a rare, acaulescent blue-flowered violet that is endemic to the eastern United States. It has distinctive leaves with narrow lobes and deep sinuses. It is a perennial.","fam":"Violaceae","ord":"Malpighiales","cls":"Magnoliopsida","gr":"G3","sr":"S1","obs":164,"wiki":"https://en.wikipedia.org/wiki/Viola_brittoniana","inat":170233},{"s":"SC","c":"Canada violet","sci":"Viola canadensis","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/125678/original.jpg","attr":"(c) Katja Schulz, some rights reserved (CC BY)","desc":"Viola canadensis is a flowering plant in the Violaceae family. It is commonly known as Canadian white violet, Canada violet, tall white violet, or white violet. It is widespread across much of Canada and the United States, from Alaska to Newfoundland, south as far as Georgia and Arizona. It is a perennial herb and the Latin-specific epithet canadensis means of Canada.","fam":"Violaceae","ord":"Malpighiales","cls":"Magnoliopsida","gr":"G5","sr":"S3","obs":19340,"wiki":"https://en.wikipedia.org/wiki/Viola_canadensis","inat":70010},{"s":"SC","c":"Southern wood violet","sci":"Viola hirsutula","n":"","ext":true,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/7913621/original.jpg","attr":"no rights reserved, uploaded by Lori B","desc":"Viola hirsutula, common name southern woodland violet, is a perennial species of violet found in the eastern United States.","fam":"Violaceae","ord":"Malpighiales","cls":"Magnoliopsida","gr":"G5","sr":"SH","obs":2484,"wiki":"https://en.wikipedia.org/wiki/Viola_hirsutula","inat":170244},{"s":"SC","c":"Northern bog violet","sci":"Viola nephrophylla","n":"","ext":false,"fed":"","img":"https://static.inaturalist.org/photos/31720678/original.jpeg","attr":"(c) Corey, all rights reserved, uploaded by Corey","desc":"Viola nephrophylla syn. Viola nephrophylla Greene f. albinea (Farw.), Viola pratincola Greene, Viola retusa Greene, is an annual or perennial forb in the Violet family (Violaceae) native to North America.","fam":"Violaceae","ord":"Malpighiales","cls":"Magnoliopsida","gr":"G5","sr":"S2","obs":2003,"wiki":"https://en.wikipedia.org/wiki/Viola_nephrophylla","inat":79513},{"s":"E","c":"Kidney-leaf white violet","sci":"Viola renifolia","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/3942233/original.jpg","attr":"(c) Cindy Kilpatrick, some rights reserved (CC BY)","desc":"Viola renifolia is a species of violet known by the common names white violet and kidneyleaf violet. It is native to northern North America, where it has a widespread distribution across Canada and the northern United States as far south as Washington, Colorado, and New York.","fam":"Violaceae","ord":"Malpighiales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":2382,"wiki":"https://en.wikipedia.org/wiki/Viola_renifolia","inat":170258},{"s":"SC","c":"Great-spurred violet","sci":"Viola selkirkii","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/38324317/original.jpg","attr":"(c) Erik Danielsen, some rights reserved (CC BY-NC), uploaded by Erik Danielsen","desc":"Viola selkirkii is a species of violet known by the common names Selkirk's violet and great-spur violet. It is native throughout the Northern Hemisphere, its distribution circumboreal.","fam":"Violaceae","ord":"Malpighiales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":2123,"wiki":"https://en.wikipedia.org/wiki/Viola_selkirkii","inat":170260},{"s":"E","c":"Barren strawberry","sci":"Waldsteinia fragarioides","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/474194373/original.jpg","attr":"(c) Ryan Hodnett, some rights reserved (CC BY-SA)","desc":"Waldsteinia fragarioides (syn. Dalibarda fragarioides Michx. and Geum fragarioides,  also called Appalachian barren strawberry, or just barren strawberry, is a low, spreading plant with showy yellow flowers that appear in early spring. This plant is often used as an underplanting in perennial gardens.","fam":"Rosaceae","ord":"Rosales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":5190,"wiki":"https://en.wikipedia.org/wiki/Waldsteinia_fragarioides","inat":894458},{"s":"T","c":"Northern yellow-eyed grass","sci":"Xyris montana","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/73582611/original.jpg","attr":"(c) Joshua Mayer, some rights reserved (CC BY-SA)","desc":"Xyris montana, the northern yelloweyed grass, is a perennial herbaceous flowering plant in the family Xyridaceae. It grows in eastern and central Canada and in the northeastern and north-central United States.","fam":"Xyridaceae","ord":"Poales","cls":"Liliopsida","gr":"G5","sr":"S2","obs":353,"wiki":"https://en.wikipedia.org/wiki/Xyris_montana","inat":170370},{"s":"E","c":"Small's yellow-eyed","sci":"Xyris smalliana","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/29086779/original.jpg","attr":"(c) keesling3, some rights reserved (CC BY-NC), uploaded by keesling3","desc":"Xyris smalliana, Small's yelloweyed grass, is a North American species of flowering plants in the yellow-eyed-grass family. It grows on the coastal plain of the eastern and southern United States from Maine to Texas, as well as in Cuba, Central America, and the State of Tabasco in southern Mexico.","fam":"Xyridaceae","ord":"Poales","cls":"Liliopsida","gr":"G4","sr":"S1","obs":403,"wiki":"https://en.wikipedia.org/wiki/Xyris_smalliana","inat":170375},{"s":"E","c":"Golden Alexanders","sci":"Zizia aptera","n":"","ext":false,"fed":"","img":"https://inaturalist-open-data.s3.amazonaws.com/photos/75570328/original.jpeg","attr":"(c) psweet, some rights reserved (CC BY-SA), uploaded by psweet","desc":"Zizia aptera is a flowering plant native to North America. Its common names include meadow zizia, golden alexanders, heart leaved golden alexanders, and prairie golden alexanders.","fam":"Apiaceae","ord":"Apiales","cls":"Magnoliopsida","gr":"G5","sr":"S1","obs":4960,"wiki":"https://en.wikipedia.org/wiki/Zizia_aptera","inat":119795}];